    @staticmethod
    def _window_owns_focus(window: tk.Toplevel, widget: tk.Misc | None) -> bool:
        """Return whether ``widget`` belongs to one exact utility window."""

        if widget is None:
            return False
        try:
            return widget is window or str(widget).startswith(f"{window}.")
        except Exception:
            return False

    def _new_toplevel(
        self,
        parent: tk.Misc,
        *,
        role: str,
    ) -> tk.Toplevel:
        """Create a Toplevel with one explicit, future-proof chrome role.

        The native wrapper does not reliably exist until Tk maps the window, so
        the policy runs on ``<Map>`` and once after idle.  Its exact-HWND
        receipt makes both paths idempotent while still handling a wrapper that
        Tk recreates after a withdraw/deiconify cycle.
        """

        window = tk.Toplevel(parent)
        window._talkdat_chrome_role = role  # type: ignore[attr-defined]

        def apply(event: tk.Event | None = None) -> None:
            if event is not None and event.widget is not window:
                return
            try:
                apply_window_chrome(window, role)
            except Exception:
                # Chrome is decoration. A platform API failure must never stop
                # a microphone control, menu, or utility from opening.
                log.debug("native window chrome skipped", exc_info=True)

        with contextlib.suppress(Exception):
            window.bind("<Map>", apply, add="+")
        with contextlib.suppress(Exception):
            window.after_idle(apply)
        return window

    @staticmethod
    def _native_toplevel_handle(window: tk.Toplevel) -> int:
        """Resolve Tk's client handle to the pointer-safe outer desktop HWND."""

        return native_toplevel_handle(window)

    @staticmethod
    def _screen_reader_is_active() -> bool:
        """Fail safe when Windows reports an assistive screen reader session."""

        if sys.platform != "win32":
            return True
        try:
            active = wintypes.BOOL()
            spi_getscreenreader = 0x0046
            if not ctypes.windll.user32.SystemParametersInfoW(
                spi_getscreenreader,
                0,
                ctypes.byref(active),
                0,
            ):
                return True
            return bool(active.value)
        except Exception:
            return True

    @staticmethod
    def _set_dwm_cloak(hwnd: int, cloaked: bool) -> bool:
        """Set and verify application-owned DWM cloaking for one HWND."""

        if sys.platform != "win32" or not hwnd:
            return False
        try:
            dwmapi = ctypes.windll.dwmapi
            set_attribute = dwmapi.DwmSetWindowAttribute
            get_attribute = dwmapi.DwmGetWindowAttribute
            set_attribute.argtypes = (
                wintypes.HWND,
                wintypes.DWORD,
                ctypes.c_void_p,
                wintypes.DWORD,
            )
            set_attribute.restype = ctypes.c_long
            get_attribute.argtypes = set_attribute.argtypes
            get_attribute.restype = ctypes.c_long
            dwmwa_cloak = 13
            dwmwa_cloaked = 14
            requested = wintypes.BOOL(bool(cloaked))
            if int(set_attribute(
                wintypes.HWND(hwnd),
                dwmwa_cloak,
                ctypes.byref(requested),
                ctypes.sizeof(requested),
            )) != 0:
                return False
            state = wintypes.DWORD()
            if int(get_attribute(
                wintypes.HWND(hwnd),
                dwmwa_cloaked,
                ctypes.byref(state),
                ctypes.sizeof(state),
            )) != 0:
                return False
            dwm_cloaked_app = 0x00000001
            is_app_cloaked = bool(int(state.value) & dwm_cloaked_app)
            return is_app_cloaked if cloaked else not is_app_cloaked
        except Exception:
            return False

    def _eligible_focus_return_window(self, candidate: int) -> int:
        """Normalize a safe, visible external window that can receive focus."""

        if sys.platform != "win32" or not candidate:
            return 0
        try:
            user32 = ctypes.windll.user32
            root = int(user32.GetAncestor(int(candidate), 2)) or int(candidate)
            if (
                not root
                or root in self._own_window_handles()
                or not user32.IsWindow(root)
                or not user32.IsWindowVisible(root)
                or not user32.IsWindowEnabled(root)
                or user32.IsIconic(root)
            ):
                return 0
            process_id = wintypes.DWORD()
            user32.GetWindowThreadProcessId(root, ctypes.byref(process_id))
            if int(process_id.value) in {0, os.getpid()}:
                return 0
            gwl_exstyle = -20
            ws_ex_noactivate = 0x08000000
            ws_ex_toolwindow = 0x00000080
            ws_ex_appwindow = 0x00040000
            exstyle = int(user32.GetWindowLongW(root, gwl_exstyle))
            if exstyle & (ws_ex_noactivate | ws_ex_toolwindow):
                return 0
            gw_owner = 4
            if int(user32.GetWindow(root, gw_owner) or 0) and not (exstyle & ws_ex_appwindow):
                return 0
            class_name = self._foreground_class_name(root)
            if class_name in {
                "DV2ControlHost",
                "IME",
                "Progman",
                "Shell_SecondaryTrayWnd",
                "Shell_TrayWnd",
                "tooltips_class32",
                "WorkerW",
            }:
                return 0
            if int(user32.GetWindowTextLengthW(root) or 0) <= 0:
                return 0

            rect = wintypes.RECT()
            if not user32.GetWindowRect(root, ctypes.byref(rect)):
                return 0
            if rect.right <= rect.left or rect.bottom <= rect.top:
                return 0
            virtual_left = int(user32.GetSystemMetrics(76))
            virtual_top = int(user32.GetSystemMetrics(77))
            virtual_right = virtual_left + max(1, int(user32.GetSystemMetrics(78)))
            virtual_bottom = virtual_top + max(1, int(user32.GetSystemMetrics(79)))
            if (
                rect.right <= virtual_left
                or rect.left >= virtual_right
                or rect.bottom <= virtual_top
                or rect.top >= virtual_bottom
            ):
                return 0

            dwmapi = ctypes.windll.dwmapi
            get_attribute = dwmapi.DwmGetWindowAttribute
            get_attribute.argtypes = (
                wintypes.HWND,
                wintypes.DWORD,
                ctypes.c_void_p,
                wintypes.DWORD,
            )
            get_attribute.restype = ctypes.c_long
            dwmwa_cloaked = 14
            cloak_state = wintypes.DWORD()
            if int(get_attribute(
                wintypes.HWND(root),
                dwmwa_cloaked,
                ctypes.byref(cloak_state),
                ctypes.sizeof(cloak_state),
            )) != 0 or int(cloak_state.value) != 0:
                return 0
            return root
        except Exception:
            return 0

    def _utility_focus_return_window(self, window: tk.Toplevel) -> int:
        """Find the ordinary app beneath a borderless Talk DAT! utility."""

        for remembered in (
            getattr(window, "_talkdat_focus_return_hwnd", 0),
            getattr(self, "context_menu_target_hwnd", 0),
        ):
            candidate = self._eligible_focus_return_window(int(remembered or 0))
            if candidate:
                return candidate
        if sys.platform != "win32":
            return 0
        try:
            user32 = ctypes.windll.user32
            cursor = self._native_toplevel_handle(window)
            gw_hwndnext = 2
            for _index in range(192):
                cursor = int(user32.GetWindow(cursor, gw_hwndnext) or 0)
                if not cursor:
                    break
                candidate = self._eligible_focus_return_window(cursor)
                if candidate:
                    return candidate
        except Exception:
            pass
        return 0

    def _try_dwm_cloak_utility(self, window: tk.Toplevel) -> bool:
        """Hide a heavy utility without making Tk unmap and rebuild its tree.

        A cloaked HWND remains composed, which turns Settings restore from a
        hundreds-of-milliseconds remap into a sub-frame operation. Screen-reader
        sessions retain native minimization because UI Automation can still
        enumerate a cloaked HWND. Focus transfer and verified DWM readback are
        mandatory; any doubt returns to the ordinary Windows minimize path.
        """

        if sys.platform != "win32" or self._screen_reader_is_active():
            return False
        try:
            if not window.winfo_viewable():
                return False
        except Exception:
            return False
        focus_target = self._utility_focus_return_window(window)
        if not focus_target:
            return False

        handles: list[int] = []
        rail = getattr(window, "_menu_rail", None)
        try:
            if rail is not None and rail.winfo_exists() and rail.winfo_viewable():
                rail_hwnd = self._native_toplevel_handle(rail)
                if rail_hwnd:
                    handles.append(rail_hwnd)
        except Exception:
            pass
        host_hwnd = self._native_toplevel_handle(window)
        if not host_hwnd:
            return False
        handles.append(host_hwnd)
        handles = list(dict.fromkeys(handles))

        user32 = ctypes.windll.user32
        enabled_states = [
            (hwnd, bool(user32.IsWindowEnabled(hwnd)))
            for hwnd in handles
        ]
        cloaked_handles: list[int] = []
        self._set_utility_rail_suspended(window, True, preserve_mapping=True)
        try:
            for hwnd, was_enabled in enabled_states:
                if was_enabled:
                    user32.EnableWindow(hwnd, False)
            for hwnd, _was_enabled in enabled_states:
                if not self._set_dwm_cloak(hwnd, True):
                    raise RuntimeError("DWM cloak verification failed")
                cloaked_handles.append(hwnd)
            if not self._restore_foreground_window(focus_target):
                raise RuntimeError("foreground handoff failed")
            with contextlib.suppress(Exception):
                ctypes.windll.dwmapi.DwmFlush()
            window._talkdat_cloaked_handles = enabled_states  # type: ignore[attr-defined]
            window._talkdat_cloak_preserved_mapping = True  # type: ignore[attr-defined]
            window._talkdat_cloak_native_host = False  # type: ignore[attr-defined]
            window._talkdat_focus_return_hwnd = focus_target  # type: ignore[attr-defined]
            return True
        except Exception:
            rollback_complete = True
            for hwnd in reversed(cloaked_handles):
                rollback_complete = self._set_dwm_cloak(hwnd, False) and rollback_complete
            if rollback_complete:
                for hwnd, was_enabled in reversed(enabled_states):
                    if was_enabled:
                        with contextlib.suppress(Exception):
                            user32.EnableWindow(hwnd, True)
                self._set_utility_rail_suspended(window, False, preserve_mapping=True)
                return False

            # A successful app-cloak remains identity-owned until a verified
            # uncloak. If rollback itself fails, keep every receipt, hide the
            # complete pair through the native fallback too, and let the normal
            # restore path retry the DWM transaction later.
            window._talkdat_cloaked_handles = enabled_states  # type: ignore[attr-defined]
            window._talkdat_cloak_preserved_mapping = False  # type: ignore[attr-defined]
            window._talkdat_cloak_native_host = True  # type: ignore[attr-defined]
            self._set_utility_rail_suspended(window, True, preserve_mapping=False)
            with contextlib.suppress(Exception):
                user32.ShowWindow(host_hwnd, 6)  # SW_MINIMIZE
            if not bool(user32.IsIconic(host_hwnd)):
                with contextlib.suppress(Exception):
                    window.withdraw()
            self._restore_foreground_window(focus_target)
            window._talkdat_focus_return_hwnd = focus_target  # type: ignore[attr-defined]
            with contextlib.suppress(Exception):
                ctypes.windll.dwmapi.DwmFlush()
            return True

    def _restore_dwm_cloaked_utility(self, window: tk.Toplevel) -> bool:
        """Atomically uncloak and re-enable a previously composed utility."""

        states = list(getattr(window, "_talkdat_cloaked_handles", ()))
        if not states:
            return False
        restored_handles: list[int] = []
        for hwnd, _was_enabled in states:
            if self._set_dwm_cloak(int(hwnd), False):
                restored_handles.append(int(hwnd))
                continue
            # Restore is transactional. If even one member of the composed
            # host/rail pair cannot prove it is visible, put every member back
            # behind DWM and retain the receipt for a later retry. Never expose
            # half a window or clear the only recovery path.
            for restored_hwnd in restored_handles:
                self._set_dwm_cloak(restored_hwnd, True)
            if sys.platform == "win32":
                with contextlib.suppress(Exception):
                    ctypes.windll.dwmapi.DwmFlush()
            return False
        for hwnd, was_enabled in states:
            if was_enabled and sys.platform == "win32":
                with contextlib.suppress(Exception):
                    ctypes.windll.user32.EnableWindow(int(hwnd), True)
        if sys.platform == "win32":
            with contextlib.suppress(Exception):
                ctypes.windll.dwmapi.DwmFlush()
        window._talkdat_cloaked_handles = ()  # type: ignore[attr-defined]
        return True

    def _set_utility_rail_suspended(
        self,
        window: tk.Toplevel,
        suspended: bool,
        *,
        preserve_mapping: bool = False,
    ) -> None:
        """Hide or restore a utility's attached rail as part of the same surface."""

        rail = getattr(window, "_menu_rail", None)
        try:
            if rail is None or not rail.winfo_exists():
                return
        except Exception:
            return
        suspension_handler = getattr(rail, "_talkdat_set_suspended", None)
        if callable(suspension_handler):
            try:
                suspension_handler(bool(suspended), bool(preserve_mapping))
                return
            except Exception:
                log.debug("menu rail suspension handler failed", exc_info=True)
        state = getattr(rail, "_talkdat_rail_state", None)
        if isinstance(state, dict):
            state["suspended"] = bool(suspended)
            if not suspended:
                state["work_area"] = None
        if suspended and not preserve_mapping:
            with contextlib.suppress(Exception):
                rail.withdraw()
            return
        if suspended:
            return
        if preserve_mapping:
            with contextlib.suppress(Exception):
                rail.attributes("-alpha", CLAY_OPACITY)
            return
        with contextlib.suppress(Exception):
            rail.deiconify()
            rail.attributes("-alpha", CLAY_OPACITY)
            rail.lift(window)
        # The follower owns its docking math. Ask that existing path to perform
        # one exact reconciliation after the host has returned to the desktop.
        with contextlib.suppress(Exception):
            window.event_generate("<<TalkDATGeometrySettled>>", when="tail")

    def _request_utility_minimize(self, window: tk.Toplevel) -> None:
        """Minimize one persistent utility without disposing feature state.

        Utility windows are deliberately borderless. Tk refuses ``iconify`` on
        an override-redirect Toplevel, so eligible Windows sessions first use a
        verified DWM cloak that preserves the composed tree. Screen readers and
        any failed cloak/focus handoff use native HWND minimization. Other
        platforms use a withdrawn same-instance fallback restored through the
        normal Pill-menu route. No path destroys widgets, runs close-only
        disposers, stops a microphone, or discards unsaved input.
        """

        try:
            if (
                not window.winfo_exists()
                or bool(getattr(window, "_talkdat_close_requested", False))
                or not bool(getattr(window, "_talkdat_minimizable", True))
                or bool(getattr(window, "_talkdat_minimized", False))
            ):
                return
        except Exception:
            return

        with contextlib.suppress(Exception):
            focused = window.focus_get()
            if self._window_owns_focus(window, focused):
                window._talkdat_restore_focus = focused  # type: ignore[attr-defined]

        # A live compositor proxy or queued geometry frame must settle before
        # its host disappears. Otherwise a late release can restore the proxy's
        # box over the next visible window.
        self._cancel_window_geometry_motion(window)
        window._talkdat_minimized = True  # type: ignore[attr-defined]
        window._talkdat_minimize_mode = "withdrawn"  # type: ignore[attr-defined]
        self._minimized_utility_stack = [
            candidate
            for candidate in getattr(self, "_minimized_utility_stack", [])
            if candidate is not window
        ]
        self._minimized_utility_stack.append(window)
        self._last_minimized_utility = window

        if self._try_dwm_cloak_utility(window):
            window._talkdat_minimize_mode = "cloaked"  # type: ignore[attr-defined]
            return

        self._set_utility_rail_suspended(window, True)
        hwnd = self._native_toplevel_handle(window)
        if hwnd:
            try:
                user32 = ctypes.windll.user32
                user32.ShowWindow(hwnd, 6)  # SW_MINIMIZE
                if bool(user32.IsIconic(hwnd)):
                    window._talkdat_minimize_mode = "native"  # type: ignore[attr-defined]
                    return
            except Exception:
                pass
        with contextlib.suppress(Exception):
            window.withdraw()

    def _restore_utility_window(self, window: tk.Toplevel) -> bool:
        """Restore a minimized utility and its rail without rebuilding either."""

        mode = str(getattr(window, "_talkdat_minimize_mode", ""))
        if mode != "cloaked":
            # X-429: the cloaked branch below finishes the pending rail layout
            # while DWM still withholds the surface. The native and withdrawn
            # paths deserve the same courtesy and were not getting it: they
            # deiconified, cleared _talkdat_minimized, and only THEN lifted
            # suspension, so the queued layout committed onto a window the user
            # could already see -- the half-packed restore frame the suspension
            # exists to prevent. preserve_mapping commits it while the rail
            # stays withdrawn; the call at the end of this method still does
            # the mapping, docking and lift once the host is back.
            self._set_utility_rail_suspended(window, False, preserve_mapping=True)
        if mode == "cloaked":
            preserved_mapping = bool(
                getattr(window, "_talkdat_cloak_preserved_mapping", True)
            )
            # On the ordinary fast path, finish any pending rail layout while
            # DWM still withholds the complete mapped surface. A failed cloak
            # rollback parks the pair natively instead, so that rail must stay
            # withdrawn until every app-cloak receipt clears.
            if preserved_mapping:
                self._set_utility_rail_suspended(window, False, preserve_mapping=True)
            if not self._restore_dwm_cloaked_utility(window):
                window._talkdat_cloak_preserved_mapping = False  # type: ignore[attr-defined]
                window._talkdat_cloak_native_host = True  # type: ignore[attr-defined]
                self._set_utility_rail_suspended(window, True, preserve_mapping=False)
                hwnd = self._native_toplevel_handle(window)
                if hwnd and sys.platform == "win32":
                    with contextlib.suppress(Exception):
                        ctypes.windll.user32.ShowWindow(hwnd, 6)  # SW_MINIMIZE
                iconic = False
                if hwnd and sys.platform == "win32":
                    with contextlib.suppress(Exception):
                        iconic = bool(ctypes.windll.user32.IsIconic(hwnd))
                if not iconic:
                    with contextlib.suppress(Exception):
                        window.withdraw()
                return False
            if bool(getattr(window, "_talkdat_cloak_native_host", False)):
                hwnd = self._native_toplevel_handle(window)
                if hwnd and sys.platform == "win32":
                    with contextlib.suppress(Exception):
                        ctypes.windll.user32.ShowWindow(hwnd, 9)  # SW_RESTORE
                with contextlib.suppress(Exception):
                    window.deiconify()
            if not preserved_mapping:
                self._set_utility_rail_suspended(window, False, preserve_mapping=False)
            window._talkdat_cloak_preserved_mapping = True  # type: ignore[attr-defined]
            window._talkdat_cloak_native_host = False  # type: ignore[attr-defined]
        elif mode == "native":
            hwnd = self._native_toplevel_handle(window)
            if hwnd and sys.platform == "win32":
                with contextlib.suppress(Exception):
                    ctypes.windll.user32.ShowWindow(hwnd, 9)  # SW_RESTORE
        if mode != "cloaked":
            # Keep this call after native restore. It synchronizes Tk's mapped
            # state and is the portable restore for the withdrawn fallback.
            window.deiconify()
        window._talkdat_minimized = False  # type: ignore[attr-defined]
        window._talkdat_minimize_mode = ""  # type: ignore[attr-defined]
        self._minimized_utility_stack = [
            candidate
            for candidate in getattr(self, "_minimized_utility_stack", [])
            if candidate is not window
        ]
        if getattr(self, "_last_minimized_utility", None) is window:
            self._last_minimized_utility = (
                self._minimized_utility_stack[-1]
                if self._minimized_utility_stack
                else None
            )
        if mode != "cloaked":
            self._set_utility_rail_suspended(window, False)
        return True

    def _focus_utility_window(self, name: str) -> bool:
        window = self.utility_windows.get(name)
        if not window:
            return False
        try:
            if not window.winfo_exists():
                self.utility_windows.pop(name, None)
                return False
            if bool(getattr(window, "_talkdat_close_requested", False)):
                # A fading/retiring utility has already disposed its feature
                # state.  Claiming this click as a successful refocus would let
                # the old surface disappear moments later and leave no window.
                self.utility_windows.pop(name, None)
                return False
            focus_return = self._eligible_focus_return_window(
                int(getattr(self, "context_menu_target_hwnd", 0) or 0)
            )
            if focus_return:
                window._talkdat_focus_return_hwnd = focus_return  # type: ignore[attr-defined]
            if bool(getattr(window, "_talkdat_minimized", False)):
                if not self._restore_utility_window(window):
                    self.set_state(
                        "error",
                        "That window is still safely minimized.",
                        "Open it again to retry the Windows restore.",
                    )
                    # The existing instance continues to own this route. A
                    # false return would let the caller build a duplicate over
                    # the still-cloaked original.
                    return True
            else:
                window.deiconify()
            was_topmost = bool(window.attributes("-topmost"))
            # Raise an already-open page long enough for Windows to surface it,
            # then restore its ordinary z-order. Leaving this flag set made a
            # refocused Settings or History window cover every other app until
            # it was closed.
            window.attributes("-topmost", True)
            window.lift()
            window.focus_force()
            restore_focus = getattr(window, "_talkdat_restore_focus", None)
            window._talkdat_restore_focus = None  # type: ignore[attr-defined]
            if self._window_owns_focus(window, restore_focus):
                def restore_child_focus(target=restore_focus) -> None:
                    with contextlib.suppress(Exception):
                        if target.winfo_exists():
                            target.focus_set()

                window.after_idle(restore_child_focus)
            if not was_topmost:
                window.after_idle(
                    lambda: window.winfo_exists()
                    and window.attributes("-topmost", False)
                )
            return True
        except tk.TclError:
            self.utility_windows.pop(name, None)
            return False

    def _parse_geometry_size(self, geometry: str) -> tuple[int, int]:
        raw = str(geometry).split("+", 1)[0].strip()
        if "x" not in raw:
            return 720, 520
        left, right = raw.lower().split("x", 1)
        try:
            return max(280, int(left)), max(180, int(right))
        except ValueError:
            return 720, 520

    def _pill_anchored_geometry(self, width: int, height: int) -> str | None:
        """Place a window directly above the Pill.

        Centring on a monitor is right for a window someone deliberately opened
        from a menu -- they are looking at the menu, and a second screen keeps
        it off whatever they are dictating into. It is wrong for a reply to an
        action taken *on the Pill*: right-click, Check for updates, and the
        answer appearing on another display reads as nothing having happened.
        The answer has to arrive where the question was asked.
        """
        try:
            pill_x = self.root.winfo_rootx()
            pill_y = self.root.winfo_rooty()
            pill_w = self.root.winfo_width()
        except Exception:
            return None
        if pill_w <= 1:
            return None

        x = pill_x + (pill_w - width) // 2
        y = pill_y - height - 12
        # Keep it on whichever display the Pill is actually on, and flip below
        # if there is no room above -- the Pill is often near the top edge.
        try:
            monitors = list_monitors()
            here = next(
                (m for m in monitors
                 if m.left <= pill_x < m.right and m.top <= pill_y < m.bottom),
                None,
            )
        except Exception:
            here = None
        if here is not None:
            if y < here.work_top + 8:
                y = min(pill_y + self.root.winfo_height() + 12, here.work_bottom - height - 8)
            x = max(here.work_left + 8, min(x, here.work_right - width - 8))
            y = max(here.work_top + 8, y)
        return f"{width}x{height}+{int(x)}+{int(y)}"

    def _utility_geometry(self, geometry: str, *, anchor_to_pill: bool = False) -> str:
        width, height = self._parse_geometry_size(geometry)
        if anchor_to_pill:
            anchored = self._pill_anchored_geometry(width, height)
            if anchored:
                return anchored

        # Pop-ups default to a second screen when there is one. Centring on the
        # primary puts every settings, update and history window straight over
        # the thing being dictated into, which interrupts the task the window
        # exists to support. Tk cannot see past the primary display, so the
        # monitor list comes from Windows.
        # X-16: windows open on the monitor the PILL is on. "secondary" was
        # the old default and sent every menu to the other screen -- exactly
        # the complaint. Anyone who explicitly chose a preference keeps it.
        preference = str(self.config.get("ui", {}).get("popup_monitor", "pill"))
        if preference == "pill":
            rect = self._pill_monitor_work_area()
            if rect is not None:
                left, top, right, bottom = rect
                work_width = max(320, right - left)
                work_height = max(220, bottom - top)
                width = min(width, max(320, work_width - 32))
                height = min(height, max(220, work_height - 32))
                x = left + max(8, (work_width - width) // 2)
                y = top + max(8, (work_height - height) // 2)
                return f"{width}x{height}+{x}+{y}"
        try:
            monitor = preferred_monitor(list_monitors(), preference)
        except Exception:
            monitor = None
        if monitor is not None:
            fitted_width, fitted_height, x, y = centre_on(monitor, width, height)
            return f"{fitted_width}x{fitted_height}+{x}+{y}"

        left, top, right, bottom = self._logical_work_area()
        work_width = max(320, right - left)
        work_height = max(220, bottom - top)
        width = min(width, max(320, work_width - 32))
        height = min(height, max(220, work_height - 32))
        x = left + max(8, (work_width - width) // 2)
        y = top + max(8, (work_height - height) // 2)
        return f"{width}x{height}+{x}+{y}"

    def _paint_clay_backdrop(self, window: tk.Toplevel, bg: str) -> None:
        """Lay the clay texture behind a window's content.

        The comment below has claimed for a while that "the tactile quality
        comes from the painted clay texture instead", and it was describing an
        intention rather than the code: the texture was wired into exactly one
        surface, the context menu, while every settings, history, stats and
        update window was a flat fill.

        Tk has no widget transparency, so child frames with their own colour
        still paint over this. What it reaches is the padding and the margins --
        the edges of the surface, which is where an uneven plaster wall reads
        from anyway. Placed rather than packed or gridded, because place does
        not participate in either manager and so cannot disturb a layout.
        """

        state: dict = {"backdrop": None, "after": None, "size": (0, 0)}

        def backdrop_is_alive() -> bool:
            backdrop = state.get("backdrop")
            try:
                return bool(backdrop is not None and backdrop.winfo_exists())
            except Exception:
                return False

        def paint() -> None:
            state["after"] = None
            if not window.winfo_exists():
                return
            # A timer queued just before pointer-down can become due after the
            # drag begins.  Scheduling-time suppression alone cannot stop it;
            # the expensive tile and PhotoImage allocation must also verify
            # the live motion state at execution time.  The exact settlement
            # event below schedules the final paint after release.
            if getattr(window, "_talkdat_live_resize", False):
                return
            width = max(1, window.winfo_width())
            height = max(1, window.winfo_height())
            if width < 20 or height < 20:
                return
            if state["size"] == (width, height) and backdrop_is_alive():
                return
            state["size"] = (width, height)
            try:
                field = clay_field(width, height, self._rgb(bg))
                photo = ImageTk.PhotoImage(field, master=window)
                if not backdrop_is_alive():
                    # The label expands immediately while its image is repainted
                    # after the resize settles.  Give the uncovered pixels the
                    # exact panel colour so no default-Tk grey flashes around a
                    # temporarily smaller texture.
                    state["backdrop"] = tk.Label(
                        window,
                        bg=bg,
                        bd=0,
                        highlightthickness=0,
                    )
                    state["backdrop"].place(x=0, y=0, relwidth=1.0, relheight=1.0)
                    state["backdrop"].lower()
                state["backdrop"].configure(image=photo, bg=bg)
                state["backdrop"].image = photo  # type: ignore[attr-defined]
            except Exception:
                # Decoration must never stop a window opening.
                log.debug("clay backdrop skipped", exc_info=True)

        def schedule(event: tk.Event | None = None) -> None:
            # X-03: the wall re-renders to FIT on every resize, debounced so
            # a drag-resize costs one render at the end, not sixty during.
            # A Toplevel binding also receives Configure events from all of its
            # descendants.  Treating a label or canvas layout as a window
            # resize multiplied one gesture into thousands of cancelled timers.
            if event is not None and event.widget is not window:
                return
            if getattr(window, "_talkdat_live_resize", False):
                return
            if event is not None:
                try:
                    requested_size = (max(1, int(event.width)), max(1, int(event.height)))
                except (AttributeError, TypeError, ValueError):
                    requested_size = (max(1, window.winfo_width()), max(1, window.winfo_height()))
                if requested_size == state["size"] and backdrop_is_alive():
                    return
            if state["after"]:
                try:
                    window.after_cancel(state["after"])
                except Exception:
                    pass
            state["after"] = window.after(140, paint)

        window.after_idle(paint)
        window.bind("<Configure>", schedule, add="+")
        window.bind("<<TalkDATGeometrySettled>>", schedule, add="+")

    def _apply_glass_effect(self, window: tk.Toplevel, bg: str) -> None:
        window.configure(bg=bg)
        self._paint_clay_backdrop(window, bg)
        try:
            # Opaque, deliberately. This was 0.965, and because Tk applies alpha
            # to the whole window rather than per region, 3.5% of whatever sat
            # behind composited straight through the panel. Over a bright shape
            # on a dark theme that is clearly visible, and it appeared as
            # unexplained coloured lines drawn across the text. The tactile
            # quality comes from the painted clay texture instead, which cannot
            # leak the desktop into anything anyone has to read.
            window.attributes("-alpha", CLAY_OPACITY)
        except Exception:
            pass
        try:
            window.attributes("-toolwindow", True)
        except Exception:
            pass
        # Tk's winfo_id() is the inner TkChild HWND.  The shared native policy
        # resolves the visible outer TkTopLevel and declares pointer-sized
        # ctypes signatures before touching DWM.  Windows 11 gets compositor
        # corners and its native shadow; Windows 10/macOS keep an intentional
        # crisp square silhouette instead of an aliased fake curve.
        set_dwm_int_attribute(window, 20, 1)
        set_dwm_int_attribute(window, 38, 3)
        try:
            apply_window_chrome(
                window,
                str(getattr(window, "_talkdat_chrome_role", UTILITY_CHROME)),
            )
        except Exception:
            log.debug("utility chrome skipped", exc_info=True)

    def _bind_drag_anywhere(self, window: tk.Toplevel) -> None:
        """X-09: every window drags from any surface a person would grab.

        The filter is behavioural, not a widget whitelist: a press starts a
        window drag only when the widget under the pointer has no click or
        drag behaviour of its own -- so buttons, entries, text, lists,
        scrollbars, the settings dial (which drags to set a value), and the
        menu rows all keep working, while dead space anywhere moves the
        window. One binding on the toplevel covers present and future
        children.
        """

        # The shared utility shell asks for this binding again after every page
        # swap.  ``add='+'`` made those closures accumulate, so one drag after
        # ten menu changes issued ten geometry calls.  Chrome input belongs to
        # the window, not the current page; install it exactly once.
        if getattr(window, "_talkdat_drag_bindings", None):
            return

        # The three handlers live as methods, not closures, because Aqua drops
        # SYNTHESIZED ButtonPress events outright (not even the pressed widget's
        # own binding fires), so the stale-origin contract can only be tested by
        # calling the real handler -- and a closure has no name to call.
        window._talkdat_drag_bindings = {  # type: ignore[attr-defined]
            "<ButtonPress-1>": window.bind(
                "<ButtonPress-1>",
                lambda e: self._drag_anywhere_press(window, e.widget, int(e.x_root), int(e.y_root)),
                add="+",
            ),
            "<B1-Motion>": window.bind(
                "<B1-Motion>",
                lambda e: self._drag_anywhere_motion(window, int(getattr(e, "state", 0)), int(e.x_root), int(e.y_root)),
                add="+",
            ),
            "<ButtonRelease-1>": window.bind(
                "<ButtonRelease-1>",
                lambda e: self._drag_anywhere_release(window),
                add="+",
            ),
        }

    def _drag_anywhere_widget_is_interactive(self, widget, window) -> bool:
        try:
            if isinstance(widget, (tk.Entry, tk.Text, tk.Listbox, tk.Scrollbar, tk.Button, ttk.Widget)):
                return True
            if widget.bind("<B1-Motion>") or widget.bind("<Button-1>") or widget.bind("<ButtonPress-1>"):
                return True
            cursor = str(widget.cget("cursor") or "")
            if cursor in {"hand2", "xterm", "sb_v_double_arrow", "sb_h_double_arrow", "sizing"}:
                return True
        except Exception:
            return True
        return False

    def _drag_anywhere_press(self, window, widget, x_root: int, y_root: int) -> None:
        if widget is not window and self._drag_anywhere_widget_is_interactive(widget, window):
            # Declining must CLEAR the origin, not leave the previous one
            # standing. It is one attribute shared by every window and by
            # the title-bar handle, and a release that lands outside the
            # window never fires, so a stale origin survives -- then the
            # next press on a button or a slider fed <B1-Motion> a start
            # point from some earlier drag and threw the window across the
            # screen. That is the "dragging is broken and messy".
            self.utility_drag_origin = None
            self.utility_drag_window = None
            return
        # X-127 ("lags on drag... not industry standard"): hand the drag
        # to Windows itself when we can. The compositor then moves the
        # window as ONE surface -- rail, pages and titlebar together --
        # instead of Tk chasing the pointer with geometry() calls that
        # let heavy panes visibly trail the light ones.
        if self._begin_native_window_drag(window):
            return
        # Moving a Tk toplevel still generates a Configure stream.  Treat
        # the fallback move as live geometry motion so delayed clay,
        # clipping-region, and artwork painters wait for the settled
        # frame instead of competing with the pointer loop.
        self._begin_window_resize(window, visual_proxy=False)
        # The window is part of the origin so one window can never be moved
        # using another's start point; they share this attribute.
        self.utility_drag_origin = (
            window,
            x_root,
            y_root,
            int(window.winfo_x()),
            int(window.winfo_y()),
        )
        self.utility_drag_window = window

    def _drag_anywhere_motion(self, window, state: int, x_root: int, y_root: int) -> None:
        origin = self.utility_drag_origin
        if not origin or origin[0] is not window:
            return
        # Ghost-drag guard: if the ButtonRelease was swallowed (grabs,
        # popovers, focus theft), Tk keeps streaming B1-Motion and the
        # window follows an unheld mouse. The event's own modifier state
        # says whether button one is REALLY down; trust it over the
        # stream we happen to be in.
        if not (state & 0x100):
            self._finish_window_resize(window)
            self.utility_drag_origin = None
            self.utility_drag_window = None
            return
        _owner, start_x, start_y, window_x, window_y = origin
        self._queue_window_geometry(
            window,
            f"+{window_x + x_root - start_x}+{window_y + y_root - start_y}",
        )

    def _drag_anywhere_release(self, window) -> None:
        origin = self.utility_drag_origin
        if origin and origin[0] is window:
            self._finish_window_resize(window)
            self._snap_on_release(window)
        self.utility_drag_origin = None
        self.utility_drag_window = None

    def _begin_native_window_drag(self, window: tk.Toplevel) -> bool:
        """Retired, and the reason is a crash dump, not a preference.

        X-127 sent drags through WM_NCLBUTTONDOWN so Windows would move the
        window as one composited surface. But that call enters the system's
        MODAL MOVE LOOP from inside a Tk callback, and the loop keeps pumping
        this thread's messages: Tk timers re-enter mid-callback -- the 40ms
        cross-thread drain, the gc pass, every animation tick -- and on real
        hardware that reentrancy ends in Tcl panicking and C abort(). That is
        the c0000409 in every 0.4.118-0.4.120 crash report; stderr capture on
        2026-08-21 caught it red-handed at this exact call (press ->
        _begin_native_window_drag). X-163 had already documented the same
        loop killing the interpreter under synthetic clicks; real clicks were
        never safe either, just luckier.

        The geometry() drag the callers fall back to is correct on every
        input path and is what the Mac port has always used. It trails heavy
        panes slightly on drag; the app surviving the click wins.
        """
        return False

    def _bind_utility_drag_handle(self, window: tk.Toplevel, *widgets: tk.Widget) -> None:
        def press(event: tk.Event) -> None:
            # X-127: dedicated drag handles go straight to the OS move loop
            # on Windows -- one composited surface, zero trailing panes.
            if self._begin_native_window_drag(window):
                return
            self._begin_window_resize(window, visual_proxy=False)
            self.utility_drag_origin = (
                window,
                int(getattr(event, "x_root", window.winfo_pointerx())),
                int(getattr(event, "y_root", window.winfo_pointery())),
                int(window.winfo_x()),
                int(window.winfo_y()),
            )
            self.utility_drag_window = window

        def drag(event: tk.Event) -> None:
            origin = self.utility_drag_origin
            if not origin or origin[0] is not window:
                return
            # Same ghost-drag guard as _bind_drag_anywhere: a swallowed
            # release must not leave the window glued to the pointer.
            if not (int(getattr(event, "state", 0)) & 0x100):
                self._finish_window_resize(window)
                self.utility_drag_origin = None
                self.utility_drag_window = None
                return
            _owner, start_x, start_y, window_x, window_y = origin
            pointer_x = int(getattr(event, "x_root", window.winfo_pointerx()))
            pointer_y = int(getattr(event, "y_root", window.winfo_pointery()))
            self._queue_window_geometry(
                window,
                f"+{window_x + pointer_x - start_x}+{window_y + pointer_y - start_y}",
            )

        def release(_event: tk.Event) -> None:
            if self.utility_drag_origin is not None and self.utility_drag_window is window:
                self._finish_window_resize(window)
                self._snap_on_release(window)
                self.utility_drag_origin = None
                self.utility_drag_window = None

        for widget in widgets:
            widget.bind("<ButtonPress-1>", press, add="+")
            widget.bind("<B1-Motion>", drag, add="+")
            widget.bind("<ButtonRelease-1>", release, add="+")

    def _install_utility_resize_grip(
        self,
        window: tk.Toplevel,
        *,
        minimum_size: tuple[int, int],
        bg: str,
    ) -> None:
        metric = lambda value: ui_scale.px(value, self.config)
        grip_size = metric(22)
        grip = tk.Canvas(
            window,
            width=grip_size,
            height=grip_size,
            bg=bg,
            bd=0,
            highlightthickness=0,
            cursor=mac_support.RESIZE_CORNER_CURSOR,
        )
        grip.place(
            relx=1.0,
            rely=1.0,
            x=-metric(2),
            y=-metric(2),
            anchor="se",
        )
        grip_palette = self._settings_palette(self._settings_theme_key())
        resize_photo = self._ui_icon_photo(
            "resize_handle",
            metric(18),
            grip_palette["muted"],
            grip_palette["text"],
        )
        grip.create_image(grip_size // 2, grip_size // 2, image=resize_photo)
        grip._talkdat_icon_photo = resize_photo  # type: ignore[attr-defined]

        resize_origin: dict[str, Any] = {}

        def press(event: tk.Event) -> str:
            work_area = self._window_monitor_work_area(window)
            if work_area is None:
                work_area = self._logical_work_area()
            origin_x = int(window.winfo_rootx())
            origin_y = int(window.winfo_rooty())
            resize_origin.update(
                pointer_x=int(getattr(event, "x_root", window.winfo_pointerx())),
                pointer_y=int(getattr(event, "y_root", window.winfo_pointery())),
                width=max(1, int(window.winfo_width())),
                height=max(1, int(window.winfo_height())),
                work_area=work_area,
                origin_x=origin_x,
                origin_y=origin_y,
            )
            self._begin_window_resize(window)
            return "break"

        def drag(event: tk.Event) -> str:
            if not resize_origin:
                return "break"
            work_area = resize_origin["work_area"]
            _left, _top, right, bottom = work_area
            origin_x = int(resize_origin["origin_x"])
            origin_y = int(resize_origin["origin_y"])
            max_width = max(1, right - origin_x - 8)
            max_height = max(1, bottom - origin_y - 8)
            pointer_x = int(getattr(event, "x_root", window.winfo_pointerx()))
            pointer_y = int(getattr(event, "y_root", window.winfo_pointery()))
            floor_width = min(int(minimum_size[0]), max_width)
            floor_height = min(int(minimum_size[1]), max_height)
            width = max(
                floor_width,
                min(max_width, resize_origin["width"] + pointer_x - resize_origin["pointer_x"]),
            )
            height = max(
                floor_height,
                min(max_height, resize_origin["height"] + pointer_y - resize_origin["pointer_y"]),
            )
            self._queue_window_geometry(window, f"{width}x{height}")
            return "break"

        def release(_event: tk.Event) -> str:
            if resize_origin:
                self._finish_window_resize(window)
            resize_origin.clear()
            return "break"

        grip.bind("<ButtonPress-1>", press)
        grip.bind("<B1-Motion>", drag)
        grip.bind("<ButtonRelease-1>", release)
        # Canvas aliases ``lift`` to item tag raising; call the widget-level
        # implementation so resizable borderless windows do not crash.
        tk.Misc.lift(grip)

    def _close_control(
        self,
        window: tk.Toplevel,
        parent: tk.Widget,
        bg: str,
        *,
        command: Callable[[], Any] | None = None,
    ) -> tk.Frame:
        """X-63: THE close button. One look, one size, everywhere.

        A 44x32 design-pixel hit zone, scaled for the display, around a
        centered glyph, themed from the user's palette, with the standard
        danger hover. Every window and popover uses this; a hand-rolled X is
        a review defect."""
        palette = self._settings_palette(self._settings_theme_key())
        zone = tk.Frame(
            parent,
            bg=bg,
            width=ui_scale.px(44, self.config),
            height=ui_scale.px(32, self.config),
        )
        zone.pack_propagate(False)
        # Use a real Tk button rather than a clickable frame/label pair.  The
        # previous composite looked like a button but was absent from keyboard
        # traversal and exposed no button role through Tk's Windows bridge.
        # The fixed outer frame preserves the exact 44x32 geometry every title
        # bar was already laid out against.
        glyph = FlatButton(
            zone,
            # The semantic text remains available to Tk's accessibility bridge;
            # compound="none" displays the generated close master instead of a
            # font-dependent X glyph.
            text="Close window",
            bg=bg,
            fg=palette.get("muted", "#9aa3b5"),
            activebackground=palette.get("danger", "#8a3038"),
            activeforeground=palette.get("on_danger", palette.get("text", "#ffffff")),
            font=(BRAND_UI_FAMILY, type_scale.SECONDARY, "bold"),
            relief="flat",
            bd=0,
            padx=0,
            pady=0,
            takefocus=1,
            highlightthickness=ui_scale.px(2, self.config),
            highlightbackground=bg,
            highlightcolor=palette.get("warm", "#ffd27d"),
            cursor="hand2",
        )
        self._set_button_icon(
            glyph,
            "close",
            size=ui_scale.px(19, self.config),
            primary=palette["muted"],
            detail=palette["text"],
            compound="none",
        )
        glyph.pack(fill="both", expand=True)

        def go(_e: tk.Event | None = None) -> str:
            if bool(getattr(window, "_close_locked", False)):
                self.set_state(
                    "processing",
                    str(getattr(window, "_close_lock_message", "Please wait for this task to finish.")),
                    "",
                )
                return "break"
            with contextlib.suppress(Exception):
                if command is None:
                    self._request_utility_close(window)
                else:
                    command()
            return "break"

        glyph.configure(command=go)
        # Tk Buttons activate with Space; Windows users also expect Enter.
        glyph.bind("<Return>", go, add="+")

        def apply_palette(latest: dict[str, str], background: str) -> None:
            zone.configure(bg=background)
            glyph.configure(
                bg=background,
                fg=latest.get("muted", "#9aa3b5"),
                activebackground=latest.get("danger", "#8a3038"),
                activeforeground=latest.get("on_danger", latest.get("text", "#ffffff")),
                highlightbackground=background,
                highlightcolor=latest.get("warm", "#ffd27d"),
            )
            self._set_button_icon(
                glyph,
                "close",
                size=ui_scale.px(19, self.config),
                primary=latest["muted"],
                detail=latest["text"],
                compound="none",
            )

        zone._talkdat_apply_palette = apply_palette  # type: ignore[attr-defined]
        return zone

    def _minimize_control(
        self,
        window: tk.Toplevel,
        parent: tk.Widget,
        bg: str,
        *,
        width: int = 84,
    ) -> tk.Frame:
        """The shared, focusable minimize action for persistent utilities.

        ``width`` exists for title bars that want a caption-button lane rather
        than a wide action: the glyph is drawn (compound="none"), so the zone
        width is pure layout. A caller matching the 44x32 close control passes
        44 and gets a pair the eye reads as one control set.
        """

        palette = self._settings_palette(self._settings_theme_key())
        zone = tk.Frame(
            parent,
            bg=bg,
            width=ui_scale.px(width, self.config),
            height=ui_scale.px(32, self.config),
        )
        zone.pack_propagate(False)
        button = FlatButton(
            zone,
            text="Minimize",
            command=lambda: self._request_utility_minimize(window),
            bg=bg,
            fg=palette.get("muted", "#9aa3b5"),
            activebackground=palette.get("select", palette.get("button", bg)),
            activeforeground=palette.get("text", "#ffffff"),
            font=(BRAND_UI_FAMILY, type_scale.CAPTION, "bold"),
            relief="flat",
            bd=0,
            padx=ui_scale.px(8, self.config),
            pady=0,
            takefocus=1,
            highlightthickness=ui_scale.px(2, self.config),
            highlightbackground=bg,
            highlightcolor=palette.get("warm", "#ffd27d"),
            cursor="hand2",
            underline=0,
        )
        self._set_button_icon(
            button,
            "minimize",
            size=ui_scale.px(21, self.config),
            primary=palette["muted"],
            detail=palette["text"],
            compound="none",
        )
        button.pack(fill="both", expand=True)

        def go(_event: tk.Event | None = None) -> str:
            self._request_utility_minimize(window)
            return "break"

        button.bind("<Return>", go, add="+")

        def apply_palette(latest: dict[str, str], background: str) -> None:
            zone.configure(bg=background)
            button.configure(
                bg=background,
                fg=latest.get("muted", "#9aa3b5"),
                activebackground=latest.get("select", latest.get("button", background)),
                activeforeground=latest.get("text", "#ffffff"),
                highlightbackground=background,
                highlightcolor=latest.get("warm", "#ffd27d"),
            )
            self._set_button_icon(
                button,
                "minimize",
                size=ui_scale.px(21, self.config),
                primary=latest["muted"],
                detail=latest["text"],
                compound="none",
            )

        zone._talkdat_apply_palette = apply_palette  # type: ignore[attr-defined]
        window._talkdat_minimize_control = zone  # type: ignore[attr-defined]
        return zone


    def _display_font(self, size: int, *, fallback_weight: str = "Semibold") -> tuple[str, int]:
        """The Knight AI+AV display face for headings; Segoe when unavailable."""
        family = getattr(self, "_brand_family", None)
        if family:
            return (family, size)
        return (BRAND_UI_FAMILY, size, "bold" if fallback_weight else "normal")

    def _make_glass_titlebar(self, window: tk.Toplevel, title: str, bg: str, fg: str = "#eef8f3") -> tk.Frame | None:
        # Idempotent. _utility_window fits every window with a bar so none can
        # ship without one, and most callers then ask for their own; the first
        # bar wins and the rest are no-ops. Without this guard those windows
        # would grow two stacked title bars.
        existing = getattr(window, "_glass_titlebar", None)
        if existing is not None and existing.winfo_exists():
            return existing
        # Tk refuses pack in a container that already has grid slaves, and the
        # raise happened here rather than at the caller -- so the caller's
        # "if manager == grid" branch could never run, and Settings, Account and
        # Local Models each ended up with a Frame that was created, recorded and
        # never displayed. They build their own header and Close button, so a
        # second bar is not wanted; the right answer is to not make one.
        if any(child.winfo_manager() == "grid" for child in window.winfo_children()):
            log.debug("no glass title bar for a grid-managed window; it supplies its own header")
            return None
        bar = tk.Frame(
            window,
            bg=bg,
            height=ui_scale.px(44, self.config),
            bd=0,
            highlightthickness=0,
        )
        window._glass_titlebar = bar  # type: ignore[attr-defined]
        bar.pack(
            fill="x",
            padx=ui_scale.px(16, self.config),
            pady=(ui_scale.px(12, self.config), 0),
        )
        label = tk.Label(
            bar,
            text=title,
            bg=bg,
            fg=fg,
            font=self._display_font(12),
            anchor="w",
        )
        label.pack(side="left", fill="x", expand=True)
        self._close_control(window, bar, bg).pack(
            side="right",
            padx=(ui_scale.px(8, self.config), 0),
        )
        if bool(getattr(window, "_talkdat_minimizable", True)):
            self._minimize_control(window, bar, bg).pack(
                side="right",
                padx=(ui_scale.px(8, self.config), 0),
            )
        self._bind_utility_drag_handle(window, bar, label)
        return bar

    def _utility_window(
        self,
        name: str,
        title: str,
        geometry: str,
        *,
        bg: str,
        resizable: bool = False,
        minimum_size: tuple[int, int] | None = None,
        anchor_to_pill: bool = False,
        remember_size: bool = True,
    ) -> tk.Toplevel | None:
        if self._focus_utility_window(name):
            return None
        # Page-type utilities behave as one application shell.  The physical
        # Toplevel is replaced during navigation, however, because destroying
        # Settings' ~900-widget tree in the visible shell blocks Tk for about a
        # second.  The old surface stays mapped at the same coordinates while
        # a fresh destination builds at alpha zero; presentation crossfades the
        # completed destination and retires the old tree only after it is no
        # longer visible.  To a person it is still one stable window, but no
        # navigation ever exposes an empty or half-destroyed frame.
        SHELL_PAGES = Overlay.SHELL_PAGES
        shell = getattr(self, "_shell_window", None)
        outgoing_shell: tk.Toplevel | None = None
        transition_box: tuple[int, int, int, int] | None = None
        transition_work_area: tuple[int, int, int, int] | None = None
        outgoing_registry_names: tuple[str, ...] = ()
        inherited_outgoing_registry_names: tuple[str, ...] = ()
        if (
            name in SHELL_PAGES
            and shell is not None
            and bool(getattr(shell, "_talkdat_close_requested", False))
        ):
            # Close already owns this surface's hidden retirement.  Never make
            # reopening wait for its large native destroy.
            if getattr(self, "_shell_window", None) is shell:
                self._shell_window = None
            shell = None
        if name in SHELL_PAGES and shell is not None and shell.winfo_exists():
            if bool(getattr(shell, "_talkdat_minimized", False)):
                # A shell-to-shell request can need an unsaved-work decision.
                # Restore first so any parented confirmation is visible instead
                # of opening behind an iconic Settings window.
                if not self._restore_utility_window(shell):
                    self._pending_window_origin = None
                    self.set_state(
                        "error",
                        "That window is still safely minimized.",
                        "Open it again before changing pages.",
                    )
                    return None
                with contextlib.suppress(Exception):
                    shell.lift()
                    shell.focus_force()
            before_navigate = getattr(shell, "_talkdat_before_navigate", None)
            if callable(before_navigate):
                try:
                    navigation_allowed = bool(before_navigate())
                except Exception:
                    log.exception("utility navigation preflight failed")
                    navigation_allowed = False
                if not navigation_allowed:
                    self._pending_window_origin = None
                    return None
            # A second navigation can supersede a destination that has not yet
            # presented. Preserve the original visible page as the handoff
            # surface and retire the hidden intermediate independently.
            prior_outgoing = getattr(shell, "_talkdat_transition_outgoing", None)
            try:
                prior_outgoing_alive = bool(
                    prior_outgoing is not None and prior_outgoing.winfo_exists()
                )
            except Exception:
                prior_outgoing_alive = False
            outgoing_shell = prior_outgoing if prior_outgoing_alive else shell
            if prior_outgoing_alive:
                inherited_outgoing_registry_names = tuple(
                    getattr(shell, "_talkdat_outgoing_registry_names", ())
                )
                shell._talkdat_transition_outgoing = None  # type: ignore[attr-defined]
                self._shell_window = None
                self._request_utility_close(shell)

            transition_box = (
                max(1, int(outgoing_shell.winfo_width())),
                max(1, int(outgoing_shell.winfo_height())),
                int(outgoing_shell.winfo_rootx()),
                int(outgoing_shell.winfo_rooty()),
            )
            transition_work_area = self._window_monitor_work_area(outgoing_shell)
            outgoing_registry_names = tuple(dict.fromkeys((
                *inherited_outgoing_registry_names,
                *tuple(
                    key
                    for key, value in list(self.utility_windows.items())
                    if value is outgoing_shell
                ),
            )))
            self._cancel_window_geometry_motion(outgoing_shell)
            # Stop functional ownership immediately while the complete old
            # pixels remain as the transition cover.  Destroy is intentionally
            # deferred until after the destination presents.
            transactions = getattr(self, "_utility_build_transactions", None)
            transactional_build = bool(
                isinstance(transactions, list) and transactions
            )
            if not transactional_build:
                for stale_name in outgoing_registry_names:
                    self._dispose_window(stale_name)
                    self.utility_windows.pop(stale_name, None)
                with contextlib.suppress(Exception):
                    outgoing_shell.attributes("-disabled", True)
                outgoing_rail = getattr(outgoing_shell, "_menu_rail", None)
                with contextlib.suppress(Exception):
                    if outgoing_rail is not None and outgoing_rail.winfo_exists():
                        outgoing_rail.attributes("-disabled", True)
            if getattr(self, "_shell_window", None) is shell:
                self._shell_window = None

        window = self._new_toplevel(self.root, role=UTILITY_CHROME)
        minimizable = name not in self.NON_MINIMIZABLE_UTILITY_ROUTES
        window._talkdat_minimizable = minimizable  # type: ignore[attr-defined]
        window._talkdat_minimized = False  # type: ignore[attr-defined]
        window._talkdat_minimize_mode = ""  # type: ignore[attr-defined]
        window._talkdat_restore_focus = None  # type: ignore[attr-defined]
        window._talkdat_cloaked_handles = ()  # type: ignore[attr-defined]
        window._talkdat_cloak_preserved_mapping = True  # type: ignore[attr-defined]
        window._talkdat_cloak_native_host = False  # type: ignore[attr-defined]
        window._talkdat_focus_return_hwnd = int(  # type: ignore[attr-defined]
            self._foreground_target_window()
            or getattr(self, "context_menu_target_hwnd", 0)
            or 0
        )
        if name in SHELL_PAGES:
            self._shell_window = window
            window._talkdat_transition_outgoing = outgoing_shell  # type: ignore[attr-defined]
            window._talkdat_outgoing_registry_names = (  # type: ignore[attr-defined]
                outgoing_registry_names if outgoing_shell is not None else ()
            )
        self._install_toplevel_timer_cleanup(window)
        window.title(title)
        window.overrideredirect(True)
        # Every caller passes a geometry tuned at 96 DPI. Scaling here, at the
        # one chokepoint, is what keeps thirty call sites honest on displays
        # where a pixel is smaller than the one the numbers were tuned on.
        geometry = ui_scale.scale_geometry(geometry, self.config)
        if minimum_size is not None:
            minimum_size = (ui_scale.px(minimum_size[0], self.config), ui_scale.px(minimum_size[1], self.config))
        # X-535: a size reaching a window has one of three origins and none of
        # them was ever checked against the monitor -- a default tuned on
        # somebody else's screen, a SAVED size measured on whatever monitor and
        # scale the person had last time, or a size the wizard grew itself to
        # fit a step. His onboarding restored to 1908x2091 on a 2066px work
        # area: taller than the screen. That is what "the window that pops up
        # is gigantic" looks like from the inside.
        work_area = self._active_monitor_work_area()
        if resizable and remember_size:
            saved = self.config.get("ui", {}).get("window_sizes", {}).get(name, "")
            restored = ui_scale.restore_window_size(saved, self.config)
            if restored is not None:
                saved_w, saved_h = restored
                fits = ui_scale.clamp_to_work_area(
                    saved_w, saved_h, work_area, config=self.config
                )
                if (
                    saved_w >= ui_scale.px(320, self.config)
                    and saved_h >= ui_scale.px(220, self.config)
                    # A receipt this monitor cannot honour is DISCARDED, not
                    # squashed. Squashing keeps the width somebody's old screen
                    # allowed and trims only the height, which hands them an
                    # aspect ratio nobody chose. Falling back to the designed
                    # size is the honest answer to "that size does not fit
                    # here".
                    and fits == (saved_w, saved_h)
                ):
                    geometry = f"{saved_w}x{saved_h}"
                else:
                    log.debug(
                        "window %s: saved %dx%d does not fit this work area; using the design",
                        name, saved_w, saved_h,
                    )
        # The design itself was tuned on somebody's monitor too, so it is held
        # to the same rule.
        want_w, want_h = self._parse_geometry_size(geometry)
        fits_w, fits_h = ui_scale.clamp_to_work_area(
            want_w, want_h, work_area, config=self.config
        )
        if (fits_w, fits_h) != (want_w, want_h):
            log.debug("window %s clamped from %dx%d to %dx%d", name, want_w, want_h, fits_w, fits_h)
            geometry = f"{fits_w}x{fits_h}"
        if transition_box is not None:
            current_w, current_h, _origin_x, _origin_y = transition_box
            want_w, want_h = self._parse_geometry_size(geometry)
            geometry = f"{max(current_w, want_w)}x{max(current_h, want_h)}"

        # Park the hidden destination at the outgoing surface's origin before
        # it maps, so the crossfade reads as one window changing content.
        pending_origin = (
            (transition_box[2], transition_box[3])
            if transition_box is not None
            else getattr(self, "_pending_window_origin", None)
        )
        self._pending_window_origin = None
        applied_geometry = self._utility_geometry(geometry, anchor_to_pill=anchor_to_pill)
        if pending_origin is not None:
            try:
                size = applied_geometry.split("+", 1)[0]
                applied_w, applied_h = self._parse_geometry_size(size)
                origin_x, origin_y = int(pending_origin[0]), int(pending_origin[1])
                # The utility may have been moved away from the Pill. Preserve
                # and clamp against the outgoing window's monitor, not the
                # microphone control's monitor, or navigation can teleport the
                # shell across displays.
                work_area = transition_work_area or self._pill_monitor_work_area()
                if work_area is not None:
                    left, top, right, bottom = work_area
                    origin_x = min(
                        max(left + 8, origin_x),
                        max(left + 8, right - applied_w - 8),
                    )
                    origin_y = min(
                        max(top + 8, origin_y),
                        max(top + 8, bottom - applied_h - 8),
                    )
                applied_geometry = f"{size}+{origin_x}+{origin_y}"
            except Exception:
                pass
        window.geometry(applied_geometry)
        window.resizable(resizable, resizable)
        if resizable and minimum_size is None:
            # X-03: no resizable window may collapse into a broken layout.
            minimum_size = (ui_scale.px(480, self.config), ui_scale.px(320, self.config))
        if minimum_size is not None:
            applied_width, applied_height = self._parse_geometry_size(applied_geometry)
            minimum_size = (
                min(applied_width, max(320, int(minimum_size[0]))),
                min(applied_height, max(220, int(minimum_size[1]))),
            )
            window.minsize(*minimum_size)
        self._apply_glass_effect(window, bg)
        # Build at the final geometry while invisible.  The caller adds its
        # controls synchronously after this method returns; a double-idle
        # presentation below reveals only the completed surface.
        with contextlib.suppress(Exception):
            window.attributes("-alpha", 0.0)
        # overrideredirect strips the OS title bar, so a window without one of
        # ours cannot be moved or closed at all -- two of these shipped that
        # way. Rather than trust each caller to remember, check once the window
        # is built and fit one if it is missing.
        #
        # Deferred rather than added here because a couple of these windows lay
        # their children out with grid, and packing a bar into a grid-managed
        # window raises TclError. By the time this runs the caller has placed
        # its own widgets, so their manager can be read off a child and matched.
        def ensure_titlebar() -> None:
            if name == "captions":
                # Live Captions is an intentional broadcast strip with its own
                # single accessible close action and no application chrome.
                return
            if getattr(window, "_glass_titlebar", None) is not None or not window.winfo_exists():
                return
            try:
                # _make_glass_titlebar packs, and returns None for the windows
                # that cannot take a packed bar. The re-management that used to
                # live here never ran: the pack inside raised first, so the
                # grid and place branches were unreachable from the day they
                # were written.
                self._make_glass_titlebar(window, title.removeprefix("Talk DAT! "), bg)
            except Exception:
                # A window that cannot take a bar still closes on Escape, which
                # _utility_window binds unconditionally -- but Escape is
                # invisible. X-341, his sweep order: every surface shows a way
                # back. A minimal corner X is placed (never packed, so it
                # cannot fight the caller's geometry manager).
                log.warning("could not fit a title bar to the %s window", name, exc_info=True)
                with contextlib.suppress(Exception):
                    fallback_close = FlatButton(
                        window,
                        text="✕",
                        command=lambda: self._request_utility_close(window),
                        bg=bg,
                        fg=self._settings_palette(self._settings_theme_key())["text"],
                        relief="flat",
                        bd=0,
                        cursor="hand2",
                        takefocus=1,
                        highlightthickness=0,
                    )
                    fallback_close.place(relx=1.0, x=-6, y=4, anchor="ne")
                    fallback_close.lift()

        window.after(0, ensure_titlebar)
        try:
            self._style_settings_widgets(window, self._settings_palette(self._settings_theme_key()))
        except Exception:
            pass
        # X-63: utility windows are ordinary citizens of the desktop -- no
        # always-on-top. Only the pill and its menu float (his order). A
        # window that falls behind is re-raised by opening it again from
        # the pill; single-instance windows refocus rather than duplicate.
        window.attributes("-topmost", False)
        self.utility_windows[name] = window

        def forget(event: tk.Event | None = None) -> None:
            if event is not None and event.widget is not window:
                return
            # A close fade can overlap an immediate reopen.  The retiring old
            # instance must never erase the new same-name window or run the new
            # instance's disposer when its delayed Destroy finally arrives.
            is_current = self.utility_windows.get(name) is window
            # X-175: dispose BEFORE forgetting the window. Every close path in
            # this app funnels through <Destroy> -- the feature toggle, the two
            # separate X controls, Escape, and WM_DELETE_WINDOW -- so this is
            # the one place a surface can be certain of being told. Live
            # captions had five ways to close and none of them stopped its
            # microphone, because the stop lived only on the START/STOP label
            # inside the window that had just been destroyed.
            self._dispose_window_instance(window, names=(name,))
            if is_current and resizable:
                # Window-size receipts are UI state, not a Settings-form edit.
                # Persist the already debounced logical receipt directly so a
                # close followed by a DPI change cannot lose the resize. Do not
                # call the heavier save_settings path, which also prepares the
                # formatter and would make closing a window feel slow.
                with contextlib.suppress(Exception):
                    from .config import save_config

                    save_config(self.config)
            if is_current:
                self.utility_windows.pop(name, None)
            if getattr(self, "_last_minimized_utility", None) is window:
                self._last_minimized_utility = None
            self._minimized_utility_stack = [
                candidate
                for candidate in getattr(self, "_minimized_utility_stack", [])
                if candidate is not window
            ]
            if (
                getattr(self, "_last_minimized_utility", None) is None
                and self._minimized_utility_stack
            ):
                self._last_minimized_utility = self._minimized_utility_stack[-1]

        if resizable and remember_size:
            def remember_size(event: tk.Event) -> None:
                if event.widget is not window:
                    return
                if getattr(window, "_talkdat_live_resize", False):
                    return
                try:
                    sizes = self.config.setdefault("ui", {}).setdefault("window_sizes", {})
                    sizes[name] = ui_scale.window_size_receipt(
                        window.winfo_width(),
                        window.winfo_height(),
                        self.config,
                    )
                except Exception:
                    pass

            window.bind("<Configure>", remember_size, add="+")
            window.bind("<<TalkDATGeometrySettled>>", remember_size, add="+")

        window.bind("<Destroy>", forget, add="+")
        window.bind("<Escape>", lambda _event: self._request_utility_close(window), add="+")
        if minimizable:
            # The custom chrome has no Windows system menu. Mirror the visible
            # Minimize mnemonic so keyboard users retain a direct window action.
            window.bind(
                "<Alt-m>",
                lambda _event: (self._request_utility_minimize(window), "break")[1],
                add="+",
            )
            if sys.platform == "darwin":
                window.bind(
                    "<Command-m>",
                    lambda _event: (self._request_utility_minimize(window), "break")[1],
                    add="+",
                )
        window.protocol("WM_DELETE_WINDOW", lambda: self._request_utility_close(window))
        # X-538: the per-window help chip and theme brush are GONE, and their
        # removal is the fix rather than a loss.
        #
        # Both were second doors into Settings, wedged into a titlebar with no
        # room for them and positioned by absolute pixel guesses that were
        # re-patched three times (X-92, X-401, X-459) and still landed on the
        # Minimize button in his screenshot. Theme lives in Settings > Colors
        # and feedback in Settings > General; neither ever needed a copy in the
        # chrome of all fifteen surfaces, and a control that exists twice is a
        # control whose two copies drift.
        if not name.startswith("feedback") and name != "captions":
            window.after(0, lambda: self._wrap_text_to_its_column(window))
        if name not in {"captions", "ramble_pick", "taste_race", "onboarding"}:
            # X-149: the onboarding is a guided corridor -- a sidebar
            # inviting exits (and rendering broken white on the Mac) has no
            # business there.
            # X-63: from ANY menu, every other menu is VISIBLE -- an open
            # left sidebar in the Claude/ChatGPT shape, glued to the window,
            # slide-collapsible, never the pill popup.
            window._talkdat_pending_menu_rail_current = name  # type: ignore[attr-defined]
        # X-09: after the caller lays out its widgets, the whole window drags
        # from any inert surface.
        window.after(0, lambda: self._bind_drag_anywhere(window))
        try:
            window.iconbitmap(str(ensure_icon_file()))
        except Exception:
            pass
        if resizable:
            if name != "captions":
                self._install_utility_resize_grip(
                    window,
                    minimum_size=minimum_size or (320, 220),
                    bg=bg,
                )
            # X-73: the corner grip alone is the cheap version. Every
            # resizable window takes a drag on ANY edge or corner, with the
            # right cursor -- the captions window's behavior, everywhere.
            floor_w, floor_h = minimum_size or (320, 220)
            self._bind_edge_resize(window, floor_w, floor_h)
        transactions = getattr(self, "_utility_build_transactions", None)
        if isinstance(transactions, list) and transactions:
            transactions[-1].append(window)
        else:
            self._commit_utility_window_build(window)
        return window

    def _install_toplevel_timer_cleanup(self, window: tk.Toplevel) -> None:
        """Cancel callbacks owned by a utility window before destroying it.

        A Toplevel shares its Tcl interpreter with the pill, so cancelling the
        interpreter's entire queue would also stop the pill.  Match queued
        scripts against this window's own registered command list instead.
        """
        original_destroy = window.destroy
        destroyed = False

        def destroy_safely() -> None:
            nonlocal destroyed
            if destroyed:
                return
            destroyed = True
            # X-183: dispose FIRST, while the children are still alive.
            #
            # Tk destroys a Toplevel's CHILDREN BEFORE the Toplevel's own
            # <Destroy> binding fires. Measured directly:
            #
            #   ('binding-fired', '.!toplevel.!text', top_exists=True,  text_exists=False)
            #
            # So a disposer hung on <Destroy> -- which is where X-175 put them --
            # sees dead widgets. Scratchpad's final flush is guarded by
            # `text.winfo_exists()`, so it returned silently and the last edits
            # were lost through the shared X control, which calls destroy()
            # directly and cannot be intercepted any other way.
            #
            # Looked up BY IDENTITY rather than by a captured name: the shared
            # shell is registered under whichever page currently owns it, which
            # is not necessarily the page that created the window.
            try:
                for key in [k for k, v in list(self.utility_windows.items()) if v is window]:
                    self._dispose_window(key)
            except Exception:
                log.exception("disposal during destroy failed")
            self._cancel_window_geometry_motion(window)
            # Geometry destruction itself emits Configure events. Stop the two
            # debounced painters before that final event can enqueue fresh
            # work behind the cancellation sweep.
            try:
                window.unbind("<Configure>")
            except Exception:
                pass
            # Timers scheduled through a canvas or label still outlive the
            # Toplevel unless they are cancelled. Include every descendant,
            # not only callbacks registered directly on the window.
            self._cancel_toplevel_owned_callbacks(window)
            try:
                original_destroy()
            except tk.TclError:
                pass
            # Destroy emits final Configure/visibility events. Their handlers
            # can enqueue one last region or texture paint after the first
            # sweep but before Tcl deletes the callback command.
            self._cancel_toplevel_owned_callbacks(window)

        window.destroy = destroy_safely  # type: ignore[method-assign]

    def _open_theme_picker(self, anchor: tk.Widget, variable: tk.StringVar) -> None:
        """Theme list where every row is painted in the theme it names.

        Fifty entries in a plain dropdown are fifty identical lines, so the
        range was invisible and people did not realise the list scrolled.
        Showing each name in its own panel and text colour makes the choice
        legible at a glance and the length obvious.
        """
        existing = getattr(self, "_theme_picker", None)
        if existing is not None:
            try:
                if existing.winfo_exists():
                    # The anchor is a toggle while its picker is open.  Retire
                    # the one owned popup through the shared motion path rather
                    # than briefly stacking a replacement over a direct destroy.
                    self._request_popup_close(existing)
                    return
            except Exception:
                pass
            if getattr(self, "_theme_picker", None) is existing:
                self._theme_picker = None
        options = self._settings_theme_options()
        popup: tk.Toplevel | None = None
        try:
            picker_palette = self._settings_palette(variable.get())
            popup = self._new_toplevel(
                anchor.winfo_toplevel(),
                role=AUXILIARY_CHROME,
            )
            popup.transient(anchor.winfo_toplevel())
            popup.overrideredirect(True)
            popup.attributes("-topmost", True)
            with contextlib.suppress(Exception):
                popup.attributes("-alpha", 0.0)
            # A Listbox cannot draw anything but text, so the old "preview"
            # was the row tinted with the theme's panel colour -- one colour out
            # of the five that actually make a theme look like itself. Each row
            # is its own small frame now, showing the background, the panel, the
            # accent and real text together, which is what you are choosing
            # between.
            picker_width = ui_scale.px(340, self.config)
            visible_rows = min(12, len(options))
            picker_height = visible_rows * ui_scale.px(44, self.config)
            canvas = tk.Canvas(
                popup,
                highlightthickness=0,
                bd=0,
                width=picker_width,
                bg=picker_palette["panel"],
                height=picker_height,
            )
            scroll = ttk.Scrollbar(
                popup,
                orient="vertical",
                command=canvas.yview,
                style="Flow.Vertical.TScrollbar",
            )
            canvas.configure(yscrollcommand=scroll.set)
            canvas.pack(side="left", fill="both", expand=True)
            scroll.pack(side="right", fill="y")
            rows = tk.Frame(canvas, bg=picker_palette["panel"])
            window_id = canvas.create_window((0, 0), window=rows, anchor="nw")
            rows.bind("<Configure>", lambda _e: canvas.configure(scrollregion=canvas.bbox("all")))
            canvas.bind("<Configure>", lambda e: canvas.itemconfigure(window_id, width=e.width))
            # Bound to the canvas, not bind_all: bind_all is application-wide
            # and is not removed when this popup closes, so a dismissed theme
            # list would go on swallowing the wheel everywhere in the app.
            def wheel_picker(event: tk.Event) -> str:
                delta = int(getattr(event, "delta", 0))
                canvas.yview_scroll(-1 if delta > 0 else 1, "units")
                return "break"

            canvas.bind("<MouseWheel>", wheel_picker, add="+")
            rows.bind("<MouseWheel>", wheel_picker, add="+")

            def forget_picker() -> None:
                # A retired picker must never clear a newer one opened from a
                # replacement host while its fade was finishing.
                if getattr(self, "_theme_picker", None) is popup:
                    self._theme_picker = None

            def pick(option: str) -> None:
                # Applying a theme can repaint or replace the picker host.  Let
                # the popup finish its own lifecycle first, then mutate the
                # watched variable exactly once from the close completion.
                def apply_choice() -> None:
                    forget_picker()
                    variable.set(option)

                self._request_popup_close(popup, on_complete=apply_choice)

            current = variable.get()
            theme_buttons: list[tk.Button] = []
            for option in options:
                family, _, mode = option.rpartition(" ")
                palette = SETTINGS_THEME_PALETTES.get(family, {}).get(mode)
                if not palette:
                    continue
                # X-337: each bar IS the theme's MATERIAL (select tinted
                # toward accent) with the ink picked by measured contrast --
                # the bg token painted every dark theme the same near-black.
                material = theme_material(palette, mode)
                ink = material_ink(palette, material)
                row = tk.Frame(rows, bg=material)
                row.pack(fill="x", padx=0, pady=0)
                button = FlatButton(
                    row,
                    text=option,
                    command=lambda o=option: pick(o),
                    bg=material,
                    fg=ink,
                    activebackground=blend_hex(material, ink, 0.12),
                    activeforeground=ink,
                    font=(BRAND_UI_FAMILY, type_scale.CAPTION, "bold"),
                    anchor="w",
                    relief="flat",
                    bd=0,
                    padx=ui_scale.spacing(12, self.config),
                    pady=ui_scale.spacing(8, self.config),
                    takefocus=1,
                    highlightthickness=ui_scale.px(2, self.config),
                    highlightbackground=palette["accent"] if option == current else material,
                    highlightcolor=palette["accent"],
                    cursor="hand2",
                )
                button.pack(side="left", fill="x", expand=True)
                accent_swatch = tk.Frame(
                    row,
                    bg=palette["accent"],
                    width=ui_scale.px(28, self.config),
                    height=ui_scale.px(16, self.config),
                    cursor="hand2",
                )
                accent_swatch.pack(side="right", padx=ui_scale.spacing((4, 12), self.config))
                panel_swatch = tk.Frame(
                    row,
                    bg=palette["panel"],
                    width=ui_scale.px(28, self.config),
                    height=ui_scale.px(16, self.config),
                    cursor="hand2",
                )
                panel_swatch.pack(side="right")
                for swatch in (accent_swatch, panel_swatch):
                    swatch.bind(
                        "<Button-1>",
                        lambda _e, target=button: (target.focus_set(), target.invoke(), "break")[-1],
                    )
                    swatch.bind("<MouseWheel>", wheel_picker, add="+")
                button.bind("<Return>", lambda _e, target=button: (target.invoke(), "break")[-1], add="+")
                row.bind("<MouseWheel>", wheel_picker, add="+")
                button.bind("<MouseWheel>", wheel_picker, add="+")
                theme_buttons.append(button)

            def close_picker(_event: tk.Event | None = None) -> str:
                self._request_popup_close(
                    popup,
                    on_complete=forget_picker,
                )
                return "break"

            def move_theme_focus(source: tk.Button, target_index: int) -> str:
                if not theme_buttons:
                    return "break"
                try:
                    index = theme_buttons.index(source)
                except ValueError:
                    index = 0
                if target_index == -2:
                    index = 0
                elif target_index == 2:
                    index = len(theme_buttons) - 1
                else:
                    index = (index + target_index) % len(theme_buttons)
                target = theme_buttons[index]
                target.focus_set()
                canvas.yview_moveto(max(0.0, index / max(1, len(theme_buttons) - 1)))
                return "break"

            for button in theme_buttons:
                button.bind("<Up>", lambda _e, source=button: move_theme_focus(source, -1), add="+")
                button.bind("<Down>", lambda _e, source=button: move_theme_focus(source, 1), add="+")
                button.bind("<Home>", lambda _e, source=button: move_theme_focus(source, -2), add="+")
                button.bind("<End>", lambda _e, source=button: move_theme_focus(source, 2), add="+")

            popup.bind("<Escape>", close_picker)

            def forget_destroyed_picker(event: tk.Event) -> None:
                if event.widget is popup:
                    forget_picker()

            popup.bind("<Destroy>", forget_destroyed_picker, add="+")

            def dismiss_if_focus_left(_event: tk.Event | None = None) -> None:
                def check() -> None:
                    with contextlib.suppress(Exception):
                        focused = popup.focus_get()
                        if focused is None or focused.winfo_toplevel() is not popup:
                            close_picker()

                popup.after_idle(check)

            popup.bind("<FocusOut>", dismiss_if_focus_left, add="+")

            popup.update_idletasks()
            x = anchor.winfo_rootx()
            y = anchor.winfo_rooty() + anchor.winfo_height()
            # Flip above the button when there is no room below, so the list is
            # never cut off by the bottom of the screen.
            if y + popup.winfo_reqheight() > popup.winfo_screenheight() - 8:
                y = max(8, anchor.winfo_rooty() - popup.winfo_reqheight())
            # X-145: clamp to the ANCHOR'S monitor, not to a 0-origin
            # virtual guess. On a monitor mounted ABOVE the primary, root
            # coordinates are NEGATIVE; max(0, y) teleported the popup to
            # the primary display behind everything, which read as "the
            # color list does not work" with no error anywhere -- his
            # exact report, on his exact monitor layout.
            rect = self._window_monitor_work_area(anchor.winfo_toplevel())
            if rect is not None:
                mon_left, mon_top, mon_right, mon_bottom = rect
            else:
                mon_left, mon_top = 0, 0
                mon_right = popup.winfo_screenwidth()
                mon_bottom = popup.winfo_screenheight()
            x = max(mon_left + 8, min(int(x), mon_right - popup.winfo_reqwidth() - 8))
            y = max(mon_top + 8, min(int(y), mon_bottom - popup.winfo_reqheight() - 8))
            popup.geometry(f"+{int(x)}+{int(y)}")
            # Publish ownership before focus can emit a FocusOut/Destroy cycle;
            # the guarded teardown then always has the correct object to clear.
            self._theme_picker = popup
            with contextlib.suppress(tk.TclError):
                popup.focus_force()
                selected = next(
                    (button for button in theme_buttons if str(button.cget("text")) == current),
                    theme_buttons[0] if theme_buttons else None,
                )
                if selected is not None:
                    selected_index = theme_buttons.index(selected)
                    canvas.yview_moveto(max(0.0, selected_index / max(1, len(theme_buttons) - 1)))
                    selected.focus_set()
            self._schedule_popup_present(popup)
        except Exception:
            log.warning("theme picker failed to open", exc_info=True)
            if popup is not None:
                with contextlib.suppress(Exception):
                    popup.destroy()
                if getattr(self, "_theme_picker", None) is popup:
                    self._theme_picker = None

    def _settings_theme_options(self) -> list[str]:
        return [f"{family} {mode}" for family in SETTINGS_THEME_FAMILIES for mode in ("Dark", "Light")]

    def _settings_theme_key(self, value: str | None = None) -> str:
        raw = str(value or "").strip()
        if not raw:
            raw = str(self.config.setdefault("ui", {}).get("settings_theme") or self.config.get("ui", {}).get("theme") or "Flow Dark")
        aliases = {
            "dark": "Flow Dark",
            "light": "Flow Light",
            "flow": "Flow Dark",
            "noir": "Aqua Noir Dark",
        }
        normalized = aliases.get(raw.lower(), raw)
        options = self._settings_theme_options()
        for option in options:
            if option.lower() == normalized.lower():
                return option
        return "Flow Light" if normalized.lower().endswith("light") else "Flow Dark"

    def _settings_palette(self, theme: str) -> dict[str, str]:
        theme = self._settings_theme_key(theme)
        family = theme.removesuffix(" Dark").removesuffix(" Light")
        mode = "Light" if theme.endswith("Light") else "Dark"
        base = SETTINGS_THEME_PALETTES.get(family, SETTINGS_THEME_PALETTES["Flow"]).get(mode)
        if base is None:
            base = SETTINGS_THEME_PALETTES["Flow"][mode]
        palette = dict(base)
        palette["name"] = theme
        palette["mode"] = mode.lower()
        # Utility windows need functional colours as semantic roles rather
        # than one-off hex values.  The theme catalog deliberately describes
        # material (stone, plaster, neon, and so on); ``warm`` is therefore
        # sometimes green or blue and cannot truthfully mean warning/danger.
        # These roles stay stable across every material while retaining the
        # selected theme for all non-functional surfaces.
        if mode == "Light":
            palette.update(
                success="#17624f",
                warning="#704d00",
                danger="#94253c",
                on_danger="#ffffff",
            )
        else:
            palette.update(
                success="#73e0b7",
                warning="#ffd166",
                danger="#ff7d94",
                on_danger="#000000",
            )

        def luminance(color: str) -> float:
            channels = [int(color[index:index + 2], 16) / 255.0 for index in (1, 3, 5)]
            linear = [
                value / 12.92 if value <= 0.04045 else ((value + 0.055) / 1.055) ** 2.4
                for value in channels
            ]
            return 0.2126 * linear[0] + 0.7152 * linear[1] + 0.0722 * linear[2]

        def contrast_ratio(first: str, second: str) -> float:
            lighter, darker = sorted((luminance(first), luminance(second)), reverse=True)
            return (lighter + 0.05) / (darker + 0.05)

        def contrast_ink(surface: str) -> str:
            surface_luminance = luminance(surface)
            dark = "#000000"
            light = "#ffffff"
            dark_ratio = (surface_luminance + 0.05) / (luminance(dark) + 0.05)
            light_ratio = (luminance(light) + 0.05) / (surface_luminance + 0.05)
            return dark if dark_ratio >= light_ratio else light

        def strongest_ring(*surfaces: str) -> str:
            return max(
                ("#000000", "#ffffff"),
                key=lambda candidate: min(
                    contrast_ratio(candidate, surface) for surface in surfaces
                ),
            )

        def readable_muted(*surfaces: str) -> str:
            # Disabled state is communicated by state and surface as well as
            # colour. Keep its copy quieter than body text without letting a
            # theme turn an informative disabled value illegible.
            for step in range(21):
                candidate = blend_hex(palette["muted"], palette["text"], step / 20.0)
                if min(contrast_ratio(candidate, surface) for surface in surfaces) >= 4.5:
                    return candidate
            return palette["text"]

        def focus_surface(surface: str, adjacent: str) -> tuple[str, str]:
            # The filled focus state itself carries a 3:1 boundary. Its ink is
            # also the inner focus line, giving primary and destructive buttons
            # a visible focused state without depending on one accent colour to
            # contrast with every material in the 50-theme catalog.
            target = strongest_ring(adjacent)
            for step in range(21):
                candidate = blend_hex(surface, target, step / 20.0)
                ink = contrast_ink(candidate)
                if (
                    contrast_ratio(candidate, adjacent) >= 3.0
                    and contrast_ratio(ink, candidate) >= 4.5
                ):
                    return candidate, ink
            return target, contrast_ink(target)

        # A mode-based ink choice is not sufficient: a few intentionally
        # unusual palettes use a mid-tone accent. Pick the higher-contrast ink
        # from the actual colour so primary buttons remain readable in all 50
        # catalog themes.
        palette["on_accent"] = contrast_ink(palette["accent"])
        palette["on_accent2"] = contrast_ink(palette["accent2"])
        palette["disabled_text"] = readable_muted(
            palette["button"], palette["panel"], palette["field"]
        )
        palette["focus_ring"] = strongest_ring(
            palette["button"], palette["panel"], palette["field"]
        )
        for role, source in (
            ("button", palette["select"]),
            ("accent", palette["accent"]),
            ("danger", palette["danger"]),
        ):
            focus_fill, focus_ink = focus_surface(source, palette["panel"])
            palette[f"{role}_focus"] = focus_fill
            palette[f"on_{role}_focus"] = focus_ink
        return palette

    def _provider_status_text(self, provider_id: str) -> str:
        provider = PROVIDER_BY_ID.get(provider_id, PROVIDER_BY_ID["deepgram"])
        if provider.api_kind == "external":
            return "Not available in this build. Your current provider remains selected when settings are saved."
        if provider.id == "deepgram":
            return "Ready: live transcription. It starts only after a trigger or Pill click."
        if provider.api_kind == "openai_batch":
            return "Ready: batch transcription through an OpenAI-compatible service."
        if provider.id == "elevenlabs":
            return "Ready: batch speech-to-text conversion."
        if provider.id == "assemblyai":
            return "Ready: batch transcription with automatic job monitoring."
        if provider.id == "google_gemini":
            return "Ready: batch audio transcription through Gemini."
        if provider.id == "xai":
            return "Ready: formatted batch transcription through xAI."
        if provider.id == "smallest":
            return "Ready: batch transcription through Smallest.ai Pulse or Pulse Pro."
        if provider.id == "soniox":
            return "Ready: asynchronous transcription with automatic remote cleanup."
        return "Registered provider. Check docs and adapter status before relying on it."

    def _settings_path_row(
        self,
        parent: tk.Widget,
        label: str,
        path: Path | str,
        palette: dict[str, str],
    ) -> tk.Frame:
        """A stored location as a caption, a chip and a button.

        Settings printed raw Windows paths as ordinary paragraph text -- the
        history file, the history database, the full transcript, the live
        draft and the settings file, five lines of
        ``C:\\Users\\<name>\\AppData\\Roaming\\...`` set in the same face and
        colour as the sentence above them. Nobody retypes a path from a
        window, everybody who wants one wants the folder open, and the only
        thing it reliably achieved was putting the customer's user name on
        screen.

        The caption stays, the path becomes a middle-ellipsised monospace
        chip, and the action becomes an action. The returned frame carries
        ``_talkdat_apply_palette`` so a theme change can repaint the chip,
        which the generic Settings repaint walk would otherwise flatten into
        the panel colour.
        """

        space = lambda value: ui_scale.spacing(value, self.config)
        target = Path(str(path))
        row = tk.Frame(parent, bg=palette["panel"], bd=0, highlightthickness=0)
        row.columnconfigure(1, weight=1)
        caption = tk.Label(
            row,
            text=label,
            bg=palette["panel"],
            fg=palette["muted"],
            font=(BRAND_UI_FAMILY, type_scale.BODY),
            anchor="w",
        )
        caption.grid(row=0, column=0, sticky="w", padx=space((0, 12)))
        chip = tk.Label(
            row,
            text=shortened_path(target),
            bg=palette["field"],
            fg=palette["text"],
            font=(mac_support.FONT_MONO, type_scale.SECONDARY),
            anchor="w",
            bd=0,
            highlightthickness=1,
            highlightbackground=palette["stroke"],
            padx=space(8),
            pady=space(4),
        )
        chip.grid(row=0, column=1, sticky="w")

        def reveal() -> None:
            folder = target if target.is_dir() else target.parent
            try:
                folder.mkdir(parents=True, exist_ok=True)
                os.startfile(str(folder))  # type: ignore[attr-defined]
            except (AttributeError, OSError, ValueError) as exc:
                # A missing drive, a denied folder, or a non-Windows Tk build.
                # Saying so beats a button that silently does nothing.
                self.set_state("error", f"Could not open that folder: {exc}", "")

        button = ttk.Button(row, text="Show in Explorer", command=reveal, style="Flow.TButton")
        button.grid(row=0, column=2, sticky="e", padx=space((12, 0)))

        def apply_palette(latest: dict[str, str]) -> None:
            with contextlib.suppress(tk.TclError):
                row.configure(bg=latest["panel"])
                caption.configure(bg=latest["panel"], fg=latest["muted"])
                chip.configure(
                    bg=latest["field"],
                    fg=latest["text"],
                    highlightbackground=latest["stroke"],
                )

        row._talkdat_apply_palette = apply_palette  # type: ignore[attr-defined]
        row._talkdat_full_path = str(target)  # type: ignore[attr-defined]
        return row

    def _style_settings_widgets(self, window: tk.Toplevel, palette: dict[str, str]) -> None:
        style = ttk.Style(window)
        space = lambda value: ui_scale.spacing(value, self.config)
        metric = lambda value: ui_scale.px(value, self.config)
        body_font = (BRAND_UI_FAMILY, type_scale.BODY)
        control_font = (BRAND_UI_FAMILY, type_scale.BODY)
        # A button label sits one step under body, which is the rule the design
        # brief states and also what keeps a row of actions from outgrowing the
        # windows that were laid out around them. These styles are shared with
        # Scratchpad, History, Status and Account, so this font is the widest
        # blast radius in the file.
        strong_control_font = (BRAND_UI_FAMILY, type_scale.SECONDARY, "bold")
        try:
            style.theme_use("clam")
        except tk.TclError:
            pass
        style.configure(
            "Flow.TNotebook",
            background=palette["bg"],
            borderwidth=0,
            tabmargins=space((0, 4, 0, 0)),
        )
        style.configure(
            "Flow.TNotebook.Tab",
            background=palette["button"],
            foreground=palette["muted"],
            padding=space((16, 12)),
            font=strong_control_font,
        )
        style.map(
            "Flow.TNotebook.Tab",
            background=[("selected", palette["surface"])],
            foreground=[("selected", palette["text"])],
        )
        style.configure("Flow.TFrame", background=palette["panel"])
        style.configure(
            "Flow.TLabel",
            background=palette["panel"],
            foreground=palette["text"],
            font=body_font,
        )
        style.configure(
            "Flow.Muted.TLabel",
            background=palette["panel"],
            foreground=palette["muted"],
            font=body_font,
        )
        style.configure(
            "Flow.Footer.TLabel",
            background=palette["bg"],
            foreground=palette["muted"],
            font=body_font,
        )
        style.configure(
            "Flow.FooterWarning.TLabel",
            background=palette["bg"],
            foreground=palette["warning"],
            font=strong_control_font,
        )
        style.configure(
            "Flow.FooterSaving.TLabel",
            background=palette["bg"],
            foreground=palette["accent"],
            font=body_font,
        )
        style.configure(
            "Flow.FooterSuccess.TLabel",
            background=palette["bg"],
            foreground=palette["success"],
            font=strong_control_font,
        )
        style.configure(
            "Flow.FooterError.TLabel",
            background=palette["bg"],
            foreground=palette["danger"],
            font=strong_control_font,
        )
        style.configure(
            "Flow.Vertical.TScrollbar",
            background=palette["button"],
            troughcolor=palette["panel"],
            bordercolor=palette["stroke"],
            arrowcolor=palette["muted"],
            lightcolor=palette["button"],
            darkcolor=palette["button"],
            arrowsize=metric(16),
        )
        style.map(
            "Flow.Vertical.TScrollbar",
            background=[("pressed", palette["accent"]), ("active", palette["select"])],
            arrowcolor=[("pressed", palette["text"]), ("active", palette["text"])],
        )
        # Keyboard focus has to be visible. Every style below mapped "active",
        # which is the mouse hover state, and nothing mapped "focus" -- so
        # tabbing through Settings moved an invisible cursor and there was no
        # way to tell which control Enter or Space would operate. The windows
        # are overrideredirect and have no OS focus ring to fall back on.
        #
        # `select` is reused for focus because it is already proven readable
        # against `text`: it is what hover uses.
        style.configure(
            "Flow.TCheckbutton",
            background=palette["panel"],
            foreground=palette["text"],
            font=control_font,
            padding=space((4, 4)),
        )
        # The same gap again, for the path where the generated indicator below
        # cannot be built and clam's own indicator is what gets drawn. clam
        # ships `-indicatormargin {1 1 4 1}`; four pixels between a box and its
        # label reads as glued. Guarded because the option only exists on
        # themes that draw an indicator element.
        with contextlib.suppress(tk.TclError):
            style.configure("Flow.TCheckbutton", indicatormargin=space((0, 0, 12, 0)))
        style.map(
            "Flow.TCheckbutton",
            background=[
                ("disabled", palette["panel"]),
                ("focus", palette["button_focus"]),
                ("active", palette["panel"]),
            ],
            foreground=[
                ("disabled", palette["disabled_text"]),
                ("focus", palette["on_button_focus"]),
            ],
        )
        style.configure(
            "Flow.TButton",
            background=palette["button"],
            foreground=palette["text"],
            padding=space((12, 8)),
            font=strong_control_font,
            borderwidth=metric(2),
            focusthickness=metric(2),
            focussolid=1,
            relief="flat",
        )
        style.map(
            "Flow.TButton",
            # Disabled must win over focus when an async action temporarily
            # disables the control that still owns keyboard focus.
            background=[
                ("disabled", palette["button"]),
                ("pressed", palette["select"]),
                ("focus", palette["select"]),
                ("active", palette["select"]),
            ],
            foreground=[
                ("disabled", palette["disabled_text"]),
            ],
            bordercolor=[
                ("disabled", palette["stroke"]),
                ("focus", palette["text"]),
            ],
            lightcolor=[
                ("disabled", palette["stroke"]),
                ("focus", palette["text"]),
            ],
            darkcolor=[
                ("disabled", palette["stroke"]),
                ("focus", palette["text"]),
            ],
            focuscolor=[
                ("disabled", palette["button"]),
                ("focus", palette["text"]),
            ],
        )
        style.configure(
            "Flow.TEntry",
            fieldbackground=palette["field"],
            foreground=palette["text"],
            insertcolor=palette["text"],
            borderwidth=metric(1),
            padding=space((12, 8)),
            font=control_font,
        )
        style.map(
            "Flow.TEntry",
            foreground=[
                ("disabled", palette["disabled_text"]),
                ("readonly", palette["text"]),
            ],
            fieldbackground=[
                ("disabled", palette["panel"]),
                ("readonly", palette["field"]),
            ],
            bordercolor=[("disabled", palette["stroke"]), ("focus", palette["text"])],
            lightcolor=[("disabled", palette["stroke"]), ("focus", palette["text"])],
        )
        style.configure(
            "Flow.Accent.TButton",
            background=palette["accent"],
            foreground=palette["on_accent"],
            padding=space((16, 8)),
            font=strong_control_font,
            borderwidth=metric(2),
            focusthickness=metric(2),
            focussolid=1,
            relief="flat",
        )
        style.map(
            "Flow.Accent.TButton",
            background=[
                ("disabled", palette["button"]),
                ("pressed", palette["accent2"]),
                ("active", palette["accent2"]),
            ],
            foreground=[
                ("disabled", palette["disabled_text"]),
                ("pressed", palette["on_accent2"]),
                ("active", palette["on_accent2"]),
            ],
            bordercolor=[("disabled", palette["stroke"]), ("focus", palette["text"])],
            lightcolor=[("disabled", palette["stroke"]), ("focus", palette["text"])],
            darkcolor=[("disabled", palette["stroke"]), ("focus", palette["text"])],
            focuscolor=[
                ("disabled", palette["button"]),
                ("pressed", "focus", palette["on_accent2"]),
                ("active", "focus", palette["on_accent2"]),
                ("focus", palette["on_accent"]),
            ],
        )
        style.configure(
            "Flow.Danger.TButton",
            background=palette["danger"],
            foreground=palette["on_danger"],
            padding=space((12, 8)),
            font=strong_control_font,
            borderwidth=metric(2),
            focusthickness=metric(2),
            focussolid=1,
            relief="flat",
        )
        style.map(
            "Flow.Danger.TButton",
            background=[
                ("disabled", palette["button"]),
            ],
            foreground=[
                ("disabled", palette["disabled_text"]),
            ],
            bordercolor=[("disabled", palette["stroke"]), ("focus", palette["text"])],
            lightcolor=[("disabled", palette["stroke"]), ("focus", palette["text"])],
            darkcolor=[("disabled", palette["stroke"]), ("focus", palette["text"])],
            focuscolor=[
                ("disabled", palette["button"]),
                ("focus", palette["on_danger"]),
            ],
        )
        style.configure(
            "Flow.Horizontal.TProgressbar",
            background=palette["accent"],
            troughcolor=palette["field"],
            bordercolor=palette["stroke"],
            lightcolor=palette["accent"],
            darkcolor=palette["accent"],
        )
        style.configure(
            "Flow.TCombobox",
            fieldbackground=palette["field"],
            background=palette["button"],
            foreground=palette["text"],
            arrowcolor=palette["accent"],
            # X-62 "make it a more solid drop down": real padding and a
            # visible border instead of clam's hairline-on-flat default.
            padding=space((12, 8)),
            bordercolor=palette["stroke"],
            lightcolor=palette["stroke"],
            darkcolor=palette["stroke"],
            arrowsize=metric(16),
            font=control_font,
        )

        # Ported from the Mac agent's find (mac-port d706525): nearly every
        # combobox here is state="readonly", and clam takes a readonly
        # widget's colours from the state MAP, not configure() -- with no map
        # they fall back to the theme's light grey, so "System default
        # microphone" rendered pale-on-pale in Settings and onboarding.
        style.map(
            "Flow.TCombobox",
            fieldbackground=[("disabled", palette["panel"]), ("readonly", palette["field"])],
            foreground=[("disabled", palette["disabled_text"]), ("readonly", palette["text"])],
            selectbackground=[("disabled", palette["panel"]), ("readonly", palette["field"])],
            selectforeground=[("disabled", palette["disabled_text"]), ("readonly", palette["text"])],
            background=[
                ("disabled", palette["panel"]),
                ("pressed", palette["select"]),
                ("active", palette["select"]),
                ("readonly", palette["button"]),
            ],
            arrowcolor=[
                ("disabled", palette["disabled_text"]),
                ("pressed", palette["text"]),
                ("active", palette["text"]),
                ("focus", palette["text"]),
                ("readonly", palette["accent"]),
            ],
            bordercolor=[
                ("disabled", palette["stroke"]),
                ("focus", palette["text"]),
                ("readonly", palette["stroke"]),
            ],
            lightcolor=[
                ("disabled", palette["stroke"]),
                ("focus", palette["text"]),
                ("readonly", palette["stroke"]),
            ],
            darkcolor=[
                ("disabled", palette["stroke"]),
                ("focus", palette["text"]),
                ("readonly", palette["stroke"]),
            ],
        )

        style.configure(
            "Flow.TRadiobutton",
            background=palette["panel"],
            foreground=palette["text"],
            padding=space((4, 4)),
            font=control_font,
        )
        style.map(
            "Flow.TRadiobutton",
            background=[
                ("disabled", palette["panel"]),
                ("focus", palette["button_focus"]),
                ("active", palette["panel"]),
            ],
            foreground=[
                ("disabled", palette["disabled_text"]),
                ("focus", palette["on_button_focus"]),
            ],
        )

        # X-92 field report: clam's flat indicator was replaced with generated
        # unchecked and checked masters from the same semantic family as every
        # other action icon. The renderer supplies the current theme colours;
        # cached PhotoImages keep Tk from dropping the style element.
        try:
            self._checkbox_images = getattr(self, "_checkbox_images", {})
            indicator_size = metric(16)
            cache_key = (
                palette["field"],
                palette["muted"],
                palette["accent"],
                palette["text"],
                indicator_size,
            )
            if cache_key not in self._checkbox_images:
                box_off = self._ui_icon_photo(
                    "checkbox_off",
                    indicator_size,
                    palette["field"],
                    palette["muted"],
                )
                box_on = self._ui_icon_photo(
                    "checkbox_on",
                    indicator_size,
                    palette["accent"],
                    palette["text"],
                )
                self._checkbox_images[cache_key] = (box_off, box_on)
            box_off, box_on = self._checkbox_images[cache_key]
            element = f"FlowCheck.indicator.{abs(hash(cache_key)) % 10_000_000}"
            with contextlib.suppress(tk.TclError):  # element_create is once-per-name
                # The box and its label rendered glued together -- a column of
                # nine reading as one dense block. The trailing inset is the
                # gap between them, so it is a real spacing step rather than
                # the two pixels it was doing nothing with.
                style.element_create(element, "image", box_off,
                                     ("selected", box_on), ("active", "selected", box_on),
                                     sticky="w", padding=space((4, 4, 12, 4)))
            style.layout("Flow.TCheckbutton", [
                ("Checkbutton.padding", {"sticky": "nswe", "children": [
                    (element, {"side": "left", "sticky": ""}),
                    ("Checkbutton.label", {"side": "left", "sticky": "nswe"}),
                ]}),
            ])
        except Exception:
            log.debug("generated checkbox indicator unavailable; clam default stays", exc_info=True)

        # The popdown list is a plain Tk listbox that ignores ttk styling.
        with contextlib.suppress(Exception):
            self.root.option_add("*TCombobox*Listbox.background", palette["field"])
            self.root.option_add("*TCombobox*Listbox.foreground", palette["text"])
            self.root.option_add("*TCombobox*Listbox.selectBackground", palette["select"])
            self.root.option_add("*TCombobox*Listbox.selectForeground", palette["text"])
            self.root.option_add("*TCombobox*Listbox.font", f"{{{BRAND_UI_FAMILY}}} 10")
            # Plain Tk multiline fields do not inherit ttk focus treatment.
            # These defaults cover every field that does not deliberately
            # provide a stronger per-surface treatment.
            self.root.option_add("*Text.highlightThickness", metric(2))
            self.root.option_add("*Text.highlightBackground", palette["stroke"])
            self.root.option_add("*Text.highlightColor", palette["accent"])
            self.root.option_add("*Text.padX", metric(12))
            self.root.option_add("*Text.padY", metric(8))
        style.configure(
            "Flow.Horizontal.TScale",
            background=palette["panel"],
            troughcolor=palette["field"],
            borderwidth=0,
        )

    def _settings_header_layers(
        self,
        width: int,
        height: int,
        palette: dict[str, str],
    ) -> tuple[Image.Image, Image.Image]:
        """Return cached, antialiased plate and sheen layers for a masthead.

        These curves used to be drawn directly at display resolution. At 125
        through 200 percent scaling, the large radius exposed visible steps and
        the corner wedges were filled with the Pill's transparency key even
        though this is an ordinary opaque Canvas. Render the immutable shell at
        4x, downsample once, and cache it separately from the moving waveform.
        """

        metric = lambda value: ui_scale.px(value, self.config)
        width = max(metric(320), int(width))
        height = max(metric(72), int(height))
        light = palette["mode"] == "light"
        cache_key = (
            width,
            height,
            round(float(ui_scale.scale(self.config)), 3),
            palette["bg"],
            palette["stroke"],
            light,
        )
        cache = getattr(self, "_settings_header_surface_cache", None)
        if not isinstance(cache, dict):
            cache = {}
            self._settings_header_surface_cache = cache
        cached = cache.get(cache_key)
        if cached is not None:
            return cached

        supersample = 4

        def scaled_box(values: tuple[int, int, int, int]) -> tuple[int, int, int, int]:
            return tuple(int(value) * supersample for value in values)  # type: ignore[return-value]

        large_size = (width * supersample, height * supersample)
        background = (*self._rgb(palette["bg"]), 255)
        plate = Image.new("RGBA", large_size, background)
        glass = Image.new("RGBA", large_size, (0, 0, 0, 0))
        glass_draw = ImageDraw.Draw(glass)
        glass_fill = (255, 255, 255, 214) if light else (7, 18, 20, 224)
        stroke = self._hex_rgba(palette["stroke"], 130 if light else 118)
        glass_draw.rounded_rectangle(
            scaled_box((0, 0, width - 1, height - 1)),
            radius=metric(24) * supersample,
            fill=glass_fill,
            outline=stroke,
            width=max(1, metric(1) * supersample),
        )
        plate = Image.alpha_composite(plate, glass).resize(
            (width, height),
            Image.Resampling.LANCZOS,
        )

        sheen = Image.new("RGBA", large_size, (0, 0, 0, 0))
        sheen_draw = ImageDraw.Draw(sheen)
        sheen_draw.rounded_rectangle(
            scaled_box((metric(2), metric(2), width - metric(3), metric(34))),
            radius=metric(22) * supersample,
            fill=(255, 255, 255, 22 if not light else 68),
        )
        sheen = sheen.resize((width, height), Image.Resampling.LANCZOS)

        if len(cache) >= 16:
            cache.pop(
                next(iter(cache)),
                None,
            )
        cache[cache_key] = (plate, sheen)
        return plate, sheen

    def _settings_receipt_icon_surface(
        self,
        width: int,
        height: int,
        palette: dict[str, str],
    ) -> Image.Image:
        """Render the generated success master in the active theme palette."""

        metric = lambda value: ui_scale.px(value, self.config)
        width = max(metric(40), int(width))
        height = max(metric(40), int(height))
        icon_size = min(width, height)
        icon = render_icon(
            "success",
            icon_size,
            palette["accent"],
            palette["warm"],
        )
        surface = Image.new("RGBA", (width, height), (0, 0, 0, 0))
        surface.alpha_composite(
            icon,
            ((width - icon_size) // 2, (height - icon_size) // 2),
        )
        return surface

    def _settings_meter_surface(
        self,
        width: int,
        height: int,
        fill_width: int,
        hot: bool,
        palette: dict[str, str],
    ) -> Image.Image:
        """Render a smooth meter without supersampling its long flat center.

        Only the curved end caps and hot ring need subpixel coverage. Drawing a
        monitor-wide 4x bitmap every time the level crossed a new cache bucket
        cost 130 ms at 200 percent in measurement. This renderer keeps the
        straight runs at target resolution and supersamples only the small
        curved assets, preserving the contour without reintroducing UI lag.
        """

        metric = lambda value: ui_scale.px(value, self.config)
        width = max(metric(48), int(width))
        height = max(metric(28), int(height))
        fill_width = max(metric(2), min(int(fill_width), width - metric(24)))
        supersample = 4
        image = Image.new(
            "RGBA",
            (width, height),
            (*self._rgb(palette["panel"]), 255),
        )

        def composite(layer: Image.Image, x: int, y: int) -> None:
            source_left = max(0, -int(x))
            source_top = max(0, -int(y))
            source_right = min(layer.width, width - int(x))
            source_bottom = min(layer.height, height - int(y))
            if source_right <= source_left or source_bottom <= source_top:
                return
            destination = (
                int(x) + source_left,
                int(y) + source_top,
                int(x) + source_right,
                int(y) + source_bottom,
            )
            base = image.crop(destination)
            source = layer.crop(
                (source_left, source_top, source_right, source_bottom)
            )
            image.paste(Image.alpha_composite(base, source), destination[:2])

        def pill(
            bounds: tuple[int, int, int, int],
            fill_color: str,
            *,
            outline_color: str | None = None,
            outline_width: int = 0,
        ) -> None:
            x1, y1, x2, y2 = (int(value) for value in bounds)
            pill_width = max(1, x2 - x1)
            pill_height = max(1, y2 - y1)
            fill_rgba = (*self._rgb(fill_color), 255)
            outline_rgba = (
                (*self._rgb(outline_color), 255) if outline_color else None
            )
            stroke = max(0, int(outline_width))

            if pill_width <= pill_height:
                large = Image.new(
                    "RGBA",
                    (pill_width * supersample, pill_height * supersample),
                    (0, 0, 0, 0),
                )
                ImageDraw.Draw(large).rounded_rectangle(
                    (0, 0, large.width - 1, large.height - 1),
                    radius=min(pill_width, pill_height) * supersample // 2,
                    fill=fill_rgba,
                    outline=outline_rgba,
                    width=max(1, stroke * supersample) if outline_rgba else 1,
                )
                composite(
                    large.resize(
                        (pill_width, pill_height),
                        Image.Resampling.LANCZOS,
                    ),
                    x1,
                    y1,
                )
                return

            diameter = pill_height
            left_width = diameter // 2
            right_width = diameter - left_width
            cap = Image.new(
                "RGBA",
                (diameter * supersample, diameter * supersample),
                (0, 0, 0, 0),
            )
            ImageDraw.Draw(cap).ellipse(
                (0, 0, cap.width - 1, cap.height - 1),
                fill=fill_rgba,
                outline=outline_rgba,
                width=max(1, stroke * supersample) if outline_rgba else 1,
            )
            cap = cap.resize((diameter, diameter), Image.Resampling.LANCZOS)
            draw = ImageDraw.Draw(image)
            draw.rectangle(
                (x1 + left_width, y1, x2 - right_width, y2 - 1),
                fill=fill_rgba,
            )
            if outline_rgba and stroke:
                draw.line(
                    (x1 + left_width, y1, x2 - right_width, y1),
                    fill=outline_rgba,
                    width=stroke,
                )
                draw.line(
                    (x1 + left_width, y2 - 1, x2 - right_width, y2 - 1),
                    fill=outline_rgba,
                    width=stroke,
                )
            composite(cap.crop((0, 0, left_width, diameter)), x1, y1)
            composite(
                cap.crop((left_width, 0, diameter, diameter)),
                x2 - right_width,
                y1,
            )

        track = (
            metric(10),
            metric(9),
            width - metric(10),
            height - metric(9),
        )
        pill(
            track,
            palette["field"],
            outline_color=palette["stroke"],
            outline_width=metric(1),
        )

        fill = (
            metric(12),
            metric(11),
            min(width - metric(12), metric(12) + fill_width),
            height - metric(11),
        )
        if hot:
            glow_width = metric(36)
            glow_height = max(metric(8), height - metric(12))
            glow = Image.new(
                "RGBA",
                (glow_width * supersample, glow_height * supersample),
                (0, 0, 0, 0),
            )
            glow_draw = ImageDraw.Draw(glow)
            glow_draw.ellipse(
                (0, 0, glow.width - 1, glow.height - 1),
                outline=self._hex_rgba(palette["warm"], 150),
                width=max(1, metric(2) * supersample),
            )
            glow = glow.filter(
                ImageFilter.GaussianBlur(radius=max(1.0, metric(2) * supersample))
            )
            composite(
                glow.resize(
                    (glow_width, glow_height),
                    Image.Resampling.LANCZOS,
                ),
                fill[2] - glow_width // 2,
                metric(6),
            )

        pill(
            fill,
            palette["accent"],
        )
        if hot:
            ring_width = metric(36)
            ring_height = max(metric(8), height - metric(12))
            ring = Image.new(
                "RGBA",
                (ring_width * supersample, ring_height * supersample),
                (0, 0, 0, 0),
            )
            ImageDraw.Draw(ring).ellipse(
                (0, 0, ring.width - 1, ring.height - 1),
                outline=(*self._rgb(palette["warm"]), 230),
                width=max(1, metric(1) * supersample),
            )
            composite(
                ring.resize(
                    (ring_width, ring_height),
                    Image.Resampling.LANCZOS,
                ),
                fill[2] - ring_width // 2,
                metric(6),
            )
        return image.convert("RGB")

    def _draw_settings_header(
        self,
        canvas: tk.Canvas,
        width: int,
        height: int,
        theme: str,
        *,
        title: str = "Talk DAT!",
        subtitle: str | None = None,
        show_close: bool = True,
    ) -> None:
        try:
            if getattr(canvas.winfo_toplevel(), "_talkdat_live_resize", False):
                return
        except tk.TclError:
            return
        metric = lambda value: ui_scale.px(value, self.config)
        width = max(metric(320), int(width))
        height = max(metric(72), int(height))
        palette = self._settings_palette(theme)
        plate, sheen = self._settings_header_layers(width, height, palette)
        field = plate.copy()

        accent_width = min(metric(210), max(metric(150), width // 4))
        accent_height = max(metric(42), height - metric(30))
        accent = self._compact_wave_frame(accent_width, accent_height, active=True) or self._compact_reference_fallback(
            accent_width, accent_height
        )
        if accent.mode != "RGBA":
            accent = accent.convert("RGBA")
        accent = ImageEnhance.Color(accent).enhance(1.22)
        accent = ImageEnhance.Contrast(accent).enhance(1.08)
        accent_x = metric(18)
        accent_y = max(metric(8), (height - accent.height) // 2)
        supersample = 4
        pad = metric(10)
        accent_layer = Image.new(
            "RGBA",
            (
                (accent.width + 2 * pad) * supersample,
                (accent.height + 2 * pad) * supersample,
            ),
            (0, 0, 0, 0),
        )
        accent_large = accent.resize(
            (accent.width * supersample, accent.height * supersample),
            Image.Resampling.LANCZOS,
        )
        accent_mask = Image.new("L", accent_large.size, 0)
        accent_draw = ImageDraw.Draw(accent_mask)
        accent_draw.rounded_rectangle(
            (0, 0, accent_large.width - 1, accent_large.height - 1),
            radius=(accent.height // 2) * supersample,
            fill=188,
        )
        accent_layer.paste(
            accent_large,
            (pad * supersample, pad * supersample),
            accent_mask,
        )

        aura = Image.new("RGBA", accent_layer.size, (0, 0, 0, 0))
        aura_draw = ImageDraw.Draw(aura)
        aura_draw.rounded_rectangle(
            (
                (pad - metric(4)) * supersample,
                (pad - metric(4)) * supersample,
                (pad + accent.width + metric(4)) * supersample,
                (pad + accent.height + metric(4)) * supersample,
            ),
            radius=(accent.height // 2 + metric(4)) * supersample,
            outline=self._hex_rgba(palette["accent"], 110),
            width=max(1, metric(2) * supersample),
        )
        aura = aura.filter(
            ImageFilter.GaussianBlur(
                radius=max(1.0, 2.4 * ui_scale.scale(self.config) * supersample)
            )
        )
        accent_layer = Image.alpha_composite(accent_layer, aura).resize(
            (accent.width + 2 * pad, accent.height + 2 * pad),
            Image.Resampling.LANCZOS,
        )
        field.alpha_composite(accent_layer, (accent_x - pad, accent_y - pad))
        field = Image.alpha_composite(field, sheen)
        self.settings_header_photo = ImageTk.PhotoImage(field.convert("RGB"), master=canvas)
        try:
            self.settings_header_photos[int(canvas.winfo_id())] = self.settings_header_photo
        except tk.TclError:
            pass
        canvas.delete("all")
        canvas.configure(bg=palette["bg"], highlightthickness=0, bd=0)
        canvas.create_image(0, 0, image=self.settings_header_photo, anchor="nw")
        canvas.create_text(
            accent_x + accent_width + metric(22),
            metric(30),
            text=title,
            anchor="w",
            fill=palette["text"],
            font=(BRAND_DISPLAY_FAMILY, type_scale.TITLE, "bold"),
        )
        canvas.create_text(
            accent_x + accent_width + metric(22),
            metric(62),
            # "local private config" told a customer nothing they wanted and
            # named a file format at them. The theme is the only part of that
            # line anyone reads, and Settings is already what the window is.
            text=subtitle or f"Settings - {palette['name']}",
            anchor="w",
            fill=palette["muted"],
            font=(BRAND_UI_FAMILY, type_scale.SECONDARY),
        )
        if show_close:
            close_left = width - metric(55)
            canvas.create_oval(
                close_left,
                metric(20),
                close_left + metric(28),
                metric(48),
                outline=palette["warm"],
                width=metric(1),
                fill=palette["button"],
            )
            close_photo = self._ui_icon_photo(
                "close",
                metric(19),
                palette["warm"],
                palette["text"],
            )
            canvas.create_image(
                close_left + metric(14),
                metric(34),
                image=close_photo,
            )

    def _schedule_settings_header_animation(
        self,
        canvas: tk.Canvas,
        theme_getter: Callable[[], str],
        height: int,
        *,
        title: str = "Talk DAT!",
        subtitle_getter: Callable[[], str | None] | None = None,
        show_close: bool = True,
    ) -> None:
        def tick() -> None:
            try:
                if not bool(canvas.winfo_exists()):
                    return
                if getattr(canvas.winfo_toplevel(), "_talkdat_live_resize", False):
                    canvas.after(50, tick)
                    return
                subtitle = subtitle_getter() if subtitle_getter else None
                # X-141 part two (the founder's CPU report, second burner):
                # this header re-rendered its ENTIRE glass panel -- Gaussian
                # blur, three composites, a fresh PhotoImage, full canvas
                # redraw -- forty times a second for as long as the window
                # existed, and X-123's home-on-boot made that all day, every
                # day (~half a core, profiled live). The accent only MOVES
                # when the pill's material moves; the pill already publishes
                # exactly that as last_flow_render_key plus the voice level.
                # Unchanged signature: skip the draw entirely and idle at a
                # slow poll. The moment anything animates, full rate resumes.
                motion_key = (
                    (None, 0.0)
                    if self._motion_is_reduced()
                    else (
                        self.last_flow_render_key,
                        round(float(getattr(self, "display_level", 0.0)), 2),
                    )
                )
                signature = (
                    max(1, canvas.winfo_width()),
                    max(1, canvas.winfo_height()),
                    theme_getter(),
                    title,
                    subtitle,
                    motion_key,
                )
                if signature == getattr(canvas, "_talkdat_header_signature", None):
                    canvas.after(150, tick)
                    return
                canvas._talkdat_header_signature = signature  # type: ignore[attr-defined]
                self._draw_settings_header(
                    canvas,
                    max(1, canvas.winfo_width()),
                    max(ui_scale.px(height, self.config), canvas.winfo_height()),
                    theme_getter(),
                    title=title,
                    subtitle=subtitle,
                    show_close=show_close,
                )
                canvas.after(max(16, min(42, self.idle_frame_ms)), tick)
            except tk.TclError:
                pass

        tick()

    @_transactional_utility_builder
    def open_onboarding(self, step: str | None = None) -> None:
        open_shared = self.callbacks.get('web_settings')
        if step is None and callable(open_shared) and open_shared('setup'):
            return
        if step is None:
            open_onboarding_wizard(self)
        else:
            open_onboarding_wizard(self, step=step)

    @_transactional_utility_builder
    def _open_legacy_onboarding(self) -> None:
        self.force_visible()
        ui = self.config.setdefault("ui", {})
        theme = self._settings_theme_key(str(ui.get("settings_theme") or ui.get("theme") or "Flow Dark"))
        palette = self._settings_palette(theme)
        window = self._utility_window(
            "onboarding",
            "Talk DAT! Setup",
            "980x760",
            bg=palette["bg"],
            resizable=True,
            minimum_size=(860, 680),
        )
        if window is None:
            return
        window.configure(bg=palette["bg"])
        self._style_settings_widgets(window, palette)
        window.columnconfigure(0, weight=1)
        window.rowconfigure(1, weight=1)

        header = tk.Canvas(
            window,
            height=ui_scale.px(136, self.config),
            bg=palette["bg"],
            bd=0,
            highlightthickness=0,
        )
        header.grid(row=0, column=0, sticky="ew", padx=ui_scale.spacing(16, self.config), pady=ui_scale.spacing((16, 8), self.config))
        self._bind_utility_drag_handle(window, header)
        legacy_minimize = self._minimize_control(window, header, palette["bg"])
        legacy_minimize.place(
            relx=1.0,
            x=-ui_scale.px(64, self.config),
            y=ui_scale.px(18, self.config),
            anchor="ne",
            width=ui_scale.px(84, self.config),
            height=ui_scale.px(32, self.config),
        )

        def redraw_header(_event: tk.Event | None = None) -> None:
            width = max(1, header.winfo_width())
            self._draw_settings_header(
                header,
                width,
                max(ui_scale.px(136, self.config), header.winfo_height()),
                theme,
                title="Talk DAT! Setup",
                subtitle="Start local with no key, or choose a cloud provider and paste your own key.",
            )

        def header_click(event: tk.Event) -> str | None:
            if (
                int(getattr(event, "x", 0))
                >= max(0, header.winfo_width() - ui_scale.px(62, self.config))
                and int(getattr(event, "y", 0)) <= ui_scale.px(62, self.config)
            ):
                self._request_utility_close(window)
                return "break"
            return None

        header.bind("<Configure>", redraw_header)
        header.bind("<ButtonPress-1>", header_click, add="+")
        self._schedule_settings_header_animation(
            header,
            lambda: theme,
            136,
            title="Talk DAT! Setup",
            subtitle_getter=lambda: "Start local with no key, or choose a cloud provider and paste your own key.",
        )

        panel = ttk.Frame(window, padding=ui_scale.spacing(20, self.config), style="Flow.TFrame")
        panel.grid(row=1, column=0, sticky="nsew", padx=ui_scale.spacing(16, self.config), pady=ui_scale.spacing((0, 12), self.config))
        panel.columnconfigure(1, weight=1)
        ttk.Label(
            panel,
            text="Choose how Talk DAT! should transcribe. The microphone remains off until you press a trigger.",
            wraplength=ui_scale.px(820, self.config),
            style="Flow.Muted.TLabel",
        ).grid(row=0, column=0, columnspan=2, sticky="ew", pady=ui_scale.spacing((0, 8), self.config))

        def add_row(row: int, label: str, widget: tk.Widget) -> None:
            ttk.Label(panel, text=label, style="Flow.TLabel").grid(row=row, column=0, sticky="w", pady=ui_scale.spacing(4, self.config), padx=ui_scale.spacing((0, 16), self.config))
            widget.grid(row=row, column=1, sticky="ew", pady=ui_scale.spacing(4, self.config))

        def combo(variable: tk.StringVar, values: list[str], width: int = 32) -> ttk.Combobox:
            return ttk.Combobox(panel, textvariable=variable, values=values, width=width, style="Flow.TCombobox")

        def entry(variable: tk.StringVar, width: int = 48, show: str | None = None) -> ttk.Entry:
            return ttk.Entry(panel, textvariable=variable, width=width, show=show or "", style="Flow.TEntry")

        active_provider_id = selected_provider_id(self.config)
        active_model_id = selected_model_id(self.config, active_provider_id)
        active_settings = provider_settings(self.config, active_provider_id)
        provider_holder = {"id": active_provider_id}

        provider_var = tk.StringVar(value=provider_label(active_provider_id))
        model_var = tk.StringVar(value=model_label(active_provider_id, active_model_id))
        variant_var = tk.StringVar(value=selected_variant(self.config, active_provider_id))
        key_var = tk.StringVar(value=str(active_settings.get("api_key", "")))
        base_var = tk.StringVar(value=str(active_settings.get("api_base") or PROVIDER_BY_ID[active_provider_id].api_base))
        language_var = tk.StringVar(value=str(active_settings.get("language") or self.config.get("deepgram", {}).get("language", "en-US")))
        key_label_var = tk.StringVar(value=PROVIDER_BY_ID[active_provider_id].key_label)
        capability_var = tk.StringVar(value=provider_capability_summary(active_provider_id, active_model_id))
        docs_var = tk.StringVar(value=str(PROVIDER_BY_ID[active_provider_id].docs_url or "Custom/local provider"))
        route_var = tk.StringVar(
            value="local" if active_provider_id == "local" else "byok"
        )
        route_status_var = tk.StringVar()

        provider_box = combo(
            provider_var,
            ["Local / On-Device"]
            if route_var.get() == "local"
            else flagship_cloud_provider_labels(),
            32,
        )
        model_box = combo(model_var, model_labels(active_provider_id), 40)
        variant_box = combo(variant_var, list(model_for_id(active_provider_id, active_model_id).variants), 26)
        key_entry = entry(key_var, 64, show="*")
        route_buttons: dict[str, tk.Button] = {}

        def paint_route_buttons() -> None:
            for route, button in route_buttons.items():
                selected = route_var.get() == route
                button.configure(
                    bg=palette["select"] if selected else palette["button"],
                    fg=palette["text"] if selected else palette["muted"],
                    activebackground=palette["select"],
                    activeforeground=palette["text"],
                )
            if route_var.get() == "local":
                route_status_var.set(
                    "Recommended default: private, free after the one-time model download, and no account or API key."
                )
            else:
                route_status_var.set(
                    f"Bring your own provider: choose a supported cloud service. Its key stays in {mac_support.CREDENTIAL_VAULT_NAME}."
                )

        def remember_provider_fields(provider_id: str) -> None:
            settings = provider_settings(self.config, provider_id)
            settings["api_key"] = key_var.get().strip()
            settings["api_base"] = base_var.get().strip()
            settings["language"] = language_var.get().strip() or "en-US"
            settings["model"] = model_id_for_label(provider_id, model_var.get())
            model = model_for_id(provider_id, settings["model"])
            settings["variant"] = variant_var.get().strip() or model.variants[0]

        def refresh_provider_fields(*, keep_model: bool = False) -> None:
            provider_id = provider_id_for_label(provider_var.get())
            provider = PROVIDER_BY_ID[provider_id]
            settings = provider_settings(self.config, provider_id)
            current_model_id = str(settings.get("model") or provider.models[0].id)
            model_box.configure(values=model_labels(provider_id))
            if not keep_model:
                model_var.set(model_label(provider_id, current_model_id))
            chosen_model_id = model_id_for_label(provider_id, model_var.get())
            chosen_model = model_for_id(provider_id, chosen_model_id)
            variant_box.configure(values=list(chosen_model.variants))
            if variant_var.get() not in chosen_model.variants:
                variant_var.set(str(settings.get("variant") or chosen_model.variants[0]))
            if variant_var.get() not in chosen_model.variants:
                variant_var.set(chosen_model.variants[0])
            key_var.set(str(settings.get("api_key", "")))
            base_var.set(str(settings.get("api_base") or provider.api_base))
            language_var.set(str(settings.get("language") or self.config.get("deepgram", {}).get("language", "en-US")))
            key_label_var.set(provider.key_label)
            capability_var.set(provider_capability_summary(provider_id, chosen_model_id))
            docs_var.set(str(provider.docs_url or "Custom/local provider"))
            provider_holder["id"] = provider_id
            key_entry.configure(state="disabled" if provider.key_optional else "normal")

        def choose_route(route: str) -> None:
            route_var.set(route if route in {"local", "byok"} else "local")
            remember_provider_fields(provider_holder["id"])
            if route_var.get() == "local":
                provider_box.configure(values=["Local / On-Device"])
                provider_var.set(provider_label("local"))
            else:
                cloud_labels = flagship_cloud_provider_labels()
                provider_box.configure(values=cloud_labels)
                if provider_id_for_label(provider_var.get()) not in FLAGSHIP_CLOUD_PROVIDER_IDS:
                    provider_var.set(provider_label("deepgram"))
            refresh_provider_fields()
            paint_route_buttons()

        def on_provider_change(_event: tk.Event | None = None) -> None:
            remember_provider_fields(provider_holder["id"])
            refresh_provider_fields()

        def on_model_change(_event: tk.Event | None = None) -> None:
            provider_id = provider_id_for_label(provider_var.get())
            chosen_model_id = model_id_for_label(provider_id, model_var.get())
            chosen_model = model_for_id(provider_id, chosen_model_id)
            variant_box.configure(values=list(chosen_model.variants))
            if variant_var.get() not in chosen_model.variants:
                variant_var.set(chosen_model.variants[0])
            capability_var.set(provider_capability_summary(provider_id, chosen_model_id))

        def open_setup_provider_link(kind: str) -> None:
            provider_id = provider_id_for_label(provider_var.get())
            provider = PROVIDER_BY_ID.get(provider_id, PROVIDER_BY_ID["local"])
            url = {
                "login": provider.login_url,
                "keys": provider.api_keys_url,
                "docs": provider.docs_url,
            }.get(kind, "")
            if url:
                webbrowser.open(url)
            else:
                self.set_state("error", f"No {kind} link configured for {provider.label}.", "")

        provider_box.bind("<<ComboboxSelected>>", on_provider_change)
        model_box.bind("<<ComboboxSelected>>", on_model_change)

        route_frame = tk.Frame(panel, bg=palette["panel"], bd=0, highlightthickness=0)
        for route, label in (
            ("local", "Private on-device"),
            ("byok", "Bring your own"),
        ):
            button = FlatButton(
                route_frame,
                text=label,
                command=lambda selected=route: choose_route(selected),
                relief="flat",
                bd=0,
                highlightthickness=1,
                highlightbackground=palette["stroke"],
                font=(BRAND_UI_FAMILY, type_scale.CAPTION, "bold"),
                cursor="hand2",
                padx=ui_scale.spacing(16, self.config),
                pady=ui_scale.spacing(8, self.config),
            )
            button.pack(
                side="left",
                fill="x",
                expand=True,
                padx=ui_scale.spacing((0, 8) if route != "byok" else 0, self.config),
            )
            route_buttons[route] = button
        add_row(1, "Transcription route", route_frame)
        # The pill's three-position switch calls this to mirror itself here
        # the instant it changes the config -- one source of truth, every
        # menu reflecting it, as ordered.
        def _sync_route_from_config() -> None:
            provider_now = selected_provider_id(self.config)
            # X-516: anything the registry does not know resolves to local,
            # so an old config naming the managed service must show Local
            # rather than falling through to "Bring your own" and implying a
            # key the person never had.
            choose_route("local" if provider_now == "local" else "byok")

        self._settings_route_sync = _sync_route_from_config
        ttk.Label(panel, textvariable=route_status_var, wraplength=ui_scale.px(700, self.config), style="Flow.Muted.TLabel").grid(
            row=2, column=1, sticky="ew", pady=ui_scale.spacing((0, 8), self.config)
        )

        add_row(3, "Provider", provider_box)
        add_row(4, "Model", model_box)
        add_row(5, "Mode / trim", variant_box)
        add_row(6, "Language", entry(language_var, 18))
        add_row(7, "API base", entry(base_var, 64))
        add_row(8, "API key", key_entry)
        ttk.Label(panel, textvariable=key_label_var, style="Flow.Muted.TLabel").grid(row=9, column=1, sticky="w")
        ttk.Label(panel, textvariable=capability_var, style="Flow.Muted.TLabel").grid(row=10, column=1, sticky="w", pady=ui_scale.spacing((4, 0), self.config))
        setup_links = ttk.Frame(panel, style="Flow.TFrame")
        ttk.Button(setup_links, text="Login", command=lambda: open_setup_provider_link("login"), style="Flow.TButton").pack(side="left", padx=ui_scale.spacing((0, 8), self.config))
        ttk.Button(setup_links, text="API keys", command=lambda: open_setup_provider_link("keys"), style="Flow.TButton").pack(side="left", padx=ui_scale.spacing((0, 8), self.config))
        ttk.Button(setup_links, text="Docs", command=lambda: open_setup_provider_link("docs"), style="Flow.TButton").pack(side="left")
        add_row(11, "Provider links", setup_links)
        ttk.Label(panel, textvariable=docs_var, wraplength=ui_scale.px(580, self.config), style="Flow.Muted.TLabel").grid(
            row=12, column=1, sticky="ew", pady=ui_scale.spacing((4, 4), self.config)
        )
        ttk.Label(
            panel,
            text="You can switch later in Settings > Voice. Talk DAT! runs on this machine, or through a provider you have a key for. Nothing is sent to us either way.",
            wraplength=ui_scale.px(820, self.config),
            style="Flow.Muted.TLabel",
        ).grid(row=13, column=0, columnspan=2, sticky="w", pady=ui_scale.spacing((4, 4), self.config))
        ttk.Label(
            panel,
            text=(
                f"Recommended first test: open {TEXT_APP_NAME}, click the pill or hold "
                f"{self._chord('push_to_talk', ('ctrl', 'cmd'))}, speak one sentence, then stop."
            ),
            wraplength=ui_scale.px(820, self.config),
            style="Flow.Muted.TLabel",
        ).grid(row=14, column=0, columnspan=2, sticky="w", pady=ui_scale.spacing((0, 4), self.config))

        button_row = tk.Frame(window, bg=palette["bg"])
        button_row.grid(row=2, column=0, sticky="ew", padx=ui_scale.spacing(16, self.config), pady=ui_scale.spacing((0, 16), self.config))
        status_var = tk.StringVar(value="")

        def save_setup(*, close: bool = True) -> None:
            remember_provider_fields(provider_holder["id"])
            provider_id = provider_id_for_label(provider_var.get())
            settings = provider_settings(self.config, provider_id)
            provider = PROVIDER_BY_ID[provider_id]
            if not provider.key_optional and not str(settings.get("api_key", "")).strip():
                status_var.set(f"Add your {provider.key_label}, or choose Private on-device.")
                key_entry.focus_set()
                return
            self.config.setdefault("stt", {})["provider"] = provider_id
            self.config.setdefault("deepgram", {})["language"] = language_var.get().strip() or "en-US"
            settings["language"] = language_var.get().strip() or "en-US"
            if provider_id == "deepgram":
                deepgram = self.config.setdefault("deepgram", {})
                deepgram["api_key"] = settings.get("api_key", "")
                deepgram["model"] = settings.get("model", "nova-3")
                deepgram["language"] = settings.get("language", "en-US")
            sync_legacy_deepgram(self.config)
            self.config.setdefault("onboarding", {})["completed"] = True
            self.apply_runtime_config()
            callback = self.callbacks.get("save_settings")
            if callback:
                callback()
            status_var.set("Saved.")
            self.set_state("captured", "Setup saved.", f"Saved to {config_path()}")
            if close:
                self._request_utility_close(window)

        def use_local_default() -> None:
            choose_route("local")
            self.config.setdefault("onboarding", {})["completed"] = True
            self.config.setdefault("stt", {})["provider"] = "local"
            self.apply_runtime_config()
            callback = self.callbacks.get("save_settings")
            if callback:
                callback()
            self.set_state("idle", "Private on-device transcription selected.", "The model downloads once, then runs locally.")
            self._request_utility_close(window)

        def full_settings() -> None:
            self._request_utility_close(window, on_complete=self.open_settings)

        ttk.Button(button_row, text="Save setup", command=save_setup, style="Flow.TButton").pack(side="left", padx=ui_scale.spacing((0, 8), self.config))
        ttk.Button(button_row, text="Full settings", command=full_settings, style="Flow.TButton").pack(side="left", padx=ui_scale.spacing((0, 8), self.config))
        ttk.Button(button_row, text="Use local default", command=use_local_default, style="Flow.TButton").pack(side="left", padx=ui_scale.spacing((0, 8), self.config))
        ttk.Label(button_row, textvariable=status_var, style="Flow.Muted.TLabel").pack(side="left", padx=ui_scale.spacing((8, 0), self.config))
        ttk.Button(button_row, text="Close", command=lambda: self._request_utility_close(window), style="Flow.TButton").pack(side="right")

        try:
            (provider_box if active_provider_id == "local" else key_entry).focus_set()
        except Exception:
            pass
        paint_route_buttons()

    @_transactional_utility_builder
    def open_account(self) -> None:
        # X-612: the web Account page signs in now; this window is the
        # fallback when the renderer is unavailable.
        callbacks = getattr(self, "callbacks", {})
        web_settings = callbacks.get("web_settings") if isinstance(callbacks, dict) else None
        if callable(web_settings) and web_settings("account"):
            return
        self.force_visible()
        ui = self.config.setdefault("ui", {})
        theme = self._settings_theme_key(str(ui.get("settings_theme") or ui.get("theme") or "Flow Dark"))
        palette = self._settings_palette(theme)
        window = self._utility_window(
            "account",
            "Talk DAT! Account & License",
            "700x500",
            bg=palette["bg"],
            resizable=True,
            minimum_size=(620, 440),
        )
        if window is None:
            return
        window.configure(bg=palette["bg"])
        self._style_settings_widgets(window, palette)
        window.columnconfigure(0, weight=1)
        window.rowconfigure(1, weight=1)
        # The body can scroll; the account actions cannot. Reserve their
        # complete hit area at the declared minimum instead of allowing the
        # body's natural request to push the last pixels below the window.
        window.rowconfigure(2, minsize=ui_scale.px(60, self.config))

        header = tk.Canvas(window, height=ui_scale.px(108, self.config), bg=palette["bg"], bd=0, highlightthickness=0)
        header.grid(row=0, column=0, sticky="ew", padx=ui_scale.spacing(16, self.config), pady=ui_scale.spacing((16, 8), self.config))

        # Account uses a grid-managed custom masthead, so the shared packed
        # title bar intentionally declines to attach. Give this exceptional
        # masthead the same real, keyboard-focusable close control as every
        # other utility window rather than leaving Escape as its only top-edge
        # exit.
        header_close = self._close_control(window, header, palette["panel"])
        header_close.place(
            relx=1.0,
            x=-ui_scale.px(12, self.config),
            y=ui_scale.px(12, self.config),
            anchor="ne",
            width=ui_scale.px(44, self.config),
            height=ui_scale.px(32, self.config),
        )
        header_minimize = self._minimize_control(window, header, palette["panel"])
        header_minimize.place(
            relx=1.0,
            x=-ui_scale.px(64, self.config),
            y=ui_scale.px(12, self.config),
            anchor="ne",
            width=ui_scale.px(84, self.config),
            height=ui_scale.px(32, self.config),
        )

        def draw_header(_event: tk.Event | None = None) -> None:
            width = max(1, header.winfo_width())
            height = max(96, header.winfo_height())
            header.delete("all")
            header.create_rectangle(0, 0, width, height, fill=palette["panel"], outline=palette["stroke"])
            header.create_line(24, height - 2, width - 24, height - 2, fill=palette["accent"], width=1)
            header.create_text(26, int(height * 0.30), text="Account & license", anchor="w",
                               fill=palette["text"], font=(BRAND_DISPLAY_FAMILY, type_scale.TITLE, "bold"))
            header.create_text(
                26,
                int(height * 0.70),
                text=f"Sign-in for {platform_copy.THIS_COMPUTER}. Talk DAT! is free; dictation never needs an account.",
                anchor="w",
                width=max(ui_scale.px(240, self.config), width - ui_scale.px(196, self.config)),
                fill=palette["muted"],
                font=(BRAND_UI_FAMILY, type_scale.CAPTION),
            )

        header.bind("<Configure>", draw_header)
        draw_header()

        # X-185: the page scrolls.
        #
        # Account is a shell page, so the shell hands it whatever size the window
        # currently is, which is not the 700x500 this page asks for. Anything
        # below the fold was simply unreachable: no scrollbar, no wheel, and
        # overrideredirect means no resize border either. The activation code row
        # and the sign-out control are at the bottom.
        #
        # `scrollable_region` is the helper that already exists for exactly this
        # and is already tested (tests/test_scrollable_region.py). Everything
        # below is unchanged: every body.grid child, the grid_remove/grid dance on
        # the code row, and the refresh timer all keep working, because only
        # body's PARENT changes.
        holder, scroller = scrollable_region(window, palette["bg"], wheel_host=window)
        holder.grid(row=1, column=0, sticky="nsew", padx=ui_scale.spacing(16, self.config))
        account_canvas = next(child for child in holder.winfo_children() if isinstance(child, tk.Canvas))
        account_scrollbar = next(child for child in holder.winfo_children() if isinstance(child, ttk.Scrollbar))
        account_canvas.configure(takefocus=1)
        account_scrollbar.configure(style="Flow.Vertical.TScrollbar")
        account_canvas.bind("<Prior>", lambda _e: (account_canvas.yview_scroll(-1, "pages"), "break")[-1])
        account_canvas.bind("<Next>", lambda _e: (account_canvas.yview_scroll(1, "pages"), "break")[-1])
        account_canvas.bind("<Home>", lambda _e: (account_canvas.yview_moveto(0.0), "break")[-1])
        account_canvas.bind("<End>", lambda _e: (account_canvas.yview_moveto(1.0), "break")[-1])
        body = ttk.Frame(scroller, padding=ui_scale.spacing((24, 24), self.config), style="Flow.TFrame")
        body.pack(fill="both", expand=True)
        body.columnconfigure(1, weight=1)

        # This window used to be a read-only status card with a button labelled
        # "Connect / activate" that explained nothing and reported nothing back.
        # Signing in is a device-code flow -- the browser does the actual sign-in
        # because that is where Google lives -- and every part of that was
        # invisible: no code, no progress, no result. It read as a page that did
        # not work, which is exactly what it was.
        headline_var = tk.StringVar()
        detail_var = tk.StringVar()
        code_var = tk.StringVar()
        rows_vars = {"Status": tk.StringVar(), "Account email": tk.StringVar()}

        ttk.Label(body, textvariable=headline_var, style="Flow.TLabel",
                  font=(BRAND_DISPLAY_FAMILY, type_scale.HEADING, "bold")).grid(row=0, column=0, columnspan=2, sticky="w", pady=ui_scale.spacing((0, 4), self.config))
        ttk.Label(body, textvariable=detail_var, style="Flow.Muted.TLabel",
                  wraplength=ui_scale.px(560, self.config)).grid(row=1, column=0, columnspan=2, sticky="ew", pady=ui_scale.spacing((0, 16), self.config))

        # The pairing code, shown large. It is also copied to the clipboard, but
        # someone whose browser opened on another screen needs to be able to read
        # it here rather than guess.
        code_label = ttk.Label(body, textvariable=code_var, style="Flow.TLabel",
                               font=(mac_support.FONT_MONO, type_scale.DISPLAY))
        code_label.grid(row=2, column=0, columnspan=2, sticky="w", pady=ui_scale.spacing((0, 16), self.config))

        for index, label in enumerate(("Status", "Account email")):
            ttk.Label(body, text=label, style="Flow.Muted.TLabel").grid(
                row=3 + index, column=0, sticky="w", padx=ui_scale.spacing((0, 24), self.config), pady=ui_scale.spacing(8, self.config))
            ttk.Label(body, textvariable=rows_vars[label], style="Flow.TLabel",
                      wraplength=ui_scale.px(430, self.config)).grid(row=3 + index, column=1, sticky="w", pady=ui_scale.spacing(8, self.config))

        # X-432: sign in HERE. His order was the full login and account setup
        # from the menu on Mac and Windows, with the website as an option and
        # not the only door. The account is created on the first code, so
        # setting up and signing in are the same two boxes.
        signin_row = ttk.Frame(body, style="Flow.TFrame")
        signin_row.grid(row=6, column=0, columnspan=2, sticky="ew", pady=ui_scale.spacing((16, 0), self.config))
        signin_row.columnconfigure(1, weight=1)
        ttk.Label(signin_row, text="Sign in or create your account", style="Flow.TLabel",
                  font=(BRAND_UI_FAMILY, type_scale.SECONDARY, "bold")).grid(row=0, column=0, columnspan=3, sticky="w")
        ttk.Label(
            signin_row,
            text="Type your email and we send a six-digit code. The code is the sign-in: no password to make, nothing to verify later.",
            style="Flow.Muted.TLabel",
            wraplength=ui_scale.px(560, self.config),
        ).grid(row=1, column=0, columnspan=3, sticky="ew", pady=ui_scale.spacing((4, 8), self.config))
        email_var = tk.StringVar()
        email_entry = ttk.Entry(signin_row, textvariable=email_var, width=34, font=(BRAND_UI_FAMILY, type_scale.BODY))
        email_entry.grid(row=2, column=0, sticky="w")
        signin_note_var = tk.StringVar(value="")

        def email_now() -> None:
            value = email_var.get().strip()
            if "@" not in value:
                signin_note_var.set("Type the email address you want the code sent to.")
                email_entry.focus_set()
                return
            signin_note_var.set("")
            callback = self.callbacks.get("license_email_start")
            if callback:
                callback(value)

        email_entry.bind("<Return>", lambda _event: email_now())
        email_button = ttk.Button(signin_row, text="Email me a code", style="Flow.TButton", command=email_now)
        email_button.grid(row=2, column=1, sticky="w", padx=ui_scale.spacing((8, 0), self.config))

        # The code box appears once a code is on its way, and stays until the
        # sign-in lands, so a mistyped digit is a retype and not a restart.
        code_entry_row = ttk.Frame(signin_row, style="Flow.TFrame")
        code_entry_row.grid(row=3, column=0, columnspan=3, sticky="ew", pady=ui_scale.spacing((8, 0), self.config))
        code_entry_row.grid_remove()
        signin_code_var = tk.StringVar()
        ttk.Label(code_entry_row, text="Six-digit code", style="Flow.Muted.TLabel").grid(row=0, column=0, sticky="w")
        signin_code_entry = ttk.Entry(code_entry_row, textvariable=signin_code_var, width=12, font=(mac_support.FONT_MONO, type_scale.SUBHEADING))
        signin_code_entry.grid(row=1, column=0, sticky="w", pady=ui_scale.spacing((4, 0), self.config))

        def verify_now() -> None:
            digits = "".join(ch for ch in signin_code_var.get() if ch.isdigit())
            if len(digits) != 6:
                signin_note_var.set("Enter the six digits from the email.")
                signin_code_entry.focus_set()
                return
            signin_note_var.set("")
            callback = self.callbacks.get("license_email_verify")
            if callback:
                callback(digits)

        signin_code_entry.bind("<Return>", lambda _event: verify_now())
        ttk.Button(code_entry_row, text="Sign in with this code", style="Flow.TButton", command=verify_now).grid(
            row=1, column=1, sticky="w", padx=ui_scale.spacing((8, 0), self.config))
        ttk.Button(code_entry_row, text="Send a new code", style="Flow.TButton", command=email_now).grid(
            row=1, column=2, sticky="w", padx=ui_scale.spacing((8, 0), self.config))

        ttk.Label(signin_row, textvariable=signin_note_var, style="Flow.Muted.TLabel",
                  wraplength=ui_scale.px(560, self.config)).grid(row=4, column=0, columnspan=3, sticky="w", pady=ui_scale.spacing((4, 0), self.config))
        # The website, as an option. It is the same account and the same
        # approval; only where you type the code changes.
        ttk.Button(signin_row, text="Prefer your browser? Sign in on the website instead", style="Flow.TButton",
                   command=self._callback("license_activate")).grid(
            row=5, column=0, columnspan=3, sticky="w", pady=ui_scale.spacing((8, 0), self.config))

        ttk.Label(
            body,
            # 2026-09-22: Talk DAT! is free -- no prices, trials, plans or
            # word caps. The account exists for sign-in and preference sync,
            # and this line says so on the one screen where someone might
            # otherwise look for a bill.
            text="Talk DAT! is free. Every feature, the on-device models and your own API keys "
                 "work without an account. Signing in keeps your preferences in step across "
                 "your computers.",
            style="Flow.Muted.TLabel",
            wraplength=ui_scale.px(570, self.config),
        ).grid(row=7, column=0, columnspan=2, sticky="ew", pady=ui_scale.spacing((16, 0), self.config))

        actions = tk.Frame(window, bg=palette["bg"])
        actions.grid(row=2, column=0, sticky="ew", padx=ui_scale.spacing(16, self.config), pady=ui_scale.spacing((8, 12), self.config))
        sign_in = ttk.Button(actions, text="Sign in on the website", style="Flow.TButton",
                             command=self._callback("license_activate"))
        sign_in.pack(side="left")
        # X-113 #16: while the app waits on the browser there was no way out
        # short of quitting -- the wait needs a door.
        cancel_wait = ttk.Button(actions, text="Cancel sign-in", style="Flow.TButton",
                                 command=self._callback("license_activation_cancel"))
        sign_out = ttk.Button(actions, text="Sign out", style="Flow.TButton",
                              command=self._callback("license_sign_out"))
        ttk.Button(
            actions,
            text="Website",
            # X-113 #12: ?handoff=1 ends in a talkdat:// bounce, and only
            # Windows registers that scheme today. On the Mac the same button
            # opens the plain account page until the port grows
            # CFBundleURLTypes (MAC_ORDERS X-113).
            command=lambda: webbrowser.open(
                str(self.config.get("licensing", {}).get("product_url") or "https://www.talkdat.app")
                + ("/?handoff=1#account" if sys.platform == "win32" else "/#account")
            ),
            style="Flow.TButton",
        ).pack(side="left", padx=ui_scale.spacing((8, 0), self.config))
        ttk.Button(actions, text="Close", command=lambda: self._request_utility_close(window), style="Flow.TButton").pack(side="right")

        def refresh() -> None:
            # X-88: guard on a widget of THIS PAGE, not on the window.
            # Since the shell landed (X-73) the window outlives every page
            # inside it, so `window.winfo_exists()` stayed True after the user
            # navigated away and this timer went on touching destroyed widgets
            # every 700ms for the rest of the session -- a TclError into a Tk
            # callback each time, forever, and one more thing burning CPU.
            if not sign_in.winfo_exists():
                return
            try:
                state = self.callbacks.get("license_status", dict)() or {}
            except Exception:
                state = {}
            try:
                activation = self.callbacks.get("license_activation_status", dict)() or {}
            except Exception:
                activation = {}

            email = str(state.get("email") or "")
            signed_in = bool(email) or bool(state.get("active")) or bool(state.get("permanent_core"))
            phase = str(activation.get("state") or "idle")

            rows_vars["Status"].set("Signed in" if signed_in else "Not signed in")
            rows_vars["Account email"].set(email or "Not signed in")

            if phase in {"starting", "waiting"}:
                headline_var.set("Finish signing in, in your browser")
                code = str(activation.get("user_code") or "")
                code_var.set(code)
                # X-113 #16: an open-ended wait reads as a hang. The refresh
                # timer already ticks, so let it count the code down.
                expires_at = float(activation.get("expires_at") or 0)
                remaining = max(0, int(expires_at - time.time())) if expires_at else 0
                clock = f" The code stays good for {remaining // 60}:{remaining % 60:02d}." if remaining else ""
                detail_var.set(
                    ("Your browser is open on the sign-in page. The code below is already "
                     "filled in and copied to your clipboard. This window updates itself when "
                     f"you are done.{clock}")
                    if code else str(activation.get("detail") or "Preparing sign-in."))
                sign_in.state(["disabled"])
                if not cancel_wait.winfo_ismapped():
                    cancel_wait.pack(side="left", padx=ui_scale.spacing((8, 0), self.config))
            elif phase in {"code_sent", "verifying", "code_error"}:
                # X-432: the in-app flow. The code box is open; the headline
                # says what to do; a wrong code keeps the box and shows the
                # service's own sentence.
                headline_var.set("Checking your code" if phase == "verifying" else "Type the code from your email")
                code_var.set("")
                detail_var.set(str(activation.get("detail") or ""))
                sign_in.state(["!disabled"])
                if not code_entry_row.winfo_ismapped():
                    code_entry_row.grid()
                    signin_code_entry.focus_set()
                if phase == "code_error":
                    signin_note_var.set(str(activation.get("detail") or ""))
            elif phase == "error":
                headline_var.set("Sign-in did not finish")
                code_var.set("")
                detail_var.set(str(activation.get("detail") or "Try again."))
                sign_in.state(["!disabled"])
            elif signed_in:
                headline_var.set(f"Signed in as {email}" if email else "Signed in")
                code_var.set("")
                detail_var.set(str(state.get("detail") or "This device is activated."))
                sign_in.state(["!disabled"])
            else:
                headline_var.set("Not signed in")
                code_var.set("")
                # X-432: this used to promise a browser and Google, neither of
                # which is how sign-in works any more.
                detail_var.set(
                    "Sign in below with a code we email you, or on the website if you "
                    "prefer. Dictation, the on-device models and your own API key "
                    "work the same without an account."
                )
                sign_in.state(["!disabled"])

            sign_in.configure(text="Switch account on the website" if signed_in else "Sign in on the website")
            if phase not in {"code_sent", "verifying", "code_error"} and code_entry_row.winfo_ismapped():
                code_entry_row.grid_remove()
            if phase not in {"starting", "waiting"} and cancel_wait.winfo_ismapped():
                cancel_wait.pack_forget()
            if signed_in:
                sign_out.pack(side="left", padx=ui_scale.spacing((8, 0), self.config))
                signin_row.grid_remove()
            else:
                sign_out.pack_forget()
                signin_row.grid()
            window.after(700, refresh)

        refresh()

    def _show_settings_opening_cover(self, palette: dict[str, str]) -> tk.Toplevel | None:
        """Paint a complete lightweight Settings surface before its large tree.

        The full Settings builder currently creates hundreds of native controls.
        A fresh click must still produce a coherent window immediately, rather
        than an unpainted rectangle followed by controls popping into place.
        This cover is the outgoing half of the ordinary shell transition; the
        completed Settings destination replaces it only after layout settles.
        """

        shell = getattr(self, "_shell_window", None)
        try:
            if (
                shell is not None
                and shell.winfo_exists()
                and not bool(getattr(shell, "_talkdat_close_requested", False))
            ):
                return None
        except Exception:
            pass
        current = self.utility_windows.get("settings")
        try:
            if (
                current is not None
                and current.winfo_exists()
                and not bool(getattr(current, "_talkdat_close_requested", False))
            ):
                return None
        except Exception:
            pass

        cover = self._new_toplevel(self.root, role=UTILITY_CHROME)
        # Own the cover from the first instruction after Toplevel creation. A
        # decoration or glass failure must be able to abort this surface through
        # the same transaction as the destination; otherwise it survives as an
        # untracked, unclosable window. Publishing it as the shell immediately
        # also makes every subsequent destination treat it as the visual source.
        cover._talkdat_settings_loading_cover = True  # type: ignore[attr-defined]
        cover._talkdat_build_committed = True  # type: ignore[attr-defined]
        self._shell_window = cover
        transactions = getattr(self, "_utility_build_transactions", None)
        if isinstance(transactions, list) and transactions:
            transactions[-1].append(cover)
        self._install_toplevel_timer_cleanup(cover)
        cover.title("Talk DAT! Settings")
        cover.overrideredirect(True)
        geometry = ui_scale.scale_geometry("1180x940", self.config)
        saved = self.config.get("ui", {}).get("window_sizes", {}).get("settings", "")
        restored = ui_scale.restore_window_size(saved, self.config)
        if restored is not None:
            saved_w, saved_h = restored
            if (
                saved_w >= ui_scale.px(980, self.config)
                and saved_h >= ui_scale.px(680, self.config)
            ):
                geometry = f"{saved_w}x{saved_h}"
        cover_geometry = self._utility_geometry(geometry)
        cover.geometry(cover_geometry)
        cover_width, cover_height = self._parse_geometry_size(cover_geometry)
        cover.minsize(
            min(cover_width, ui_scale.px(980, self.config)),
            min(cover_height, ui_scale.px(680, self.config)),
        )
        cover.resizable(True, True)
        cover.configure(bg=palette["bg"])
        cover.attributes("-topmost", False)
        with contextlib.suppress(Exception):
            cover.attributes("-alpha", 0.0)
        self._apply_glass_effect(cover, palette["bg"])

        stage = tk.Frame(
            cover,
            bg=palette["bg"],
            bd=0,
            highlightthickness=0,
        )
        stage.place(relx=0.5, rely=0.5, anchor="center")
        eyebrow = tk.Label(
            stage,
            text="TALK DAT!",
            bg=palette["bg"],
            fg=palette["accent"],
            font=(BRAND_UI_FAMILY, type_scale.CAPTION, "bold"),
            anchor="center",
        )
        eyebrow.pack(fill="x")
        tk.Label(
            stage,
            text="Settings",
            bg=palette["bg"],
            fg=palette["text"],
            font=(BRAND_DISPLAY_FAMILY, type_scale.DISPLAY, "bold"),
            anchor="center",
        ).pack(fill="x", pady=ui_scale.spacing((12, 8), self.config))
        status = tk.StringVar(value="Preparing your controls")
        tk.Label(
            stage,
            textvariable=status,
            bg=palette["bg"],
            fg=palette["muted"],
            font=(BRAND_UI_FAMILY, type_scale.BODY),
            anchor="center",
        ).pack(fill="x")
        rule = tk.Frame(stage, bg=palette["accent"], width=84, height=2)
        rule.pack(pady=ui_scale.spacing((24, 0), self.config))
        cover._talkdat_settings_loading_status = status  # type: ignore[attr-defined]
        self._close_control(cover, cover, palette["bg"]).place(
            relx=1.0,
            x=-ui_scale.px(18, self.config),
            y=ui_scale.px(16, self.config),
            anchor="ne",
            width=ui_scale.px(44, self.config),
            height=ui_scale.px(32, self.config),
        )
        self._bind_utility_drag_handle(cover, stage, eyebrow)
        cover.bind("<Escape>", lambda _event: self._request_utility_close(cover), add="+")
        cover.protocol("WM_DELETE_WINDOW", lambda: self._request_utility_close(cover))

        cover.update_idletasks()
        apply_window_chrome(cover, UTILITY_CHROME)
        with contextlib.suppress(Exception):
            cover.attributes("-alpha", CLAY_OPACITY)
        cover.deiconify()
        cover.lift()
        cover.update_idletasks()
        if os.name == "nt":
            # Force the already-laid-out surface through DWM without running a
            # nested Tk event loop inside the Settings builder.
            with contextlib.suppress(Exception):
                ctypes.windll.user32.UpdateWindow(int(cover.winfo_id()))
                ctypes.windll.dwmapi.DwmFlush()
        # The transaction owns a PARTIAL cover so any construction failure can
        # remove it. Once complete, the cover becomes the rollback surface for
        # the independently built Settings destination. Keeping it in the same
        # transaction would make a later destination failure abort both windows
        # and leave the user staring at nothing instead of this coherent page.
        if isinstance(transactions, list) and transactions:
            with contextlib.suppress(ValueError):
                transactions[-1].remove(cover)
        return cover

    def open_home(self) -> None:
        """Open Home. A launch calls THIS, never open_settings().

        X-172, his report 2026-09-21: boot called open_settings() with no
        destination, and the shell's no-destination branch falls back to
        `self._last_page` -- so the app opened on whatever settings page the
        previous session happened to close on. Home is an explicit
        destination, so there is no last-page branch to fall into. The legacy
        Tk interface has no Home, so it keeps its own behaviour.
        """
        callbacks = getattr(self, "callbacks", {})
        web_settings = callbacks.get("web_settings") if isinstance(callbacks, dict) else None
        if callable(web_settings) and web_settings("home"):
            return
        self.open_settings()

    @_transactional_utility_builder
    def open_settings(self) -> None:
        self.force_visible()
        callbacks = getattr(self, "callbacks", {})
        web_settings = callbacks.get("web_settings") if isinstance(callbacks, dict) else None
        if callable(web_settings) and web_settings(getattr(self, "_settings_initial_page", None)):
            self._settings_initial_page = None
            return
        # X-74: a deep link arriving while Settings is already open must
        # navigate the LIVE window -- _utility_window's focus short-circuit
        # otherwise swallows it before the page selector ever runs.
        pending_page = getattr(self, "_settings_initial_page", None)
        existing = self.utility_windows.get("settings")
        if (
            pending_page is None
            and existing is not None
            and existing.winfo_exists()
            and not bool(getattr(existing, "_talkdat_close_requested", False))
        ):
            # Reopening an existing Settings window is also the restore path
            # after Minimize. Do it before creating the temporary opening cover,
            # so a same-instance restore never flashes a second window.
            self._focus_utility_window("settings")
            return
        if (
            isinstance(pending_page, tuple)
            and pending_page
            and existing is not None
            and existing.winfo_exists()
            and not bool(getattr(existing, "_talkdat_close_requested", False))
        ):
            selector = getattr(existing, "_select_settings_page", None)
            if callable(selector):
                self._settings_initial_page = None
                top_title = str(pending_page[0])
                child_title = str(pending_page[1]) if len(pending_page) > 1 else ""
                with contextlib.suppress(tk.TclError):
                    selector(top_title, None, child_title)
                    self._focus_utility_window("settings")
                    return
        ui = self.config.setdefault("ui", {})
        theme = self._settings_theme_key(str(ui.get("settings_theme") or ui.get("theme") or "Flow Dark"))
        palette = self._settings_palette(theme)
        self._show_settings_opening_cover(palette)
        window = self._utility_window(
            "settings",
            "Talk DAT! Settings",
            # 800 put the tail of the longest page below the window: "Update
            # channel", the plugin and local-API switches and "Backup
            # settings..." all started past y=800 and needed the corner grip
            # to reach. The update channel being the hard one to find is the
            # worst version of that, since updating is the thing a user most
            # needs to get right. _utility_geometry clamps to the work area,
            # so asking for more is safe on a small screen.
            "1180x940",
            bg=palette["bg"],
            resizable=True,
            minimum_size=(980, 680),
        )
        if window is None:
            return
        window.configure(bg=palette["bg"])
        self._style_settings_widgets(window, palette)
        window.columnconfigure(0, weight=1)
        window.rowconfigure(1, weight=1)
        theme_text_widgets: list[tk.Text] = []
        theme_redraw_callbacks: list[Callable[[], None]] = []
        settings_dirty = {"value": False, "armed": False}
        active_tooltip: dict[str, Any] = {"window": None, "owner": None}
        window._talkdat_active_tooltip = active_tooltip  # type: ignore[attr-defined]

        setting_help = {
            "Instant correction": (
                "Talk DAT! shows your words immediately, then replaces them with the polished "
                "version. Automatic swaps the whole block at once in the apps where that was "
                "measured (Notepad and Chromium browsers such as Edge, Chrome and Brave) and "
                "retypes the difference everywhere else. Always is faster in long dictation but "
                "can leave text twice over in an app that ignores undo."
            ),
            "Active brand": "The speech-to-text provider Talk DAT! will use the next time you activate the pill.",
            "Active model": "The exact speech model currently selected for dictation.",
            "Language": "Primary dictation language. Keep en-US for US English; use provider-specific language codes for other languages.",
            "Auto Cleanup": "How much Talk DAT! cleans speech into written text. High is best for normal dictation.",
            "Formatting level": "Chill keeps your voice and register. Executive rewrites everything into boardroom-ready prose - facts and names never change. Flip it any time from the pill menu.",
            "Keep a local formatting log (what you said vs what was typed)": (
                "Records each dictation's raw words and the delivered text to a private file on this "
                "computer so you can see exactly what formatting did. Never uploaded - sharing it with "
                "a bug report is a separate checkbox you tick at send time."
            ),
            "Speculative paste": "Your words land instantly from the fast pass; a moment later the AI's cleaner version may quietly replace them in place.",
            "Update channel": "Stable reads the latest normal GitHub Release. Beta can see prerelease builds too.",
            "Brand": "The company or local engine that will transcribe your audio.",
            "Model": "The model under the selected provider. Wired models work today; adapter-pending models are labeled.",
            "Mode / trim": "Provider-specific output mode such as streaming, JSON, diarization, or low-latency.",
            "Secret / credential": f"Your private provider key. It is protected by {mac_support.CREDENTIAL_VAULT_NAME}; config.json stores no plaintext copy after migration.",
            "API base": "Advanced endpoint override. Leave this alone unless you use a compatible proxy or self-hosted API.",
            "Sample rate": "Deepgram raw microphone stream rate. 16000 Hz mono linear16 is the best default for this app's low-latency speech path.",
            "Channels": "Microphone channels sent to Deepgram. Mono is recommended for dictation.",
            "Encoding": "The audio format sent to the provider. linear16 means signed 16-bit PCM and matches Talk DAT!'s mic stream.",
            "Endpointing ms": "How long Deepgram waits for silence before finalizing speech. Lower feels faster; higher is less likely to cut you off.",
            "Utterance end ms": "How long after speech end before an utterance-end event. 1000 ms is a forgiving dictation default.",
            "Include provider filler words": "When enabled, Deepgram includes words like um/uh in transcripts. Leave off for clean dictation; Talk DAT!'s cleanup can also remove fillers later.",
            "Smart format": "Provider-side formatting for dates, times, numbers, and punctuation when supported.",
            "Punctuation": "Ask the provider to add punctuation before Talk DAT!'s own cleanup runs.",
            "Interim results": "Show low-latency draft transcript events while the provider is still listening.",
            "VAD speech events": "Ask the provider to send speech-start/speech-end events for responsiveness and credit guards.",
            "Deepgram MIP opt-out": "Deepgram option to opt out of model-improvement processing where supported by your plan.",
            "Tail capture ms": "Extra audio kept after release so the last syllable is not chopped off.",
            "Minimum capture ms": "If speech is heard and you release quickly, Talk Dat keeps listening only long enough to make a usable local retry clip.",
            "Dictation preset": "Quick timing presets for common styles. They update the detailed timing fields below and can still be customized.",
            "Hold debounce ms": "Tiny delay that prevents accidental trigger flicker from starting/stopping a session.",
            "Hands-free max seconds": "Safety cap for toggle recording so a forgotten session cannot run forever.",
            "Hands-free no speech": "Credit guard: stops hands-free if no speech is heard soon after activation.",
            "Hands-free silence": "Credit guard: stops hands-free after a period of silence.",
            "Hold max seconds": "Maximum duration for press-and-hold dictation.",
            "Hold no speech": "Credit guard for hold mode when the mic opens but no speech starts.",
            "Hold silence": "Credit guard for hold mode after speech goes quiet.",
            "Microphone": f"The input device Talk DAT! listens to. Default follows your {mac_support.SYSTEM_DEFAULT_MIC_LABEL.lower()}.",
            "Input gain boost": "Software gain before transcription. Increase only if the meter stays low.",
            "Quiet mode boost": "Extra gain used only when whisper-quiet mode is enabled.",
            "Mic check": "Records a short local sample and reports the peak level. It does not send audio to a provider.",
            "Wake word model": "openWakeWord model name. Wake word is local and only runs when this feature is enabled.",
            "Paste method": "Clipboard paste is fast. Type mode simulates keystrokes for apps that block paste.",
            "History limit": "0 keeps all history. A positive number trims local history to that many entries.",
            "History storage": "jsonl is plain local text. sqlite is better for searching larger local history.",
            "Resize frame ms": "Target timer cadence for open/close animation. 8 ms with 22 steps is the responsive default.",
            "Resize steps": "How many cached frames are available for the pill open/close transition. 22 is the responsive default; valid range is 12-40.",
            "Translation source": "Auto follows the selected speech-recognition language. Choose a language here for pasted or manually entered text.",
            "Translation target": "The language Talk DAT! produces. Translation runs locally and is disabled until you turn it on.",
            "Translation quality": "Balanced is the best normal-PC default. Larger TranslateGemma models improve difficult translations but need more RAM and disk space.",
            "Translation register": "Natural is the safest everyday default. Formal, informal, and literal are available for specific writing needs.",
            "Auto-translate every dictation": "After transcription and cleanup, translate locally before the normal paste step. This remains off by default.",
        }
        # X-121, his order: "hover to explain features MUST be a thing on any
        # menu — every feature." The full per-control copy ships as an asset
        # (180 entries covering every tab); the inline dict above keeps the
        # hand-tuned lines and WINS on collision.
        try:
            import json as _json
            from pathlib import Path as _Path

            _tips_path = _Path(__file__).resolve().parent / "assets" / "settings_tips.json"
            for _entry in _json.loads(_tips_path.read_text(encoding="utf-8")):
                setting_help.setdefault(str(_entry.get("label", "")), str(_entry.get("tip", "")))
            setting_help.pop("", None)
        except Exception:
            log.debug("settings tips asset unavailable", exc_info=True)

        # X-121, his order: modern save logic. Every change saves ITSELF --
        # a 2.5s debounce after the last edit runs the same validated save()
        # the button runs, quietly. The button stays for instant certainty,
        # and half-typed numbers get their grace period.
        autosave_state: dict[str, Any] = {"after": None}

        def run_autosave() -> None:
            autosave_state["after"] = None
            if not settings_dirty["value"]:
                return
            try:
                save(quiet=True)
            except Exception:
                log.debug("autosave skipped", exc_info=True)

        def schedule_autosave() -> None:
            pending = autosave_state.get("after")
            if pending is not None:
                with contextlib.suppress(Exception):
                    window.after_cancel(pending)
            with contextlib.suppress(Exception):
                autosave_state["after"] = window.after(2500, run_autosave)

        def mark_dirty(*_args: Any) -> None:
            if settings_dirty["armed"]:
                settings_dirty["value"] = True
                set_save_status("Unsaved changes, saving…", "saving")
                schedule_autosave()

        def close_tooltip(
            owner: tk.Widget | None = None,
            *,
            immediate: bool = False,
            restore_focus: bool = False,
        ) -> None:
            if owner is not None and active_tooltip.get("owner") is not owner:
                return
            pending_close = active_tooltip.get("close_after")
            active_tooltip["close_after"] = None
            if pending_close is not None:
                with contextlib.suppress(tk.TclError):
                    window.after_cancel(pending_close)
            tooltip = active_tooltip.get("window")
            if tooltip is None:
                return
            focus_owner = active_tooltip.get("owner")
            if immediate:
                if active_tooltip.get("window") is tooltip:
                    active_tooltip["window"] = None
                    active_tooltip["owner"] = None
                    active_tooltip["interaction"] = None
                with contextlib.suppress(tk.TclError):
                    tooltip.destroy()
                if restore_focus and focus_owner is not None:
                    # Returning focus emits FocusIn on the owner. Suppress that
                    # one event so Escape dismisses help instead of instantly
                    # reopening the same help surface.
                    active_tooltip["suppress_owner"] = focus_owner
                    with contextlib.suppress(tk.TclError):
                        focus_owner.focus_set()
                return
            # Keep ownership until Destroy. If the pointer enters another
            # control during this short fade, show() can retire this exact
            # surface before creating its replacement instead of briefly
            # stacking two translucent tooltips.
            self._request_popup_close(tooltip, duration_ms=48)

        def schedule_tooltip_close(owner: tk.Widget) -> None:
            pending = active_tooltip.get("close_after")
            if pending is not None:
                with contextlib.suppress(tk.TclError):
                    window.after_cancel(pending)

            def close_if_unoccupied() -> None:
                active_tooltip["close_after"] = None
                interaction = active_tooltip.get("interaction")
                if (
                    active_tooltip.get("owner") is owner
                    and isinstance(interaction, dict)
                    and not interaction.get("hovered")
                    and not interaction.get("tip_hovered")
                    and not interaction.get("focused")
                    and not interaction.get("pinned")
                ):
                    close_tooltip(owner)

            with contextlib.suppress(tk.TclError):
                active_tooltip["close_after"] = window.after(
                    ui_scale.px(96, self.config),
                    close_if_unoccupied,
                )

        def attach_tip(widget: tk.Widget, text: str) -> None:
            if not text:
                return

            interaction = {
                "hovered": False,
                "tip_hovered": False,
                "focused": False,
                "pinned": False,
            }

            def show(
                _event: tk.Event | None = None,
                *,
                pinned: bool = False,
            ) -> None:
                # A tooltip changing owners is replacement, not two notices
                # cross-fading over one another.
                close_tooltip(immediate=True)
                interaction["pinned"] = bool(pinned)
                metric = lambda value: ui_scale.px(value, self.config)
                try:
                    x = widget.winfo_rootx() + metric(18)
                    y = widget.winfo_rooty() + widget.winfo_height() + metric(8)
                except tk.TclError:
                    return
                light = palette["mode"] == "light"
                fill = "#f8fbf6" if light else "#071418"
                tip = self._new_toplevel(window, role=AUXILIARY_CHROME)
                self._install_toplevel_timer_cleanup(tip)
                tip.overrideredirect(True)
                tip.attributes("-topmost", True)
                tip.configure(bg=fill)
                try:
                    tip.attributes("-alpha", 0.0)
                except Exception:
                    pass
                work_area = self._popup_work_area(window)
                gutter = metric(8)
                pad_x = metric(22)
                top_space = metric(30)
                bottom_space = metric(18)
                scroll_lane = metric(24)
                left, top, right, bottom = work_area
                available_width = max(1, right - left - 2 * gutter)
                available_height = max(1, bottom - top - 2 * gutter)
                # A 520-logical-pixel box landed exactly on a Segoe UI glyph
                # boundary at 125% and stranded the last word on its own line.
                # This small reserve keeps identical copy wrapping consistently
                # across 100/125/150/200% while respecting the monitor bounds.
                width = min(metric(544), available_width)
                content_width = max(1, width - 2 * pad_x)
                canvas = tk.Canvas(
                    tip,
                    width=width,
                    height=1,
                    bg=fill,
                    bd=0,
                    highlightthickness=0,
                )
                body = tk.Frame(canvas, bg=fill, bd=0, highlightthickness=0)
                body.columnconfigure(0, weight=1)
                body.rowconfigure(0, weight=1)
                body_canvas = tk.Canvas(
                    body,
                    width=content_width,
                    height=1,
                    bg=fill,
                    bd=0,
                    highlightthickness=0,
                    takefocus=0,
                    # A large Canvas scroll increment makes ``moveto(1.0)``
                    # round past the scrollregion whenever the remaining
                    # distance is not an exact multiple of that increment.
                    # Keep one-pixel viewport math and apply the comfortable
                    # logical step explicitly in ``scroll_units`` below.
                    yscrollincrement=1,
                )
                body_canvas.grid(row=0, column=0, sticky="nsew")
                copy = tk.Label(
                    body_canvas,
                    text=text,
                    anchor="nw",
                    justify="left",
                    wraplength=content_width,
                    bg=fill,
                    fg=palette["text"],
                    font=(BRAND_UI_FAMILY, type_scale.BODY),
                    bd=0,
                    highlightthickness=0,
                )
                copy_item = body_canvas.create_window(
                    0,
                    0,
                    window=copy,
                    anchor="nw",
                    width=content_width,
                )
                copy.update_idletasks()
                copy_height = max(1, copy.winfo_reqheight())
                desired_height = top_space + copy_height + bottom_space
                scrolling = desired_height > available_height
                scrollbar: ttk.Scrollbar | None = None
                if scrolling:
                    height = available_height
                    body_width = max(1, width - 2 * pad_x)
                    content_width = max(1, body_width - scroll_lane)
                    copy.configure(wraplength=content_width)
                    body_canvas.itemconfigure(copy_item, width=content_width)
                    copy.update_idletasks()
                    copy_height = max(1, copy.winfo_reqheight())
                    body_height = max(
                        1,
                        height - top_space - bottom_space,
                    )
                    body_canvas.configure(
                        width=content_width,
                        height=body_height,
                        takefocus=1,
                    )
                    scrollbar = ttk.Scrollbar(
                        body,
                        orient="vertical",
                        command=body_canvas.yview,
                        style="Flow.Vertical.TScrollbar",
                    )
                    scrollbar.grid(row=0, column=1, sticky="ns")
                    body_canvas.configure(yscrollcommand=scrollbar.set)
                else:
                    height = min(
                        available_height,
                        max(metric(92), desired_height),
                    )
                    body_width = content_width
                    body_height = copy_height
                    body_canvas.configure(width=content_width, height=body_height)
                body_canvas.configure(
                    scrollregion=(0, 0, content_width, copy_height),
                )
                below_y = y
                above_y = widget.winfo_rooty() - height - gutter
                if below_y + height > bottom - gutter and above_y >= top + gutter:
                    y = above_y
                x = max(left + gutter, min(x, right - width - gutter))
                y = max(top + gutter, min(y, bottom - height - gutter))
                tip.geometry(f"{width}x{height}+{x}+{y}")
                canvas.configure(height=height)
                canvas.pack(fill="both", expand=True)
                border_width = metric(1)
                far_border_inset = max(border_width, 2)
                canvas.create_rectangle(
                    border_width,
                    border_width,
                    width - far_border_inset,
                    height - far_border_inset,
                    fill=fill,
                    outline=palette["accent"],
                    width=border_width,
                )
                canvas.create_line(
                    metric(24),
                    metric(18),
                    width - metric(24),
                    metric(18),
                    fill=palette["warm"],
                    width=metric(1),
                )
                canvas.create_window(
                    pad_x,
                    top_space,
                    window=body,
                    anchor="nw",
                    width=body_width,
                    height=body_height,
                )
                active_tooltip["window"] = tip
                active_tooltip["owner"] = widget
                active_tooltip["interaction"] = interaction
                active_tooltip["scroll_canvas"] = body_canvas if scrolling else None
                tip._talkdat_tooltip_copy = copy  # type: ignore[attr-defined]
                tip._talkdat_tooltip_body = body_canvas  # type: ignore[attr-defined]
                tip._talkdat_tooltip_scrollbar = scrollbar  # type: ignore[attr-defined]
                tip._talkdat_tooltip_scroll_mode = scrolling  # type: ignore[attr-defined]
                tip._talkdat_tooltip_content_width = content_width  # type: ignore[attr-defined]

                def scroll_units(units: int) -> str:
                    body_canvas.yview_scroll(units * max(1, metric(20)), "units")
                    return "break"

                def scroll_pages(pages: int) -> str:
                    body_canvas.yview_scroll(pages, "pages")
                    return "break"

                if scrolling:
                    for target in (body_canvas, copy):
                        target.bind(
                            "<MouseWheel>",
                            lambda event: scroll_units(-1 if event.delta > 0 else 1),
                            add="+",
                        )
                        target.bind("<Button-4>", lambda _event: scroll_units(-1), add="+")
                        target.bind("<Button-5>", lambda _event: scroll_units(1), add="+")
                    body_canvas.bind("<Up>", lambda _event: scroll_units(-1), add="+")
                    body_canvas.bind("<Down>", lambda _event: scroll_units(1), add="+")
                    body_canvas.bind("<Prior>", lambda _event: scroll_pages(-1), add="+")
                    body_canvas.bind("<Next>", lambda _event: scroll_pages(1), add="+")
                    body_canvas.bind(
                        "<Home>",
                        lambda _event: (body_canvas.yview_moveto(0.0), "break")[-1],
                        add="+",
                    )
                    body_canvas.bind(
                        "<End>",
                        lambda _event: (body_canvas.yview_moveto(1.0), "break")[-1],
                        add="+",
                    )

                def tip_enter(_event: tk.Event | None = None) -> None:
                    interaction["tip_hovered"] = True
                    pending = active_tooltip.get("close_after")
                    active_tooltip["close_after"] = None
                    if pending is not None:
                        with contextlib.suppress(tk.TclError):
                            window.after_cancel(pending)

                def tip_leave(_event: tk.Event | None = None) -> None:
                    interaction["tip_hovered"] = False
                    schedule_tooltip_close(widget)

                tip.bind("<Enter>", tip_enter, add="+")
                tip.bind("<Leave>", tip_leave, add="+")
                tip.bind(
                    "<Escape>",
                    lambda _event: (
                        close_tooltip(widget, immediate=True, restore_focus=True),
                        "break",
                    )[-1],
                    add="+",
                )

                def forget_tip(event: tk.Event) -> None:
                    if (
                        event.widget is tip
                        and active_tooltip.get("window") is tip
                    ):
                        active_tooltip["window"] = None
                        active_tooltip["owner"] = None
                        active_tooltip["interaction"] = None

                tip.bind("<Destroy>", forget_tip, add="+")
                self._schedule_popup_present(tip, target=0.97, duration_ms=64)
                if pinned and scrolling:
                    with contextlib.suppress(tk.TclError):
                        body_canvas.focus_set()

            def enter(_event: tk.Event | None = None) -> None:
                interaction["hovered"] = True
                show()

            def leave(_event: tk.Event | None = None) -> None:
                interaction["hovered"] = False
                schedule_tooltip_close(widget)

            def focus_in(_event: tk.Event | None = None) -> None:
                interaction["focused"] = True
                if active_tooltip.get("suppress_owner") is widget:
                    active_tooltip["suppress_owner"] = None
                    return
                show()

            def focus_out(_event: tk.Event | None = None) -> None:
                interaction["focused"] = False
                schedule_tooltip_close(widget)

            def pin(_event: tk.Event | None = None) -> str:
                show(pinned=True)
                return "break"

            widget.bind("<Enter>", enter, add="+")
            widget.bind("<Leave>", leave, add="+")
            widget.bind("<FocusIn>", focus_in, add="+")
            widget.bind("<FocusOut>", focus_out, add="+")
            widget.bind("<F1>", pin, add="+")

        def show_saved_overlay(message: str = "Settings saved") -> None:
            self._show_settings_saved_overlay(window, palette, message)

        def prepare_settings_departure() -> bool:
            close_tooltip(immediate=True)
            if settings_dirty["value"]:
                answer = messagebox.askyesnocancel(
                    "Unsaved settings",
                    "You changed settings but have not saved them.\n\nYes = save and close\nNo = discard changes\nCancel = stay here",
                    parent=window,
                )
                if answer is None:
                    return False
                if answer:
                    if not save():
                        return False
            return True

        def request_settings_close() -> None:
            if prepare_settings_departure():
                self._request_utility_close(window)

        def handle_settings_escape(_event: tk.Event | None = None) -> str:
            tooltip = active_tooltip.get("window")
            if tooltip is not None:
                try:
                    if tooltip.winfo_exists():
                        close_tooltip(immediate=True, restore_focus=True)
                        return "break"
                except tk.TclError:
                    pass
            request_settings_close()
            return "break"

        window._talkdat_before_navigate = prepare_settings_departure  # type: ignore[attr-defined]
        window.bind("<Escape>", handle_settings_escape)
        window.protocol("WM_DELETE_WINDOW", request_settings_close)

        header = tk.Canvas(window, height=ui_scale.px(96, self.config), bg=palette["bg"], bd=0, highlightthickness=0)
        header.grid(row=0, column=0, sticky="ew", padx=ui_scale.spacing(16, self.config), pady=ui_scale.spacing((16, 8), self.config))
        self._bind_utility_drag_handle(window, header)

        style = ttk.Style(window)
        style.layout("Flow.Hidden.TNotebook.Tab", [])
        style.configure("Flow.Hidden.TNotebook", background=palette["panel"], borderwidth=0, tabmargins=0)

        console_shell = tk.Frame(window, bg=palette["bg"], bd=0, highlightthickness=0)
        console_shell.grid(row=1, column=0, sticky="nsew", padx=ui_scale.spacing(16, self.config), pady=ui_scale.spacing((0, 12), self.config))
        self._install_resize_visual_proxy(window, console_shell)
        console_shell.columnconfigure(1, weight=1)
        console_shell.rowconfigure(0, weight=1)
        # X-127: same surface as content_host -- rail + pages are one plane.
        navigation_host = tk.Frame(console_shell, bg=palette["panel"], bd=0, highlightthickness=0)
        navigation_host.grid(row=0, column=0, sticky="nsw")
        settings_search_var = tk.StringVar(value="")
        settings_search_entries: list[SettingsSearchEntry] = []
        settings_search_hits: list[SettingsSearchEntry] = []
        settings_search_callbacks: dict[str, Callable[..., Any]] = {
            "refresh": lambda *_args: None,
            "open": lambda *_args: None,
            "describe": lambda *_args: None,
        }
        settings_search_shell = tk.Frame(
            navigation_host,
            bg=palette["panel"],
            bd=0,
            highlightthickness=0,
        )
        settings_search_shell.pack(fill="x", padx=ui_scale.spacing(12, self.config), pady=ui_scale.spacing((12, 8), self.config))
        settings_search_title_row = tk.Frame(
            settings_search_shell,
            bg=palette["panel"],
            bd=0,
            highlightthickness=0,
        )
        settings_search_title_row.pack(fill="x", pady=ui_scale.spacing((0, 4), self.config))
        settings_search_label = tk.Label(
            settings_search_title_row,
            text="Find a setting",
            bg=palette["panel"],
            fg=palette["text"],
            font=(BRAND_UI_FAMILY, type_scale.SUBHEADING, "bold"),
            anchor="w",
        )
        settings_search_label.pack(side="left", fill="x", expand=True)
        # Clear used to be a full button ABOVE and beside the label, offering
        # to empty a field that had not been typed in yet. It is now inline
        # with the field and only exists while there is something to clear.
        settings_search_field_row = tk.Frame(
            settings_search_shell,
            bg=palette["panel"],
            bd=0,
            highlightthickness=0,
        )
        settings_search_field_row.pack(fill="x")
        settings_search_clear = ttk.Button(
            settings_search_field_row,
            text="Clear",
            style="Flow.TButton",
            command=lambda: settings_search_var.set(""),
        )
        settings_search_entry = ttk.Entry(
            settings_search_field_row,
            textvariable=settings_search_var,
            style="Flow.TEntry",
            width=20,
        )
        settings_search_entry.pack(side="left", fill="x", expand=True)

        def sync_search_clear(*_args: Any) -> None:
            wanted = bool(str(settings_search_var.get()).strip())
            try:
                shown = bool(settings_search_clear.winfo_manager())
            except tk.TclError:
                return
            if wanted == shown:
                return
            with contextlib.suppress(tk.TclError):
                if wanted:
                    # `before` keeps pack's cavity order: the expanding entry
                    # must be allocated after this, or there is no room left
                    # for it to sit in.
                    settings_search_clear.pack(
                        side="right",
                        before=settings_search_entry,
                        padx=ui_scale.spacing((8, 0), self.config),
                    )
                else:
                    settings_search_clear.pack_forget()

        settings_search_var.trace_add("write", sync_search_clear)
        sync_search_clear()
        settings_search_status = tk.Label(
            settings_search_shell,
            text="Search labels, help, or older menu names.",
            bg=palette["panel"],
            fg=palette["muted"],
            font=(BRAND_UI_FAMILY, type_scale.SECONDARY),
            anchor="w",
            justify="left",
            wraplength=ui_scale.px(180, self.config),
        )
        settings_search_status.pack(fill="x", pady=ui_scale.spacing((4, 0), self.config))
        settings_search_results_box = tk.Listbox(
            navigation_host,
            height=7,
            activestyle="dotbox",
            exportselection=False,
            takefocus=True,
            bd=0,
            highlightthickness=ui_scale.px(2, self.config),
            relief="flat",
            bg=palette["field"],
            fg=palette["text"],
            selectbackground=palette["select"],
            selectforeground=palette["text"],
            highlightbackground=palette["stroke"],
            highlightcolor=palette["accent"],
        )
        settings_search_results_box.bind(
            "<Return>",
            lambda _event: settings_search_callbacks["open"](),
            add="+",
        )
        settings_search_results_box.bind(
            "<Double-Button-1>",
            lambda _event: settings_search_callbacks["open"](),
            add="+",
        )
        settings_search_entry.bind(
            "<Return>",
            lambda _event: settings_search_callbacks["open"](0),
            add="+",
        )
        settings_search_entry.bind(
            "<Down>",
            lambda _event: (
                settings_search_results_box.selection_clear(0, "end"),
                settings_search_results_box.selection_set(0),
                settings_search_results_box.focus_set(),
                "break",
            )[-1] if settings_search_hits else None,
            add="+",
        )
        settings_search_entry.bind(
            "<Escape>",
            lambda _event: (settings_search_var.set(""), "break")[1],
            add="+",
        )
        settings_search_results_box.bind(
            "<Escape>",
            lambda _event: (
                settings_search_var.set(""),
                settings_search_results_box.pack_forget(),
                settings_search_entry.focus_set(),
                "break",
            )[-1],
            add="+",
        )
        settings_search_results_box.bind(
            "<<ListboxSelect>>",
            lambda _event: settings_search_callbacks["describe"](),
            add="+",
        )
        content_host = tk.Frame(console_shell, bg=palette["panel"], bd=0, highlightthickness=0)
        content_host.grid(row=0, column=1, sticky="nsew")
        content_host.columnconfigure(0, weight=1)
        content_host.rowconfigure(0, weight=1)
        # The rail is the visible navigation. The page stack isolates inactive
        # page geometry so resize reconciliation touches only what is visible.
        notebook = FlowPageStack(
            content_host,
            style="Flow.TFrame",
            width=1,
            height=1,
        )
        notebook.grid(row=0, column=0, sticky="nsew")
        window._settings_page_stack = notebook  # type: ignore[attr-defined]
        # Virtual notebook events fire synchronously while pages are destroyed.
        # Their callbacks reach the sibling navigation rail and microphone
        # controls, so staged retirement must detach them before either sibling
        # disappears. Keep exact funcids rather than erasing class bindings.
        retirement_unbinds: list[tuple[tk.Misc, str, str]] = []
        window._talkdat_retire_unbinds = retirement_unbinds  # type: ignore[attr-defined]
        settings_subnavs: list[FlowSubnav] = []

        # X-74: ONE level of tabs. Each page scrolls; the old nested-notebook
        # tabs became labelled sections inside these pages, so every builder
        # below runs unchanged against the same variable names.
        page_outers: dict[str, ttk.Frame] = {}

        def make_scroll_tab(title: str) -> ttk.Frame:
            outer = ttk.Frame(notebook, style="Flow.TFrame")
            notebook.add(outer, text=title)
            outer.columnconfigure(0, weight=1)
            outer.rowconfigure(0, weight=1)
            canvas = tk.Canvas(outer, bg=palette["panel"], bd=0, highlightthickness=0)
            canvas.grid(row=0, column=0, sticky="nsew")
            bar = ttk.Scrollbar(outer, orient="vertical", command=canvas.yview)
            bar.grid(row=0, column=1, sticky="ns")
            canvas.configure(yscrollcommand=bar.set)
            inner = ttk.Frame(canvas, padding=ui_scale.spacing(16, self.config), style="Flow.TFrame")
            inner_id = canvas.create_window((0, 0), window=inner, anchor="nw")
            layout_state: dict[str, Any] = {
                "after": None,
                "content_geometry": None,
                "scrollregion": None,
            }

            def layout_signature() -> tuple[Any, ...] | None:
                try:
                    # The completed predecessor intentionally covers this page
                    # during staging. Tk therefore reports the canvas-window
                    # child as globally unmapped even after it has a real
                    # 900px-capped geometry, bbox, and scroll region. Requiring
                    # global visibility made every healthy transition wait for
                    # the 1.2s emergency fallback. The mapped viewport plus the
                    # canvas-owned child and complete geometry state are the
                    # actual readiness contract.
                    if not canvas.winfo_ismapped() or inner.winfo_manager() != "canvas":
                        return None
                    bounds = canvas.bbox("all")
                    content_geometry = layout_state["content_geometry"]
                    scrollregion = layout_state["scrollregion"]
                    viewport_width = canvas.winfo_width()
                    viewport_height = canvas.winfo_height()
                    if (
                        viewport_width <= 1
                        or viewport_height <= 1
                        or content_geometry is None
                        or bounds is None
                        or scrollregion is None
                    ):
                        return None
                    return (
                        viewport_width,
                        viewport_height,
                        content_geometry,
                        max(1, inner.winfo_reqwidth()),
                        max(1, inner.winfo_reqheight()),
                        tuple(bounds),
                        scrollregion,
                    )
                except tk.TclError:
                    return None

            def apply_layout() -> None:
                layout_state["after"] = None
                try:
                    if not canvas.winfo_exists():
                        return
                    viewport_width = max(1, canvas.winfo_width())
                    maximum_form_width = max(
                        1,
                        ui_scale.px(900, self.config),
                    )
                    content_width = min(viewport_width, maximum_form_width)
                    content_x = max(0, (viewport_width - content_width) // 2)
                    geometry = (content_x, content_width)
                    previous_geometry = layout_state["content_geometry"]
                    if geometry != previous_geometry:
                        if (
                            previous_geometry is None
                            or content_width != int(previous_geometry[1])
                        ):
                            canvas.itemconfigure(inner_id, width=content_width)
                        if (
                            previous_geometry is None
                            or content_x != int(previous_geometry[0])
                        ):
                            canvas.coords(inner_id, content_x, 0)
                        layout_state["content_geometry"] = geometry
                    bounds = canvas.bbox("all")
                    scrollregion = (
                        (
                            0,
                            min(0, int(bounds[1])),
                            max(viewport_width, int(bounds[2])),
                            max(1, int(bounds[3])),
                        )
                        if bounds is not None
                        else None
                    )
                    if scrollregion != layout_state["scrollregion"]:
                        canvas.configure(
                            scrollregion=scrollregion or (0, 0, viewport_width, 1)
                        )
                        layout_state["scrollregion"] = scrollregion
                    notebook.report_layout(outer, layout_signature())
                except tk.TclError:
                    pass

            def on_config(_event: tk.Event | None = None) -> None:
                if layout_state["after"] is None:
                    with contextlib.suppress(tk.TclError):
                        layout_state["after"] = canvas.after_idle(apply_layout)

            inner.bind("<Configure>", on_config, add="+")
            canvas.bind("<Configure>", on_config, add="+")
            setattr(outer, "_scroll_canvas", canvas)
            setattr(outer, "_scroll_inner", inner)
            setattr(outer, "_scroll_inner_id", inner_id)
            setattr(outer, "_scroll_layout_state", layout_state)
            setattr(outer, "_sections", {})
            notebook.register_layout_probe(outer, layout_signature)
            page_outers[title] = outer
            return inner

        def _wheel_target(event: tk.Event) -> tk.Canvas | None:
            widget = event.widget
            while widget is not None:
                canvas = getattr(widget, "_scroll_canvas", None)
                if canvas is not None:
                    return canvas
                widget = getattr(widget, "master", None)
            return None

        def on_settings_wheel(event: tk.Event) -> str | None:
            canvas = _wheel_target(event)
            if canvas is None or not canvas.winfo_exists():
                return None
            try:
                canvas.yview_scroll(-1 * int(event.delta / 120), "units")
            except tk.TclError:
                return None
            return "break"

        window.bind_all("<MouseWheel>", on_settings_wheel, add="+")
        window.bind(
            "<Destroy>",
            lambda event: window.unbind_all("<MouseWheel>") if event.widget is window else None,
            add="+",
        )

        advanced_section_summaries = {
            "Dictionary (raw editor)": "Specialist JSON editor. Most vocabulary work is easier in Words & phrases.",
            "Advanced (STT)": "Provider timing and protocol details for troubleshooting or custom deployments.",
            "Backups + diagnostics": "Maintenance, export, and diagnostic controls used less often.",
            "Speech check": "Record a sample and review your local speech model.",
            # Tesler + Hick (DESIGN.md, Behavioral Laws, 2026-08-31): the
            # defaults carry the complexity. These three surfaces are for the
            # person who wants them, never a prerequisite -- so they fold.
            "Pill": "Fine-tuning for the pill's size, timing and placement. The defaults are tuned; open this only if the pill blocks your workflow or a monitor needs adjustment.",
            "Advanced options JSON": "Raw provider options for custom deployments. The route cards above cover normal use.",
            "Custom transforms JSON": "Raw transform definitions for specialist cleanup. Smart formatting and the presets above cover normal use.",
            "Voice shortcuts": "Say an exact phrase, paste saved text. Edited as JSON; open this to add or change a shortcut.",
        }

        def section(host: ttk.Frame, title: str) -> ttk.Frame:
            holder = tk.Frame(host, bg=palette["panel"], bd=0, highlightthickness=0)
            holder.pack(fill="x", expand=True, anchor="n", pady=ui_scale.spacing((0, 12), self.config))
            title_row = tk.Frame(holder, bg=palette["panel"], bd=0, highlightthickness=0)
            title_row.pack(fill="x", pady=ui_scale.spacing((4, 8), self.config))
            tk.Label(
                title_row, text=title, bg=palette["panel"], fg=palette["text"],
                font=self._display_font(type_scale.HEADING), anchor="w",
            ).pack(side="left", fill="x", expand=True)
            body = ttk.Frame(holder, style="Flow.TFrame")
            summary = advanced_section_summaries.get(title)

            def set_expanded(expanded: bool) -> None:
                if expanded:
                    body.pack(fill="x", expand=True)
                    if disclosure is not None:
                        disclosure.configure(text="Hide details")
                else:
                    body.pack_forget()
                    if disclosure is not None:
                        disclosure.configure(text="Show details")
                setattr(holder, "_settings_expanded", bool(expanded))

            disclosure: ttk.Button | None = None
            if summary:
                disclosure = ttk.Button(
                    title_row,
                    text="Show details",
                    style="Flow.TButton",
                    command=lambda: set_expanded(
                        not bool(getattr(holder, "_settings_expanded", False))
                    ),
                )
                disclosure.pack(side="right", padx=ui_scale.spacing((12, 0), self.config))
                tk.Label(
                    holder,
                    text=summary,
                    bg=palette["panel"],
                    fg=palette["muted"],
                    font=(BRAND_UI_FAMILY, type_scale.BODY),
                    anchor="w",
                    justify="left",
                    wraplength=ui_scale.px(760, self.config),
                ).pack(fill="x", pady=ui_scale.spacing((0, 8), self.config))
                set_expanded(False)
            else:
                set_expanded(True)
            setattr(holder, "_settings_expand", lambda: set_expanded(True))
            setattr(holder, "_settings_body", body)
            setattr(holder, "_settings_section_title", title)
            outer = host.master.master if isinstance(host.master, tk.Canvas) else host
            registry = getattr(outer, "_sections", None)
            if isinstance(registry, dict):
                registry[title.lower()] = holder
            return body

        general_page = make_scroll_tab("General")
        colors_page = make_scroll_tab("Colors")
        dictation_page = make_scroll_tab("Dictation")
        formatting_page = make_scroll_tab("Formatting")
        speech_page = make_scroll_tab("Speech")
        advanced_page = make_scroll_tab("Advanced")
        # X-529: the Tools tab is gone. It carried no settings -- it was five
        # buttons that opened other windows, and every one of them already had
        # a home: account, words and Mic Doctor are sidebar destinations, and
        # Race is a real section on Advanced. A preferences window is the wrong
        # place for a launcher, and two doors to one page is what made this
        # read as "a menu within a menu".

        # General: the app-wide facts and looks. "Home" is dead.
        core_tab = section(general_page, "At a glance")
        overlay_tab = section(general_page, "Pill")
        privacy_tab = section(general_page, "Privacy + updates")
        # X-529: the only tool from the retired Tools tab with nowhere else to
        # live. Everything else there already had a home.
        idea_section = section(general_page, "Share an idea")
        idea_row = tk.Frame(idea_section, bg=palette["panel"])
        idea_row.grid(row=0, column=0, sticky="w", pady=ui_scale.spacing((0, 4), self.config))
        ttk.Button(
            idea_row, text="Share an idea", style="Flow.TButton",
            command=lambda: self.open_feedback_form("feature"),
        ).pack(side="left")

        # Dictation: everything between pressing the hotkey and the paste.
        audio_tab = section(dictation_page, "Mic + paste")
        dictation_tab = section(dictation_page, "Timing + safety")
        hotkeys_tab = section(dictation_page, "Hotkeys")

        # Formatting: what the words look like once they land. The Translation
        # section retires into the Translate window with X-77; the raw
        # dictionary editor retires into Words & phrases with X-72.
        transforms_tab = section(formatting_page, "Formatting")
        snippets_tab = section(formatting_page, "Voice shortcuts")
        dictionary_tab = section(formatting_page, "Dictionary (raw editor)")
        translation_tab = section(formatting_page, "Translation")

        # Speech: which engine hears you. Two routes since X-480, and the
        # managed one is not one of them.
        providers_tab = section(speech_page, "Your own provider")
        local_models_tab = section(speech_page, "Local models")
        deepgram_tab = section(speech_page, "Advanced (STT)")

        # X-155, reported twice: "color settings does nothing". The Colors page
        # was built and added to the notebook, and the rail advertised it, but
        # this map -- the only thing that turns a rail click into a page -- had
        # no "colors" entry. select_top_section looked it up, got None, and
        # returned. A dead tab that looks alive, with no error anywhere.
        top_tabs = {
            "general": page_outers["General"],
            "colors": page_outers["Colors"],
            "dictation": page_outers["Dictation"],
            "formatting": page_outers["Formatting"],
            "speech": page_outers["Speech"],
            "advanced": page_outers["Advanced"],
        }
        # Heavy page collections register their builders later in this method.
        # Navigation can call this registry without coupling the lightweight
        # Settings scaffold to controls that have not been constructed yet.
        lazy_page_loaders: dict[str, Callable[[], None]] = {}
        # Every section the rail offers must land somewhere. Silently swallowing
        # a click is how the Colors tab stayed broken through two reports, so a
        # missing page is now loud at build time instead of dead at click time.
        missing = [key for key, _label, _hint in FLOW_CONSOLE_SECTIONS if key not in top_tabs]
        if missing:
            raise RuntimeError(f"settings rail advertises sections with no page: {missing}")
        navigation_ref: dict[str, FlowNavigationRail | None] = {"rail": None}

        def selected_section_key() -> str:
            selected = notebook.select()
            for candidate_key, candidate_frame in top_tabs.items():
                if str(candidate_frame) == str(selected):
                    return candidate_key
            return "general"

        def prepare_settings_page(key: str, label: str) -> bool:
            loader = lazy_page_loaders.get(key)
            if not callable(loader):
                return True
            try:
                loader()
            except Exception as exc:
                # A destination is a transaction: a failed lazy builder cannot
                # leave its rail item selected while the predecessor remains on
                # screen. Keep the complete page and make the failure explicit.
                log.exception("could not prepare Settings page %s", label)
                with contextlib.suppress(Exception):
                    self.set_state(
                        "error",
                        f"Could not open {label} settings.",
                        f"Your current page is still available. Try again. ({exc.__class__.__name__})",
                    )
                return False
            return True

        def select_top_section(key: str) -> None:
            frame = top_tabs.get(key)
            if frame is None:
                return
            previous_key = selected_section_key()
            label = next(
                (section_label for section_key, section_label, _hint in FLOW_CONSOLE_SECTIONS if section_key == key),
                key.title(),
            )
            if not prepare_settings_page(key, label):
                rail = navigation_ref["rail"]
                if rail is not None:
                    rail.select(previous_key, notify=False)
                return
            notebook.select(frame)
            rail = navigation_ref["rail"]
            if rail is not None and rail.selected != key:
                rail.select(key, notify=False)

        navigation_rail = FlowNavigationRail(
            navigation_host,
            FLOW_CONSOLE_SECTIONS,
            select_top_section,
            palette,
            width=188,
            scale=ui_scale.scale(self.config),
        )
        navigation_rail.pack(fill="both", expand=True)
        navigation_ref["rail"] = navigation_rail

        def sync_top_navigation(_event: tk.Event | None = None) -> None:
            selected = notebook.select()
            for key, frame in top_tabs.items():
                if str(frame) == str(selected):
                    navigation_rail.select(key, notify=False)
                    break

        top_navigation_binding = notebook.bind(
            "<<NotebookTabChanged>>", sync_top_navigation, add="+"
        )
        if top_navigation_binding:
            retirement_unbinds.append(
                (notebook, "<<NotebookTabChanged>>", top_navigation_binding)
            )

        # Legacy page names still arrive from deep links minted before X-74
        # (tray, pill menu, the model guide). Map every old (top, child)
        # address to its new (page, section) home so no caller breaks.
        LEGACY_SETTINGS_PAGES = {
            ("Voice", "Provider"): ("Speech", "cloud + providers"),
            ("Voice", "Local Models"): ("Speech", "local models"),
            ("Voice", "Mic + Paste"): ("Dictation", "mic + paste"),
            ("Voice", "Timing + Safety"): ("Dictation", "timing + safety"),
            ("Voice", "STT Advanced"): ("Speech", "advanced (stt)"),
            ("Writing", "Formatting"): ("Formatting", "formatting"),
            ("Writing", "Translation"): ("Formatting", "translation"),
            ("Writing", "Dictionary"): ("Formatting", "dictionary (raw editor)"),
            ("Writing", "Voice Shortcuts"): ("Formatting", "voice shortcuts"),
            ("System", "Pill"): ("General", "pill"),
            ("System", "Hotkeys"): ("Dictation", "hotkeys"),
            ("System", "Privacy + Updates"): ("General", "privacy + updates"),
        }

        def select_settings_page(top_title: str, _legacy_notebook: object | None = None, child_title: str | None = None) -> None:
            try:
                aliases = {"Start": "General", "Home": "General", "Text": "Writing"}
                top_title = aliases.get(top_title, top_title)
                section_key = (child_title or "").lower()
                mapped = LEGACY_SETTINGS_PAGES.get((top_title, child_title or ""))
                if mapped is not None:
                    top_title, section_key = mapped
                target = page_outers.get(top_title)
                if target is None:
                    return
                if not prepare_settings_page(top_title.casefold(), top_title):
                    rail = navigation_ref["rail"]
                    if rail is not None:
                        rail.select(selected_section_key(), notify=False)
                    return
                notebook.select(target)
                if section_key:
                    holder = getattr(target, "_sections", {}).get(section_key)
                    canvas = getattr(target, "_scroll_canvas", None)
                    inner = getattr(target, "_scroll_inner", None)
                    if holder is not None and canvas is not None and inner is not None:
                        expand = getattr(holder, "_settings_expand", None)
                        if callable(expand):
                            expand()
                        def scroll_to(attempt: int = 0) -> None:
                            """Scroll to a section, once the page has a height.

                            X-185. `after_idle` is not late enough: on a page
                            swapped into the shell the content frame has not been
                            laid out yet, so `inner.winfo_height()` is 1. The
                            `max(1, ...)` then divided by 1 and produced a
                            fraction far past the end, so the deep link landed at
                            the bottom of the page instead of on the section --
                            which is how Offline speech appeared to go nowhere.

                            Waiting for a real measurement is the fix; retrying
                            rather than sleeping keeps it off the UI thread. The
                            attempt cap means a page that never lays out costs
                            twenty idle callbacks, not an endless loop.
                            """
                            try:
                                window.update_idletasks()
                                total = inner.winfo_height()
                                if total <= 1 and attempt < 20:
                                    window.after(30, lambda: scroll_to(attempt + 1))
                                    return
                                canvas.yview_moveto(max(0.0, holder.winfo_y() / max(1, total)))
                            except tk.TclError:
                                pass
                        window.after_idle(scroll_to)
                sync_top_navigation()
            except tk.TclError:
                pass

        def refresh_settings_search(*_args: Any) -> None:
            query = settings_search_var.get().strip()
            settings_search_hits[:] = list(
                settings_search_results(settings_search_entries, query, limit=8)
            )
            settings_search_results_box.delete(0, "end")
            for hit in settings_search_hits:
                # The navigation rail is intentionally compact.  Putting the
                # label and its full page path on one Listbox line made the
                # destination look abruptly chopped off at ordinary widths.
                # Keep the hit itself scannable and put the selected location
                # in the wrapped status line below the field.
                settings_search_results_box.insert("end", hit.label)
            if not query:
                settings_search_results_box.pack_forget()
                settings_search_status.configure(
                    text="Search labels, help, or older menu names."
                )
                return
            if settings_search_hits:
                settings_search_results_box.pack(
                    fill="x",
                    padx=ui_scale.spacing(12, self.config),
                    pady=ui_scale.spacing((0, 8), self.config),
                    before=navigation_rail,
                )
                settings_search_results_box.selection_clear(0, "end")
                settings_search_results_box.selection_set(0)
                describe_settings_search_result(0)
            else:
                settings_search_results_box.pack_forget()
                settings_search_status.configure(
                    text="No setting matched. Try a feature, device, or older menu name."
                )

        def describe_settings_search_result(index: int | None = None) -> None:
            if not settings_search_hits:
                return
            if index is None:
                selection = settings_search_results_box.curselection()
                index = int(selection[0]) if selection else 0
            index = max(0, min(int(index), len(settings_search_hits) - 1))
            hit = settings_search_hits[index]
            location = hit.page if not hit.section else f"{hit.page} / {hit.section}"
            count = len(settings_search_hits)
            settings_search_status.configure(
                text=(
                    f"{count} result{'s' if count != 1 else ''}. "
                    f"Selected: {location}. Enter opens."
                )
            )

        def open_settings_search_result(index: int | None = None) -> str:
            if not settings_search_hits:
                return "break"
            if index is None:
                selection = settings_search_results_box.curselection()
                index = int(selection[0]) if selection else 0
            index = max(0, min(int(index), len(settings_search_hits) - 1))
            hit = settings_search_hits[index]
            select_settings_page(hit.page, None, hit.section)
            settings_search_results_box.pack_forget()
            settings_search_status.configure(
                text=f"Opened {hit.label} in {hit.page}."
            )
            settings_search_entry.focus_set()
            return "break"

        def build_settings_search_index() -> None:
            candidates: list[SettingsSearchEntry] = []
            positions: dict[tuple[str, str, str], int] = {}

            def add(
                page: str,
                section_title: str,
                label: str,
                *,
                help_text: str = "",
                aliases: tuple[str, ...] = (),
            ) -> None:
                clean_label = " ".join(str(label).split())
                if not clean_label or len(clean_label) > 100:
                    return
                key = (page.casefold(), section_title.casefold(), clean_label.casefold())
                existing_index = positions.get(key)
                if existing_index is not None:
                    existing = candidates[existing_index]
                    candidates[existing_index] = SettingsSearchEntry(
                        page=existing.page,
                        section=existing.section,
                        label=existing.label,
                        help_text=existing.help_text or help_text,
                        aliases=tuple(dict.fromkeys((*existing.aliases, *aliases))),
                    )
                    return
                positions[key] = len(candidates)
                candidates.append(
                    SettingsSearchEntry(
                        page=page,
                        section=section_title,
                        label=clean_label,
                        help_text=help_text,
                        aliases=aliases,
                    )
                )

            for key, label, hint in FLOW_CONSOLE_SECTIONS:
                add(label, "", label, help_text=hint, aliases=(key, hint))

            for page, outer in page_outers.items():
                for section_key, holder in getattr(outer, "_sections", {}).items():
                    section_title = str(
                        getattr(holder, "_settings_section_title", section_key)
                    )
                    add(page, section_title, section_title)
                    stack = [holder]
                    while stack:
                        widget = stack.pop()
                        with contextlib.suppress(tk.TclError):
                            stack.extend(widget.winfo_children())
                        try:
                            text_value = str(widget.cget("text"))
                        except (tk.TclError, TypeError):
                            continue
                        clean = " ".join(text_value.split())
                        if clean:
                            add(
                                page,
                                section_title,
                                clean,
                                help_text=setting_help.get(clean, ""),
                            )

            for (legacy_page, legacy_child), (page, section_key) in LEGACY_SETTINGS_PAGES.items():
                add(
                    page,
                    section_key,
                    legacy_child or legacy_page,
                    aliases=(legacy_page, legacy_child, f"{legacy_page} {legacy_child}"),
                )

            # The two largest collections are intentionally unbuilt on the
            # default General page. Preserve their search reachability from
            # model data instead of forcing hundreds of hidden widgets to exist
            # merely so this index can read their labels.
            for option in self._settings_theme_options():
                add(
                    "Colors",
                    "Theme",
                    option,
                    help_text="Apply this theme to Talk DAT! Settings.",
                    aliases=("theme", "color", "appearance"),
                )
            for model in available_local_models(self.config):
                add(
                    "Speech",
                    "Local models",
                    str(model.label),
                    help_text=str(model.notes or "On-device speech model."),
                    aliases=(str(model.id), "offline speech", "local model"),
                )

            settings_search_entries[:] = candidates

        settings_search_callbacks["refresh"] = refresh_settings_search
        settings_search_callbacks["open"] = open_settings_search_result
        settings_search_callbacks["describe"] = describe_settings_search_result

        def redraw_header(_event: tk.Event | None = None) -> None:
            self._draw_settings_header(
                header,
                max(1, header.winfo_width()),
                max(ui_scale.px(96, self.config), header.winfo_height()),
                theme_var.get(),
                show_close=False,
            )

        def add_row(parent: ttk.Frame, row: int, label: str, widget: tk.Widget) -> None:
            label_widget = ttk.Label(parent, text=label, style="Flow.TLabel")
            label_widget.grid(row=row, column=0, sticky="w", pady=ui_scale.spacing(4, self.config), padx=ui_scale.spacing((0, 16), self.config))
            widget.grid(row=row, column=1, sticky="ew", pady=ui_scale.spacing(4, self.config))
            parent.columnconfigure(1, weight=1)
            help_text = setting_help.get(label, "")
            attach_tip(label_widget, help_text)
            attach_tip(widget, help_text)

        def action_row(parent: ttk.Frame, row: int, label: str, widget: tk.Widget) -> None:
            """An action row, for a control that DOES something rather than holds a value.

            `add_row` stretches its widget across the whole value column, which
            is right for an input and wrong for a button: "Check / install
            latest" rendered as a full-width centred slab, visually identical
            to the disabled fields above it, and so it did not read as
            something you could press. Same label column, same rhythm; the
            control keeps its natural width and sits at the end of its row.
            """

            label_widget = ttk.Label(parent, text=label, style="Flow.TLabel")
            label_widget.grid(row=row, column=0, sticky="w", pady=ui_scale.spacing(4, self.config), padx=ui_scale.spacing((0, 16), self.config))
            widget.grid(row=row, column=1, sticky="e", pady=ui_scale.spacing(4, self.config))
            parent.columnconfigure(1, weight=1)
            help_text = setting_help.get(label, "")
            attach_tip(label_widget, help_text)
            attach_tip(widget, help_text)

        def entry(parent: ttk.Frame, variable: tk.StringVar, width: int = 18, show: str | None = None) -> ttk.Entry:
            return ttk.Entry(parent, textvariable=variable, width=width, show=show or "", style="Flow.TEntry")

        def combo(parent: ttk.Frame, variable: tk.StringVar, values: list[str], width: int = 28) -> ttk.Combobox:
            return ttk.Combobox(parent, textvariable=variable, values=values, width=width, style="Flow.TCombobox")

        def check(parent: ttk.Frame, text: str, variable: tk.BooleanVar, row: int) -> ttk.Checkbutton:
            widget = ttk.Checkbutton(parent, text=text, variable=variable, style="Flow.TCheckbutton")
            widget.grid(
                row=row, column=0, columnspan=2, sticky="w", pady=ui_scale.spacing(4, self.config)
            )
            attach_tip(widget, setting_help.get(text, ""))
            return widget

        def gain_meter_knob(
            parent: ttk.Frame,
            variable: tk.StringVar,
            *,
            low: float,
            high: float,
            default: float,
            caption: str,
        ) -> ttk.Frame:
            holder = ttk.Frame(parent, style="Flow.TFrame")
            holder.columnconfigure(1, weight=1)
            metric = lambda value: ui_scale.px(value, self.config)
            canvas = tk.Canvas(
                holder,
                width=metric(132),
                height=metric(112),
                bg=palette["panel"],
                bd=0,
                highlightthickness=metric(2),
                highlightbackground=palette["stroke"],
                highlightcolor=palette["warm"],
                # The dial remains a direct-manipulation visual, but the real
                # semantic control is the native Scale beside it.  Keeping the
                # Canvas out of Tab traversal prevents an anonymous graphics
                # object from masquerading as a slider to keyboard and AT users.
                takefocus=0,
                cursor="hand2",
            )
            canvas.grid(row=0, column=0, rowspan=4, sticky="w", padx=ui_scale.spacing((0, 16), self.config))
            value_label = ttk.Label(holder, style="Flow.TLabel")
            value_label.grid(row=0, column=1, sticky="w", pady=ui_scale.spacing((8, 0), self.config))
            ttk.Label(holder, text=caption, style="Flow.Muted.TLabel").grid(row=1, column=1, sticky="w")
            ttk.Label(holder, text="Use the slider or drag the dial.", style="Flow.Muted.TLabel").grid(
                row=3, column=1, sticky="w", pady=ui_scale.spacing((4, 8), self.config)
            )

            def current_value() -> float:
                try:
                    value = float(str(variable.get()).strip())
                except ValueError:
                    value = default
                return float(self._clamp(value, low, high))

            def norm_for_value(value: float) -> float:
                if low <= 0 or high <= low:
                    return 0.0
                return float(self._clamp(math.log(value / low) / math.log(high / low), 0.0, 1.0))

            def value_for_norm(norm: float) -> float:
                norm = float(self._clamp(norm, 0.0, 1.0))
                if low <= 0:
                    return low + (high - low) * norm
                return low * ((high / low) ** norm)

            slider_var = tk.DoubleVar(value=norm_for_value(current_value()))
            slider_sync = {"value": False}

            def format_gain(value: float) -> str:
                if value < 1:
                    return f"{value:.2f}x"
                return f"{value:.2f}".rstrip("0").rstrip(".") + "x"

            def set_value(value: float) -> None:
                value = float(self._clamp(value, low, high))
                variable.set(format_gain(value).removesuffix("x"))

            def norm_from_pointer(x: int, y: int) -> float:
                cx, cy = metric(54), metric(56)
                raw = math.degrees(math.atan2(cy - y, x - cx))
                candidates = [raw, raw + 360, raw - 360]

                def score(angle: float) -> float:
                    candidate = (225 - angle) / 270
                    if 0 <= candidate <= 1:
                        return 0
                    return min(abs(candidate), abs(candidate - 1))

                best_angle = min(candidates, key=score)
                return float(self._clamp((225 - best_angle) / 270, 0.0, 1.0))

            def draw() -> None:
                canvas.configure(
                    bg=palette["panel"],
                    highlightbackground=palette["stroke"],
                    highlightcolor=palette["warm"],
                )
                canvas.delete("all")
                value = current_value()
                norm = norm_for_value(value)
                cx, cy, radius = metric(54), metric(56), metric(34)
                light = palette["mode"] == "light"
                shadow = "#071113" if not light else "#cfd8d1"
                face = palette["button"]
                field = palette["field"]
                stroke = palette["stroke"]
                accent = palette["accent"]
                warm = palette["warm"]
                text = palette["text"]
                muted = palette["muted"]
                canvas.create_oval(cx - metric(43), cy - metric(37), cx + metric(43), cy + metric(49), fill=shadow, outline="")
                canvas.create_oval(cx - metric(42), cy - metric(42), cx + metric(42), cy + metric(42), fill=face, outline=stroke, width=metric(1))
                canvas.create_oval(cx - metric(31), cy - metric(31), cx + metric(31), cy + metric(31), fill=field, outline=stroke, width=metric(1))
                canvas.create_arc(
                    cx - metric(43),
                    cy - metric(43),
                    cx + metric(43),
                    cy + metric(43),
                    start=225,
                    extent=-270,
                    style="arc",
                    width=metric(7),
                    outline=stroke,
                )
                canvas.create_arc(
                    cx - metric(43),
                    cy - metric(43),
                    cx + metric(43),
                    cy + metric(43),
                    start=225,
                    extent=-270 * norm,
                    style="arc",
                    width=metric(7),
                    outline=accent,
                )
                canvas.create_arc(
                    cx - metric(43),
                    cy - metric(43),
                    cx + metric(43),
                    cy + metric(43),
                    start=225 - (270 * max(0.0, norm - 0.08)),
                    extent=-270 * min(0.08, norm),
                    style="arc",
                    width=metric(7),
                    outline=warm,
                )
                for index in range(11):
                    tick_norm = index / 10
                    angle = math.radians(225 - 270 * tick_norm)
                    outer = radius + metric(10)
                    inner = radius + metric(5 if index in {0, 5, 10} else 7)
                    canvas.create_line(
                        cx + math.cos(angle) * inner,
                        cy - math.sin(angle) * inner,
                        cx + math.cos(angle) * outer,
                        cy - math.sin(angle) * outer,
                        fill=muted if index not in {0, 5, 10} else warm,
                        width=metric(1),
                    )
                angle = math.radians(225 - 270 * norm)
                canvas.create_line(
                    cx,
                    cy,
                    cx + math.cos(angle) * metric(27),
                    cy - math.sin(angle) * metric(27),
                    fill=warm,
                    width=metric(4),
                    capstyle="round",
                )
                canvas.create_oval(cx - metric(5), cy - metric(5), cx + metric(5), cy + metric(5), fill=accent, outline="")
                canvas.create_text(cx, cy + metric(20), text="GAIN", fill=muted, font=(BRAND_UI_FAMILY, type_scale.CAPTION, "bold"))
                canvas.create_text(cx, cy + metric(32), text=format_gain(value), fill=text, font=(BRAND_UI_FAMILY, type_scale.SECONDARY, "bold"))
                value_label.configure(text=f"{format_gain(value)} software gain")
                slider_sync["value"] = True
                try:
                    slider_var.set(norm)
                finally:
                    slider_sync["value"] = False

            def set_from_event(event: tk.Event) -> str:
                set_value(value_for_norm(norm_from_pointer(int(event.x), int(event.y))))
                return "break"

            def wheel(event: tk.Event) -> str:
                direction = 1 if int(getattr(event, "delta", 0)) > 0 or int(getattr(event, "num", 0)) == 4 else -1
                set_value(value_for_norm(norm_for_value(current_value()) + direction * 0.035))
                return "break"

            def nudge(delta: float) -> str:
                set_value(value_for_norm(norm_for_value(current_value()) + delta))
                return "break"

            def set_boundary(value: float) -> str:
                set_value(value)
                return "break"

            def set_from_slider(raw: str) -> None:
                if slider_sync["value"]:
                    return
                try:
                    norm = float(raw)
                except (TypeError, ValueError):
                    norm = float(slider_var.get())
                set_value(value_for_norm(norm))

            slider = ttk.Scale(
                holder,
                from_=0.0,
                to=1.0,
                orient="horizontal",
                variable=slider_var,
                command=set_from_slider,
                style="Flow.Horizontal.TScale",
                takefocus=True,
            )
            slider.grid(row=2, column=1, sticky="ew", pady=ui_scale.spacing((8, 0), self.config))
            slider.bind("<Left>", lambda _event: nudge(-0.035), add="+")
            slider.bind("<Down>", lambda _event: nudge(-0.035), add="+")
            slider.bind("<Right>", lambda _event: nudge(0.035), add="+")
            slider.bind("<Up>", lambda _event: nudge(0.035), add="+")
            slider.bind("<Prior>", lambda _event: nudge(0.12), add="+")
            slider.bind("<Next>", lambda _event: nudge(-0.12), add="+")
            slider.bind("<Home>", lambda _event: set_boundary(low), add="+")
            slider.bind("<End>", lambda _event: set_boundary(high), add="+")

            canvas.bind("<Button-1>", set_from_event)
            canvas.bind("<B1-Motion>", set_from_event)
            canvas.bind("<MouseWheel>", wheel)
            canvas.bind("<Button-4>", wheel)
            canvas.bind("<Button-5>", wheel)
            ttk.Button(holder, text="Reset", command=lambda: set_value(default), style="Flow.TButton").grid(
                row=0, column=2, rowspan=4, sticky="e", padx=ui_scale.spacing((12, 0), self.config)
            )
            variable.trace_add("write", lambda *_args: draw())
            theme_redraw_callbacks.append(draw)
            draw()
            return holder

        def text_box(parent: ttk.Frame, height: int, *, font: tuple[str, int] = (mac_support.FONT_MONO, type_scale.CAPTION)) -> tk.Text:
            widget = tk.Text(
                parent,
                height=height,
                wrap="word",
                font=font,
                bg=palette["field"],
                fg=palette["text"],
                insertbackground=palette["text"],
                selectbackground=palette["select"],
                bd=0,
                padx=ui_scale.spacing(12, self.config),
                pady=ui_scale.spacing(12, self.config),
            )
            leading.apply(widget)
            theme_text_widgets.append(widget)
            return widget

        deepgram = self.config.setdefault("deepgram", {})
        stt_config = self.config.setdefault("stt", {})
        cleanup = self.config.setdefault("cleanup", {})
        privacy = self.config.setdefault("privacy", {})
        dictation_config = self.config.setdefault("dictation", {})
        overlay_config = self.config.setdefault("overlay", {})
        updates_config = self.config.setdefault("updates", {})
        transforms = self.config.setdefault("transforms", {})
        ollama = transforms.setdefault("ollama", {})
        translation_config = self.config.setdefault("translation", {})

        theme_var = tk.StringVar(value=self._settings_theme_key(theme))
        header.bind("<Configure>", redraw_header)
        settings_header_close = self._close_control(
            window,
            header,
            palette["bg"],
            command=request_settings_close,
        )
        settings_header_close.place(
            relx=1.0,
            x=-ui_scale.px(12, self.config),
            y=ui_scale.px(18, self.config),
            anchor="ne",
            width=ui_scale.px(44, self.config),
            height=ui_scale.px(32, self.config),
        )
        settings_header_minimize = self._minimize_control(window, header, palette["bg"])
        settings_header_minimize.place(
            relx=1.0,
            x=-ui_scale.px(64, self.config),
            y=ui_scale.px(18, self.config),
            anchor="ne",
            width=ui_scale.px(84, self.config),
            height=ui_scale.px(32, self.config),
        )
        self._schedule_settings_header_animation(
            header,
            lambda: theme_var.get(),
            96,
            show_close=False,
        )

        key_var = tk.StringVar(value=str(deepgram.get("api_key", "")))
        model_var = tk.StringVar(value=str(deepgram.get("model", "nova-3")))
        language_var = tk.StringVar(value=str(deepgram.get("language", "en-US")))
        level_var = tk.StringVar(value=str(cleanup.get("level", "high")))
        # X-137 naming, settled: the two finishes are Chill and Executive.
        # Config keys stay standard/executive -- labels are the product.
        FORMAT_INTENSITY_LABELS = (
            ("standard", "Chill - your voice, tidied"),
            ("executive", "Executive - boardroom-ready rewrite"),
        )
        intensity_label_by_key = dict(FORMAT_INTENSITY_LABELS)
        intensity_key_by_label = {label: key for key, label in FORMAT_INTENSITY_LABELS}
        format_intensity_var = tk.StringVar(value=intensity_label_by_key.get(
            str(cleanup.get("format_intensity", "standard")).strip().lower(),
            intensity_label_by_key["standard"],
        ))
        save_history_var = tk.BooleanVar(value=bool(privacy.get("save_history", True)))
        play_sounds_var = tk.BooleanVar(value=bool(dictation_config.get("play_sounds", True)))
        auto_paste_var = tk.BooleanVar(value=bool(dictation_config.get("auto_paste", True)))
        smart_space_var = tk.BooleanVar(value=bool(dictation_config.get("smart_leading_space", True)))
        check_updates_on_start_var = tk.BooleanVar(value=bool(updates_config.get("check_on_start", True)))
        auto_download_updates_var = tk.BooleanVar(value=bool(updates_config.get("auto_download", False)))
        latest_version_var = tk.StringVar(value=str(updates_config.get("latest_version") or "not checked yet"))

        deepgram_model_options = [model.id for model in PROVIDER_BY_ID["deepgram"].models]

        active_provider_id = selected_provider_id(self.config)
        active_model_id = selected_model_id(self.config, active_provider_id)
        active_settings = provider_settings(self.config, active_provider_id)
        provider_holder = {"id": active_provider_id}

        stt_provider_var = tk.StringVar(value=provider_label(active_provider_id))
        stt_model_var = tk.StringVar(value=model_label(active_provider_id, active_model_id))
        stt_variant_var = tk.StringVar(value=selected_variant(self.config, active_provider_id))
        stt_key_var = tk.StringVar(value=str(active_settings.get("api_key", "")))
        def _visible_api_base(provider_id: str, settings: dict) -> str:
            # X-92: this field once printed our own service's hostname for the
            # retired managed route. Only the person's own provider (or a
            # local one) can be selected now, so its base is theirs to see.
            return str(settings.get("api_base") or PROVIDER_BY_ID[provider_id].api_base)

        stt_base_var = tk.StringVar(value=_visible_api_base(active_provider_id, active_settings))
        stt_key_label_var = tk.StringVar(value=PROVIDER_BY_ID[active_provider_id].key_label)
        stt_env_var = tk.StringVar(value=PROVIDER_BY_ID[active_provider_id].env_key or "No key required")
        stt_docs_var = tk.StringVar(value=str(PROVIDER_BY_ID[active_provider_id].docs_url or "Custom/local provider"))
        stt_capability_var = tk.StringVar(value=provider_capability_summary(active_provider_id, active_model_id))
        stt_status_var = tk.StringVar(value=self._provider_status_text(active_provider_id))
        stt_extra_text: tk.Text | None = None
        stt_model_detail_var = tk.StringVar()

        provider_lane_titles = {
            "local": "Local / on-device",
            "byok": "Bring your own",
        }

        def provider_lane_for(provider_id: str) -> str:
            if provider_id == "local":
                return "local"
            provider = PROVIDER_BY_ID.get(provider_id, PROVIDER_BY_ID["deepgram"])
            return "byok" if provider.api_kind != "external" else "local"

        initial_provider_lane = provider_lane_for(active_provider_id)
        provider_lane_var = tk.StringVar(value=initial_provider_lane)
        # A Radiobutton updates its Tk variable immediately before invoking its
        # command. Keep the committed lane separately so the command can still
        # tell whether it must preserve the provider fields being left behind.
        provider_lane_state = {"value": initial_provider_lane}

        def provider_ids_for_lane(lane: str) -> list[str]:
            ids: list[str] = []
            for provider_id, provider in PROVIDER_BY_ID.items():
                if lane == "local" and provider_id == "local":
                    ids.append(provider_id)
                elif lane == "byok" and provider_id != "local" and provider.api_kind != "external":
                    ids.append(provider_id)
            return ids or (["local"] if lane == "local" else ["deepgram"])

        def provider_labels_for_lane(lane: str | None = None) -> list[str]:
            return [provider_label(provider_id) for provider_id in provider_ids_for_lane(lane or provider_lane_var.get())]

        def provider_model_detail(provider_id: str, model_id: str) -> str:
            provider = PROVIDER_BY_ID.get(provider_id, PROVIDER_BY_ID["deepgram"])
            model = model_for_id(provider_id, model_id)
            status = self._provider_status_text(provider_id)
            notes = model.notes or provider.notes
            detail = f"{model.label}: {model.mode}"
            if model.open_weights:
                detail += " / open weights"
            if notes:
                detail += f". {notes}"
            if provider.api_kind == "external":
                detail += " This provider is not available in this build and will not replace your active route."
            else:
                detail += f" {status}"
            return detail

        stt_model_detail_var.set(provider_model_detail(active_provider_id, active_model_id))

        def remember_provider_fields(provider_id: str) -> None:
            settings = provider_settings(self.config, provider_id)
            settings["api_key"] = stt_key_var.get().strip()
            typed_base = stt_base_var.get().strip()
            if not typed_base.lower().startswith("managed by"):
                settings["api_base"] = typed_base
            settings["model"] = model_id_for_label(provider_id, stt_model_var.get())
            model = model_for_id(provider_id, settings["model"])
            settings["variant"] = stt_variant_var.get().strip() or model.variants[0]
            if stt_extra_text is not None:
                raw = stt_extra_text.get("1.0", "end-1c").strip()
                if not raw:
                    settings["extra"] = {}
                else:
                    try:
                        parsed = json.loads(raw)
                    except json.JSONDecodeError:
                        parsed = None
                    if isinstance(parsed, dict):
                        settings["extra"] = parsed

        def refresh_provider_fields(*, keep_model: bool = False) -> None:
            provider_id = provider_id_for_label(stt_provider_var.get())
            settings = provider_settings(self.config, provider_id)
            provider = PROVIDER_BY_ID[provider_id]
            current_model_id = str(settings.get("model") or provider.models[0].id)
            model_options_for_provider = model_labels(provider_id)
            stt_model_box.configure(values=model_options_for_provider)
            if not keep_model:
                stt_model_var.set(model_label(provider_id, current_model_id))
            chosen_model_id = model_id_for_label(provider_id, stt_model_var.get())
            chosen_model = model_for_id(provider_id, chosen_model_id)
            stt_variant_box.configure(values=list(chosen_model.variants))
            if stt_variant_var.get() not in chosen_model.variants:
                stt_variant_var.set(str(settings.get("variant") or chosen_model.variants[0]))
            if stt_variant_var.get() not in chosen_model.variants:
                stt_variant_var.set(chosen_model.variants[0])
            stt_key_var.set(str(settings.get("api_key", "")))
            stt_base_var.set(_visible_api_base(provider.id, settings))
            stt_key_label_var.set(provider.key_label)
            stt_env_var.set(provider.env_key or "No key required")
            stt_docs_var.set(str(provider.docs_url or "Custom/local provider"))
            stt_capability_var.set(provider_capability_summary(provider_id, chosen_model_id))
            stt_status_var.set(self._provider_status_text(provider_id))
            stt_model_detail_var.set(provider_model_detail(provider_id, chosen_model_id))
            if stt_extra_text is not None:
                stt_extra_text.delete("1.0", "end")
                stt_extra_text.insert("1.0", json.dumps(settings.get("extra", {}), indent=2, ensure_ascii=False))
            provider_holder["id"] = provider_id

        def on_provider_change(_event: tk.Event | None = None) -> None:
            remember_provider_fields(provider_holder["id"])
            refresh_provider_fields()

        def on_model_change(_event: tk.Event | None = None) -> None:
            provider_id = provider_id_for_label(stt_provider_var.get())
            chosen_model_id = model_id_for_label(provider_id, stt_model_var.get())
            chosen_model = model_for_id(provider_id, chosen_model_id)
            stt_variant_box.configure(values=list(chosen_model.variants))
            if stt_variant_var.get() not in chosen_model.variants:
                stt_variant_var.set(chosen_model.variants[0])
            stt_capability_var.set(provider_capability_summary(provider_id, chosen_model_id))
            stt_model_detail_var.set(provider_model_detail(provider_id, chosen_model_id))

        def open_stt_provider_link(kind: str) -> None:
            provider_id = provider_id_for_label(stt_provider_var.get())
            provider = PROVIDER_BY_ID.get(provider_id, PROVIDER_BY_ID["local"])
            url = {
                "login": provider.login_url,
                "keys": provider.api_keys_url,
                "docs": provider.docs_url,
            }.get(kind, "")
            if url:
                webbrowser.open(url)
            else:
                self.set_state("error", f"No {kind} link configured for {provider.label}.", "")

