        def local_active_model_id() -> str:
            settings = provider_settings(self.config, "local")
            return str(settings.get("model") or DEFAULT_LOCAL_MODEL_ID)

        def set_local_active(model: Any) -> None:
            settings = provider_settings(self.config, "local")
            settings["model"] = model.id
            settings["variant"] = "auto"
            # X-341, his order: choosing WHICH local model is not choosing
            # to GO local. This used to force provider="local" and yank the
            # whole provider lane over -- picking a model while on Cloud or
            # Auto silently rerouted every dictation. The route belongs to
            # the pill's switch alone; only when local is already the
            # active provider do the provider widgets need re-labelling.
            if str(self.config.get("stt", {}).get("provider", "local")) == "local":
                stt_model_var.set(model_label("local", model.id))
            refresh_provider_fields()
            callback = self.callbacks.get("save_settings")
            if callback:
                callback()
            local_status_var.set(
                f"Active local model: {model.label}. Saved. Your Cloud/Auto/Local route is unchanged."
            )
            self.set_state("captured", f"Local model set: {model.label}", "Local / On-Device is now active.")
            refresh_local_models()

        def start_local_download(model: Any) -> None:
            if model.id in self._local_model_downloads:
                return
            self._local_model_downloads.add(model.id)
            local_status_var.set(f"Downloading {model.label}...")
            refresh_local_models()

            def worker() -> None:
                error = ""
                try:
                    status_messages = {
                        "downloading_model": f"Downloading {model.label}...",
                        "loading_model": f"Loading {model.label}...",
                        "verifying_model": f"Verifying {model.label}...",
                        "model_ready": f"{model.label} is ready.",
                    }
                    download_local_model(
                        model,
                        lambda status: self._post_ui(
                            lambda value=status_messages.get(
                                status,
                                f"Preparing {model.label}...",
                            ): self._notify_current_local_model_download(
                                model.id,
                                value,
                            )
                        ),
                    )
                except Exception as exc:
                    error = str(exc) or exc.__class__.__name__

                def done() -> None:
                    self._local_model_downloads.discard(model.id)
                    if error:
                        # A 640 MB download failing is common enough -- a
                        # dropped connection, a full disk -- that the useful
                        # thing to say is that trying again is cheap. Hugging
                        # Face keeps the partial file and resumes with a Range
                        # request, so a retry does not start from zero. Without
                        # saying so, "failed" reads as "start the 640 MB again".
                        self._notify_current_local_model_download(
                            model.id,
                            f"Download failed: {error[:110]} "
                            "Choose Download again. It resumes from where it stopped.",
                            "error",
                        )
                    else:
                        self._notify_current_local_model_download(
                            model.id,
                            f"Downloaded {model.label}. You can use it now.",
                            "ready",
                        )

                self._post_ui(done)

            thread = threading.Thread(
                target=worker,
                name=f"TalkDatModelDL-{model.id}",
                daemon=True,
            )
            try:
                thread.start()
            except BaseException as exc:
                self._local_model_downloads.discard(model.id)
                error = str(exc) or exc.__class__.__name__
                self._notify_current_local_model_download(
                    model.id,
                    f"Download could not start: {error[:110]}. Choose Download to try again.",
                    "error",
                )

        def remove_local_model(model: Any) -> None:
            active_note = (
                "\n\nThis is the active local model. The next local dictation will need "
                "to download it again before it can run."
                if model.id == local_active_model_id()
                else ""
            )
            if not messagebox.askyesno(
                "Delete local model?",
                f"Delete {model.label} from {platform_copy.THIS_COMPUTER}?\n\n"
                f"This removes about {local_downloaded_size_mb(model) or model.size_mb} MB of "
                f"downloaded model data.{active_note}\n\n"
                "Recovery: choose Download beside this model to install it again.",
                icon="warning",
                default="no",
                parent=window,
            ):
                local_status_var.set(f"Kept {model.label}. Nothing was deleted.")
                return
            delete_local_model(model)
            local_status_var.set(f"Removed {model.label} from local storage.")
            refresh_local_models()

        custom_model_var = tk.StringVar(value="")

        def persist_local_settings() -> None:
            """Save through the host, which owns persistence.

            Not `save_config` directly: the host callback also re-reads
            credentials and reapplies the config to the running app, and every
            other settings write in this window already goes through it.
            """
            callback = self.callbacks.get("save_settings")
            if callable(callback):
                callback()


        catalog_style = ttk.Style(window)

        def repaint_local_catalog() -> None:
            catalog_style.configure(
                "Flow.Treeview",
                background=palette["field"],
                fieldbackground=palette["field"],
                foreground=palette["text"],
                bordercolor=palette["stroke"],
                lightcolor=palette["stroke"],
                darkcolor=palette["stroke"],
                rowheight=ui_scale.px(32, self.config),
                font=(BRAND_UI_FAMILY, type_scale.SECONDARY),
            )
            catalog_style.map(
                "Flow.Treeview",
                background=[("selected", palette["select"])],
                foreground=[("selected", palette["text"])],
            )
            catalog_style.configure(
                "Flow.Treeview.Heading",
                background=palette["button"],
                foreground=palette["text"],
                font=(BRAND_UI_FAMILY, type_scale.SECONDARY, "bold"),
                padding=ui_scale.spacing((8, 8), self.config),
            )
            live_trees: list[ttk.Treeview] = []
            for tree in tuple(local_model_build.get("trees", ())):
                try:
                    if tree.winfo_exists():
                        tree.tag_configure("active", foreground=palette["accent"])
                        live_trees.append(tree)
                except tk.TclError:
                    continue
            local_model_build["trees"] = live_trees

        theme_redraw_callbacks.append(repaint_local_catalog)

        def refresh_local_models() -> None:
            pending = local_model_build.get("after")
            if pending:
                with contextlib.suppress(tk.TclError):
                    window.after_cancel(pending)
            abandoned = local_model_build.get("building_stage")
            if abandoned is not None:
                with contextlib.suppress(tk.TclError):
                    abandoned.destroy()
            generation = int(local_model_build["generation"]) + 1
            local_model_build["generation"] = generation
            local_model_build["after"] = None
            local_model_build["ready"] = False
            active_id = local_active_model_id()
            models = tuple(available_local_models(self.config))
            previous_stage = local_model_build.get("stage")
            stage = tk.Frame(
                local_list,
                bg=palette["panel"],
                bd=0,
                highlightthickness=0,
            )
            stage.columnconfigure(0, weight=1)
            stage.grid(row=1, column=0, sticky="ew")
            # On first visit, grow the catalog in bounded visible batches
            # beneath a clear preparation label. Hiding every new row and then
            # mapping 100-plus controls at once only moved the freeze to the
            # reveal frame. Refreshes keep the complete old catalog visible and
            # swap atomically after the replacement is ready.
            if previous_stage is not None:
                stage.grid_remove()
            local_model_build["building_stage"] = stage
            local_loading.configure(text="Preparing the on-device model catalog...")
            local_loading.grid()
            progress = {"index": 0}

            repaint_local_catalog()
            catalog_shell = ttk.Frame(stage, style="Flow.TFrame")
            catalog_shell.grid(row=0, column=0, sticky="ew")
            catalog_shell.columnconfigure(0, weight=1)
            model_tree = ttk.Treeview(
                catalog_shell,
                columns=("languages", "size", "status"),
                show="tree headings",
                height=min(12, max(7, len(models))),
                selectmode="browse",
                style="Flow.Treeview",
                takefocus=True,
            )
            model_tree.heading("#0", text="Model", anchor="w")
            model_tree.heading("languages", text="Languages", anchor="w")
            model_tree.heading("size", text="Size", anchor="e")
            model_tree.heading("status", text="Status", anchor="w")
            model_tree.column("#0", width=310, minwidth=180, stretch=True, anchor="w")
            model_tree.column("languages", width=150, minwidth=90, stretch=True, anchor="w")
            model_tree.column("size", width=86, minwidth=70, stretch=False, anchor="e")
            model_tree.column("status", width=145, minwidth=105, stretch=False, anchor="w")
            model_tree.grid(row=0, column=0, sticky="ew")
            catalog_scroll = ttk.Scrollbar(
                catalog_shell,
                orient="vertical",
                command=model_tree.yview,
                style="Flow.Vertical.TScrollbar",
            )
            catalog_scroll.grid(row=0, column=1, sticky="ns")
            model_tree.configure(yscrollcommand=catalog_scroll.set)
            model_tree.tag_configure("active", foreground=palette["accent"])
            local_model_build["trees"] = [
                *tuple(local_model_build.get("trees", ())),
                model_tree,
            ]

            selected_detail_var = tk.StringVar(value="Select a model to see its route and storage state.")
            ttk.Label(
                stage,
                textvariable=selected_detail_var,
                style="Flow.Muted.TLabel",
                wraplength=ui_scale.px(820, self.config),
            ).grid(row=1, column=0, sticky="ew", pady=ui_scale.spacing((8, 0), self.config))
            model_actions = ttk.Frame(stage, style="Flow.TFrame")
            model_actions.grid(row=2, column=0, sticky="w", pady=ui_scale.spacing((12, 0), self.config))
            item_models: dict[str, Any] = {}
            active_item: dict[str, str] = {"id": ""}

            def selected_model() -> Any | None:
                selection = model_tree.selection()
                return item_models.get(selection[0]) if selection else None

            def use_selected_model() -> None:
                model = selected_model()
                if model is not None:
                    set_local_active(model)

            def manage_selected_model() -> None:
                model = selected_model()
                if model is None or model.id in self._local_model_downloads:
                    return
                if model.id.startswith(CUSTOM_MODEL_PREFIX):
                    remove_custom_model(model)
                elif local_model_downloaded(model):
                    remove_local_model(model)
                else:
                    start_local_download(model)

            use_model_button = ttk.Button(
                model_actions,
                text="Use selected model",
                command=use_selected_model,
                style="Flow.Accent.TButton",
            )
            use_model_button.pack(side="left", padx=ui_scale.spacing((0, 8), self.config))
            manage_model_button = ttk.Button(
                model_actions,
                text="Download selected",
                command=manage_selected_model,
                style="Flow.TButton",
            )
            manage_model_button.pack(side="left")

            def refresh_selected_actions(_event: tk.Event | None = None) -> None:
                model = selected_model()
                if model is None:
                    use_model_button.configure(state="disabled", text="Use selected model")
                    manage_model_button.configure(state="disabled", text="Manage selected")
                    return
                downloaded = local_model_downloaded(model)
                downloading = model.id in self._local_model_downloads
                is_active = model.id == active_id
                use_model_button.configure(
                    state="disabled" if is_active else "normal",
                    text="Active model" if is_active else "Use selected model",
                )
                if downloading:
                    manage_text = "Downloading..."
                    manage_state = "disabled"
                elif model.id.startswith(CUSTOM_MODEL_PREFIX):
                    manage_text = "Remove from list"
                    manage_state = "normal"
                elif downloaded:
                    manage_text = f"Delete from {platform_copy.THIS_COMPUTER}"
                    manage_state = "normal"
                else:
                    manage_text = "Download selected"
                    manage_state = "normal"
                manage_model_button.configure(state=manage_state, text=manage_text)
                note = f"{model.languages}. About {model.size_mb} MB."
                if model.notes:
                    note += f" {model.notes}"
                selected_detail_var.set(note)

            model_tree.bind("<<TreeviewSelect>>", refresh_selected_actions, add="+")
            model_tree.bind(
                "<Double-Button-1>",
                lambda _event: (use_selected_model(), "break")[1],
                add="+",
            )
            model_tree.bind(
                "<Return>",
                lambda _event: (use_selected_model(), "break")[1],
                add="+",
            )

            def add_model_row(row_index: int, model: Any) -> None:
                downloaded = local_model_downloaded(model)
                downloading = model.id in self._local_model_downloads
                status = (
                    "Downloading"
                    if downloading
                    else (f"Ready, {local_downloaded_size_mb(model)} MB" if downloaded else "Not downloaded")
                )
                item_id = f"model-{row_index}"
                item_models[item_id] = model
                model_tree.insert(
                    "",
                    "end",
                    iid=item_id,
                    text=model.label,
                    values=(model.languages, f"~{model.size_mb} MB", status),
                    tags=("active",) if model.id == active_id else (),
                )
                if model.id == active_id:
                    active_item["id"] = item_id

            def add_custom_row() -> None:
                adder = tk.Frame(stage, bg=palette["field"], highlightthickness=1,
                             highlightbackground=palette["stroke"])
                adder.grid(row=3, column=0, sticky="ew", pady=ui_scale.spacing((16, 4), self.config))
                adder.columnconfigure(0, weight=1)
                tk.Label(
                    adder, text="Add your own model", bg=palette["field"], fg=palette["text"],
                    font=(BRAND_UI_FAMILY, type_scale.SUBHEADING, "bold"), anchor="w",
                ).grid(row=0, column=0, sticky="ew", padx=ui_scale.spacing(12, self.config), pady=ui_scale.spacing((8, 0), self.config))
                tk.Label(
                    adder,
                    text="Paste a Hugging Face model id such as deepdml/faster-whisper-large-v3-turbo-ct2, "
                         "or the full path to a folder holding a converted model. Anything in "
                         "CTranslate2 Whisper format works. A model in another architecture needs "
                         "adding to the app, so send it to build@knightaiav.com and it can ship "
                         "as a built-in.",
                    bg=palette["field"], fg=palette["muted"], font=(BRAND_UI_FAMILY, type_scale.BODY), anchor="w",
                    wraplength=ui_scale.px(620, self.config), justify="left",
                ).grid(row=1, column=0, sticky="ew", padx=ui_scale.spacing(12, self.config), pady=ui_scale.spacing((0, 8), self.config))
                custom_entry = ttk.Entry(adder, textvariable=custom_model_var, width=48, style="Flow.TEntry")
                custom_entry.grid(row=2, column=0, sticky="ew", padx=ui_scale.spacing(12, self.config), pady=ui_scale.spacing((0, 12), self.config))
                custom_actions = tk.Frame(adder, bg=palette["field"])
                custom_actions.grid(row=0, column=1, rowspan=3, sticky="e", padx=ui_scale.spacing(12, self.config))
                ttk.Button(custom_actions, text="Add", command=add_custom_model,
                           style="Flow.TButton").pack(side="left")

            def retire_old_stage(old_stage: tk.Widget | None) -> None:
                if old_stage is None or old_stage is stage:
                    return
                children = list(getattr(old_stage, "children", {}).values())

                def retire_next() -> None:
                    if children:
                        child = children.pop()
                        with contextlib.suppress(tk.TclError):
                            child.destroy()
                        with contextlib.suppress(tk.TclError):
                            window.after(32, retire_next)
                        return
                    with contextlib.suppress(tk.TclError):
                        old_stage.destroy()

                with contextlib.suppress(tk.TclError):
                    window.after(32, retire_next)

            def finish_build() -> None:
                if generation != int(local_model_build["generation"]):
                    with contextlib.suppress(tk.TclError):
                        stage.destroy()
                    return
                add_custom_row()
                children = model_tree.get_children("")
                preferred = active_item["id"] or (str(children[0]) if children else "")
                if preferred:
                    model_tree.selection_set(preferred)
                    model_tree.focus(preferred)
                    model_tree.see(preferred)
                refresh_selected_actions()
                old_stage = local_model_build.get("stage")
                if old_stage is not None:
                    with contextlib.suppress(tk.TclError):
                        old_stage.grid_remove()
                    stage.grid()
                local_loading.grid_remove()
                local_model_build["stage"] = stage
                local_model_build["building_stage"] = None
                local_model_build["after"] = None
                local_model_build["ready"] = True
                retire_old_stage(old_stage)

            def schedule_next(delay_ms: int) -> None:
                """Arm the next batch after layout has yielded a real frame.

                Tk drains recursively queued idle callbacks inside one update.
                Two idle boundaries followed by a timer place the timer near
                the end of the current layout wave, rather than letting a slow
                wave make every nominal 16 ms batch immediately due.
                """

                def arm_timer() -> None:
                    local_model_build["after"] = window.after(delay_ms, build_next)

                def after_layout() -> None:
                    local_model_build["after"] = window.after_idle(arm_timer)

                local_model_build["after"] = window.after_idle(after_layout)

            def build_next() -> None:
                local_model_build["after"] = None
                try:
                    alive = bool(window.winfo_exists()) and not bool(
                        getattr(window, "_talkdat_close_requested", False)
                    )
                except tk.TclError:
                    alive = False
                if not alive or generation != int(local_model_build["generation"]):
                    with contextlib.suppress(tk.TclError):
                        stage.destroy()
                    return
                if bool(getattr(window, "_talkdat_live_resize", False)):
                    schedule_next(32)
                    return
                stop = min(len(models), progress["index"] + 6)
                while progress["index"] < stop:
                    index = progress["index"]
                    add_model_row(index, models[index])
                    progress["index"] += 1
                if progress["index"] < len(models):
                    schedule_next(32)
                    return
                finish_build()

            schedule_next(16)

        def ensure_local_models() -> None:
            if local_model_build.get("ready") or local_model_build.get("after"):
                return
            refresh_local_models()

        def handle_local_model_download_event(
            model_id: str,
            message: str,
            outcome: str,
        ) -> None:
            try:
                current = self.utility_windows.get("settings")
                alive = (
                    current is window
                    and bool(window.winfo_exists())
                    and not bool(getattr(window, "_talkdat_close_requested", False))
                )
            except tk.TclError:
                alive = False
            if not alive:
                return
            local_status_var.set(message)
            if not outcome:
                return
            model = next(
                (
                    candidate
                    for candidate in available_local_models(self.config)
                    if str(candidate.id) == str(model_id)
                ),
                None,
            )
            label = str(getattr(model, "label", model_id))
            if outcome == "error":
                failure_title = (
                    f"Could not download {model.label}."
                    if model is not None
                    else f"Could not download {label}."
                )
                self.set_state(
                    "error",
                    failure_title,
                    "Choose Download again. It resumes from where it stopped, "
                    "so existing partial data is kept for the retry.",
                )
            else:
                self.set_state("captured", f"{label} downloaded and ready.", "")
            refresh_local_models()

        window._talkdat_local_model_download_event = (  # type: ignore[attr-defined]
            handle_local_model_download_event
        )

        def add_custom_model() -> None:
            """Validate before storing, so a typo is caught here rather than on
            the first dictation with the microphone already open."""
            reference = custom_model_var.get().strip()
            if not reference:
                return
            model = custom_model_from(reference)
            if model is None:
                local_status_var.set(
                    f"That is not a Hugging Face model id or a folder on {platform_copy.THIS_COMPUTER}. "
                    "Use owner/name, or the full path to a converted model folder."
                )
                return
            local_settings = self.config.setdefault("stt", {}).setdefault(
                "providers", {}).setdefault("local", {})
            existing = local_settings.get("custom_models")
            if not isinstance(existing, list):
                existing = []
            if any(str(e.get("id") if isinstance(e, dict) else e).strip() == reference
                   for e in existing):
                local_status_var.set(f"{reference} is already in the list.")
                return
            existing.append(reference)
            local_settings["custom_models"] = existing
            persist_local_settings()
            custom_model_var.set("")
            local_status_var.set(
                f"Added {model.label}. Choose Use to dictate with it; it downloads on first use."
            )
            refresh_local_models()

        def remove_custom_model(model: Any) -> None:
            if not messagebox.askyesno(
                "Remove custom model?",
                f"Remove {model.label} from the Talk DAT! model list?\n\n"
                "The model's source files are not deleted. Add the same Hugging Face id "
                "or folder path again to restore it to this list.",
                icon="warning",
                default="no",
                parent=window,
            ):
                local_status_var.set(f"Kept {model.label} in your model list.")
                return
            local_settings = self.config.setdefault("stt", {}).setdefault(
                "providers", {}).setdefault("local", {})
            entries = local_settings.get("custom_models")
            if not isinstance(entries, list):
                return
            reference = model.engine_id
            local_settings["custom_models"] = [
                e for e in entries
                if str(e.get("id") if isinstance(e, dict) else e).strip() != reference
            ]
            persist_local_settings()
            local_status_var.set(f"Removed {model.label} from your list.")
            refresh_local_models()

        lazy_page_loaders["speech"] = ensure_local_models

        add_row(core_tab, 2, "Active brand", ttk.Label(core_tab, textvariable=stt_provider_var, style="Flow.TLabel"))
        add_row(core_tab, 3, "Active model", ttk.Label(core_tab, textvariable=stt_model_var, style="Flow.TLabel"))
        add_row(core_tab, 4, "Language", entry(core_tab, language_var, 20))
        add_row(core_tab, 5, "Auto Cleanup", combo(core_tab, level_var, ["none", "light", "medium", "high"], 20))
        # X-143, his spec: the finish is a SWITCH on the page, not a form row
        # in a menu's clothing. Two clear sides, both labeled, the active one
        # visibly on -- the same control language as the pill menu's pinned
        # switches. format_intensity_var still carries the value into save().
        finish_holder = tk.Frame(core_tab, bg=palette["panel"], bd=0, highlightthickness=0)
        finish_holder.grid(row=1, column=0, columnspan=2, sticky="ew", pady=ui_scale.spacing((0, 12), self.config))
        finish_holder.columnconfigure(0, weight=1)
        finish_holder.columnconfigure(1, weight=1)
        finish_choice_var = tk.StringVar(
            value=intensity_key_by_label.get(format_intensity_var.get(), "standard")
        )
        finish_buttons: dict[str, tk.Radiobutton] = {}

        def refresh_finish_switch() -> None:
            current = intensity_key_by_label.get(format_intensity_var.get(), "standard")
            finish_choice_var.set(current)
            for key, button in finish_buttons.items():
                active = key == current
                button.configure(
                    bg=palette["select"] if active else palette["field"],
                    fg=palette["warm"] if active else palette["muted"],
                    activebackground=palette["select"],
                    activeforeground=palette["text"],
                    selectcolor=palette["select"],
                    relief="sunken" if active else "flat",
                    highlightbackground=palette["accent"] if active else palette["stroke"],
                )
                self._set_button_icon(
                    button,
                    "chill" if key == "standard" else "executive",
                    size=ui_scale.px(24, self.config),
                    primary=palette["warm"] if active else palette["muted"],
                    detail=palette["text"] if active else palette["muted"],
                    compound="left",
                )

        def pick_finish(key: str) -> None:
            format_intensity_var.set(intensity_label_by_key[key])
            refresh_finish_switch()

        for column, (key, label_text, sub_text) in enumerate(
            (("standard", "Chill", "your voice, tidied"), ("executive", "Executive", "boardroom-ready"))
        ):
            # This is an exclusive choice, so expose a real Radiobutton role.
            # indicatoron=False keeps the existing two-segment visual hierarchy
            # while Windows accessibility APIs can still identify the group.
            button = tk.Radiobutton(
                finish_holder,
                text=f"{label_text}\n{sub_text}",
                value=key,
                variable=finish_choice_var,
                command=lambda choice=key: pick_finish(choice),
                indicatoron=False,
                bd=0,
                highlightthickness=1,
                highlightbackground=palette["stroke"],
                highlightcolor=palette["warm"],
                takefocus=1,
                cursor="hand2",
                font=(BRAND_UI_FAMILY, type_scale.BODY, "bold"),
                justify="center",
                pady=ui_scale.spacing(8, self.config),
                offrelief="flat",
                overrelief="flat",
            )
            button.bind("<Return>", lambda _event, target=button: (target.invoke(), "break")[-1], add="+")
            button.bind(
                "<FocusIn>",
                lambda _event, target=button: target.configure(
                    highlightthickness=ui_scale.px(2, self.config)
                ),
                add="+",
            )
            button.bind(
                "<FocusOut>",
                lambda _event, target=button: target.configure(highlightthickness=1),
                add="+",
            )
            button.grid(
                row=0,
                column=column,
                sticky="ew",
                padx=ui_scale.spacing((0, 4) if column == 0 else (4, 0), self.config),
            )
            finish_buttons[key] = button
        finish_order = list(finish_buttons.values())
        for index, button in enumerate(finish_order):
            button.bind(
                "<Left>",
                lambda _event, target=finish_order[(index - 1) % len(finish_order)]: (target.focus_set(), "break")[-1],
                add="+",
            )
            button.bind(
                "<Right>",
                lambda _event, target=finish_order[(index + 1) % len(finish_order)]: (target.focus_set(), "break")[-1],
                add="+",
            )
        refresh_finish_switch()
        # X-145: repaint the switch when the theme changes underneath it.
        theme_redraw_callbacks.append(refresh_finish_switch)
        # A readonly combobox cannot colour its rows, so fifty themes read as
        # fifty identical lines of text and the list was not obviously long
        # enough to scroll. Each row is now painted in the theme it names.
        theme_holder = ttk.Frame(core_tab, style="Flow.TFrame")
        # This button carried no colours at all. On Windows a bare tk.Button is
        # a light face with black text and reads fine; on macOS it inherits
        # systemWindowBackgroundColor with black text, which inside the dark
        # settings window is black on near-black -- the control that opens the
        # theme list was itself unreadable. Every other control here is painted,
        # so this one is now too.
        _theme_palette = self._settings_palette(self._settings_theme_key())
        theme_button = FlatButton(
            theme_holder,
            textvariable=theme_var,
            anchor="w",
            relief="flat",
            bd=0,
            padx=ui_scale.spacing(12, self.config),
            pady=ui_scale.spacing(8, self.config),
            cursor="hand2",
            font=(BRAND_UI_FAMILY, type_scale.BODY),
            command=lambda: self._open_theme_picker(theme_button, theme_var),
        )
        theme_button.pack(side="left", fill="x", expand=True)
        ttk.Label(
            theme_holder,
            text=f"  {len(SETTINGS_THEME_FAMILIES)} themes, light and dark",
            style="Flow.Muted.TLabel",
        ).pack(side="left")
        # X-145, his ruling: color lives in ONE place -- the Colors tab,
        # where every theme is painted as itself. The General-tab picker row
        # was the same feature twice; the holder is built (widgets and var
        # wiring intact) but never gridded.

        # THE COLORS TAB (X-145: "make each bar the color of the color";
        # X-337: the color is the MATERIAL, not the near-black bg token).
        # Every theme, always visible, painted as itself. Clicking a row
        # applies the theme live through the same theme_var trace the
        # picker uses.
        colors_section = section(colors_page, "Theme")
        colors_section.columnconfigure(0, weight=1)
        # X-337, his refinement of X-145: the bg token painted every dark
        # bar the same near-black. Each row is now the theme's MATERIAL --
        # its select token tinted toward its accent, so Roman Clay reads as
        # clay -- with the ink chosen by measured contrast and a stipple
        # grain for tooth. One canvas replaces fifty buttons, which also
        # retires the staged reveal the button count used to need.
        # X-458, his verdict on the bars: "These are UGLY for color bars...
        # we NEED a redesign." The pattern every serious theme picker uses
        # (macOS Appearance, Slack Themes, Windows Personalization, the iOS
        # wallpaper picker): a thumbnail of the REAL UI per choice, in a
        # grid, the name UNDER the thumbnail and never over it, a selection
        # ring, and light/dark as one control rather than a doubled list.
        # One tile per family, each tile the material photograph with the
        # app's own caption strip and pill drawn in that palette's tokens.
        gallery_families = tuple(SETTINGS_THEME_FAMILIES)
        gallery_modes = ("Dark", "Light")

        def gallery_mode() -> str:
            _family, _, mode = theme_var.get().rpartition(" ")
            return mode if mode in gallery_modes else "Dark"

        def gallery_family() -> str:
            family, _, _mode = theme_var.get().rpartition(" ")
            return family if family in gallery_families else gallery_families[0]

        # The option strings for the CURRENT mode, so the keyboard path
        # applies "<family> <mode>" exactly as the popup picker would.
        gallery_options: list[str] = [f"{family} {gallery_mode()}" for family in gallery_families]
        gallery_gap = ui_scale.px(14, self.config)
        gallery_cols = 5
        gallery_state: dict[str, Any] = {
            "built": False, "focus": -1, "hover": -1, "after": None,
            "rects": [], "mode_rects": [], "height": 0,
        }
        gallery = tk.Canvas(
            colors_section,
            bg=palette["panel"],
            bd=0,
            highlightthickness=0,
            height=ui_scale.px(120, self.config),
            cursor="hand2",
            takefocus=1,
        )
        gallery.grid(row=0, column=0, sticky="ew", pady=ui_scale.spacing((4, 8), self.config))
        gallery_name_font = tkfont.Font(
            root=gallery, family=BRAND_UI_FAMILY, size=type_scale.BODY, weight="normal",
        )
        gallery_name_font_bold = tkfont.Font(
            root=gallery, family=BRAND_UI_FAMILY, size=type_scale.BODY, weight="bold",
        )
        gallery_group_font = tkfont.Font(
            root=gallery, family=BRAND_UI_FAMILY, size=max(8, type_scale.BODY - 2), weight="bold",
        )

        # X-352, his rule: visual assets are IMAGE-GENERATED and then
        # edited to fit -- never hand-coded. Each tile's backdrop is a crop
        # of the generated material photograph (Codex-seat image gen ->
        # scripts/grade_material_textures.py) at the tile's own aspect, and
        # the app's caption strip and pill are drawn over it in the
        # palette's tokens. The flat material survives only as the fallback
        # for a missing file.
        material_image_cache: dict[str, Any] = {}
        material_photo_cache: dict[tuple[str, str, int, int], Any] = {}

        def material_image(slug: str, mode: str) -> Any | None:
            raw_key = f"{slug}-{mode.lower()}"
            image = material_image_cache.get(raw_key)
            if image is None:
                filename = f"{raw_key}.png"
                path = Path(__file__).resolve().parent / "assets" / "materials" / filename
                if not path.is_file():
                    bundle_root = getattr(sys, "_MEIPASS", "")
                    if bundle_root:
                        path = Path(bundle_root) / "knight_flow" / "assets" / "materials" / filename
                if not path.is_file():
                    material_image_cache[raw_key] = False
                    return None
                try:
                    image = Image.open(path).convert("RGB")
                except Exception:
                    material_image_cache[raw_key] = False
                    return None
                material_image_cache[raw_key] = image
            return None if image is False else image

        def material_tile_photo(family: str, mode: str, width: int, height: int) -> Any | None:
            """The tile: the material at the tile's aspect, the app drawn on it."""
            key = (family, mode, width, height)
            photo = material_photo_cache.get(key)
            if photo is not None:
                return photo
            pal = SETTINGS_THEME_PALETTES.get(family, {}).get(mode)
            if not pal or width < 8 or height < 8:
                return None
            slug = family.lower().replace(" ", "-")
            source = material_image(slug, mode)
            try:
                if source is not None:
                    sw, sh = source.size
                    factor = max(width / sw, height / sh)
                    scaled = source.resize((max(1, round(sw * factor)), max(1, round(sh * factor))), Image.LANCZOS)
                    left = (scaled.width - width) // 2
                    top = (scaled.height - height) // 2
                    tile = scaled.crop((left, top, left + width, top + height))
                else:
                    tile = Image.new("RGB", (width, height), theme_material(pal, mode))
                draw = ImageDraw.Draw(tile, "RGBA")
                # the caption strip: the app's panel with two lines of its own ink
                strip_w, strip_h = int(width * 0.62), int(height * 0.34)
                sx, sy = (width - strip_w) // 2, int(height * 0.20)
                radius = max(3, height // 18)
                draw.rounded_rectangle((sx, sy, sx + strip_w, sy + strip_h), radius=radius, fill=pal["panel"])
                draw.rounded_rectangle((sx, sy, sx + strip_w, sy + strip_h), radius=radius, outline=pal["stroke"], width=1)
                pad = max(4, width // 22)
                line_h = max(2, height // 26)
                draw.rounded_rectangle((sx + pad, sy + pad, sx + strip_w - pad, sy + pad + line_h), radius=1, fill=pal["text"])
                draw.rounded_rectangle((sx + pad, sy + 2 * pad + line_h, sx + int(strip_w * 0.62), sy + 2 * pad + 2 * line_h), radius=1, fill=pal["muted"])
                # the pill under it, in the accent, with the mic dot in the bg ink
                pw, ph = int(width * 0.30), max(6, int(height * 0.15))
                px, py = (width - pw) // 2, sy + strip_h + max(4, height // 14)
                draw.rounded_rectangle((px, py, px + pw, py + ph), radius=ph // 2, fill=pal["accent"])
                dot = max(2, ph // 3)
                cx, cy = px + pw // 2, py + ph // 2
                draw.ellipse((cx - dot // 2, cy - dot // 2, cx + dot // 2, cy + dot // 2), fill=pal["bg"])
                # rounded corners, so the tile reads as a card on the panel
                mask = Image.new("L", (width, height), 0)
                ImageDraw.Draw(mask).rounded_rectangle((0, 0, width - 1, height - 1), radius=max(6, height // 11), fill=255)
                card = Image.new("RGB", (width, height), palette["panel"])
                card.paste(tile, (0, 0), mask)
                photo = ImageTk.PhotoImage(card)
            except Exception:
                return None
            if len(material_photo_cache) > 120:
                material_photo_cache.pop(next(iter(material_photo_cache)), None)
            material_photo_cache[key] = photo
            return photo

        def draw_gallery(*_args: object) -> None:
            if not gallery_state["built"]:
                return
            try:
                width = int(gallery.winfo_width())
            except tk.TclError:
                return
            if width <= 2:
                return
            gallery.delete("all")
            mode = gallery_mode()
            gallery_options[:] = [f"{family} {mode}" for family in gallery_families]
            current_family = gallery_family()
            tile_w = max(40, (width - (gallery_cols - 1) * gallery_gap) // gallery_cols)
            tile_h = int(tile_w * 0.62)
            name_h = gallery_name_font.metrics("linespace")
            group_h = gallery_group_font.metrics("linespace")
            pad_y = ui_scale.px(6, self.config)
            rects: list[tuple[int, int, int, int]] = []
            mode_rects: list[tuple[str, int, int, int, int]] = []

            # Dark | Light: one control at the top, drawn as two chips.
            y = 0
            chip_h = ui_scale.px(30, self.config)
            chip_pad = ui_scale.px(16, self.config)
            x = 0
            for option in gallery_modes:
                on = option == mode
                text_w = gallery_name_font_bold.measure(option)
                x1 = x + text_w + 2 * chip_pad
                gallery.create_rectangle(
                    x, y, x1, y + chip_h,
                    fill=palette["select"] if on else palette["field"],
                    outline=palette["accent"] if on else palette["stroke"],
                )
                gallery.create_text(
                    x + chip_pad, y + chip_h // 2, text=option, anchor="w",
                    fill=palette["text"] if on else palette["muted"],
                    font=gallery_name_font_bold if on else gallery_name_font,
                )
                mode_rects.append((option, x, y, x1, y + chip_h))
                x = x1 + ui_scale.px(8, self.config)
            gallery.create_text(
                x + ui_scale.px(6, self.config), y + chip_h // 2, anchor="w",
                text=f"{len(gallery_families)} materials. The tile is the app in that material.",
                fill=palette["muted"], font=gallery_name_font,
            )
            y += chip_h + ui_scale.px(18, self.config)

            index = 0
            for group, members in SETTINGS_THEME_GROUPS:
                gallery.create_text(0, y, text=group.upper(), anchor="nw", fill=palette["muted"], font=gallery_group_font)
                rule_x = gallery_group_font.measure(group.upper()) + ui_scale.px(10, self.config)
                gallery.create_line(rule_x, y + group_h // 2, width, y + group_h // 2, fill=palette["stroke"])
                y += group_h + pad_y
                row_top = y
                for column, family in enumerate(members):
                    if family not in gallery_families:
                        continue
                    pal = SETTINGS_THEME_PALETTES.get(family, {}).get(mode)
                    if not pal:
                        continue
                    if column and column % gallery_cols == 0:
                        row_top += tile_h + name_h + pad_y * 3
                    tx = (column % gallery_cols) * (tile_w + gallery_gap)
                    ty = row_top
                    texture = material_tile_photo(family, mode, tile_w, tile_h)
                    if texture is not None:
                        gallery.create_image(tx, ty, image=texture, anchor="nw")
                    else:
                        material = theme_material(pal, mode)
                        gallery.create_rectangle(tx, ty, tx + tile_w, ty + tile_h, fill=material, outline="")
                        gallery.create_rectangle(
                            tx, ty, tx + tile_w, ty + tile_h,
                            fill=material_grain(material, mode), outline="", stipple="gray12",
                        )
                    chosen = family == current_family
                    hovered = index == gallery_state["hover"]
                    if chosen:
                        gallery.create_rectangle(tx + 1, ty + 1, tx + tile_w - 2, ty + tile_h - 2,
                                                 outline=pal["accent"], width=3)
                        badge = ui_scale.px(11, self.config)
                        bx, by = tx + tile_w - badge - ui_scale.px(8, self.config), ty + badge + ui_scale.px(8, self.config)
                        gallery.create_oval(bx - badge, by - badge, bx + badge, by + badge, fill=pal["accent"], outline="")
                        gallery.create_text(bx, by, text="\u2713", fill=pal["bg"], font=gallery_name_font_bold)
                    elif hovered:
                        gallery.create_rectangle(tx + 1, ty + 1, tx + tile_w - 2, ty + tile_h - 2,
                                                 outline=palette["text"], width=2)
                    if index == gallery_state["focus"]:
                        gallery.create_rectangle(tx + 4, ty + 4, tx + tile_w - 5, ty + tile_h - 5,
                                                 outline=palette["text"], width=1, dash=(2, 2))
                    # The name lives UNDER the tile, in the page's own ink;
                    # it never sits on the photograph again.
                    gallery.create_text(
                        tx + 2, ty + tile_h + pad_y, text=family, anchor="nw",
                        fill=palette["text"] if (chosen or hovered) else palette["muted"],
                        font=gallery_name_font_bold if chosen else gallery_name_font,
                    )
                    if chosen:
                        gallery.create_text(
                            tx + 2 + gallery_name_font_bold.measure(family) + ui_scale.px(8, self.config),
                            ty + tile_h + pad_y, text="current", anchor="nw",
                            fill=pal["accent"], font=gallery_group_font,
                        )
                    rects.append((tx, ty, tx + tile_w, ty + tile_h + name_h + pad_y))
                    index += 1
                y = row_top + tile_h + name_h + pad_y * 4
            gallery_state["rects"] = rects
            gallery_state["mode_rects"] = mode_rects
            total = y + pad_y
            if total != gallery_state["height"]:
                gallery_state["height"] = total
                with contextlib.suppress(tk.TclError):
                    gallery.configure(height=total)

        def gallery_index_at(x: int, y: int) -> int:
            for index, (x0, y0, x1, y1) in enumerate(gallery_state["rects"]):
                if x0 <= x <= x1 and y0 <= y <= y1:
                    return index
            return -1

        def gallery_mode_at(x: int, y: int) -> str | None:
            for option, x0, y0, x1, y1 in gallery_state["mode_rects"]:
                if x0 <= x <= x1 and y0 <= y <= y1:
                    return option
            return None

        def reveal_gallery_row(index: int) -> None:
            """Keep keyboard focus inside the visible Colors viewport."""
            outer = page_outers.get("Colors")
            canvas = getattr(outer, "_scroll_canvas", None) if outer is not None else None
            if canvas is None or index < 0 or index >= len(gallery_state["rects"]):
                return
            try:
                canvas.update_idletasks()
                region = canvas.bbox("all")
                if not region or region[3] <= region[1]:
                    return
                _x0, tile_top, _x1, tile_bottom = gallery_state["rects"][index]
                content_y = gallery.winfo_rooty() - colors_page.winfo_rooty() + tile_top
                item_bottom = content_y + (tile_bottom - tile_top)
                view_top = float(canvas.canvasy(0))
                view_bottom = view_top + canvas.winfo_height()
                if content_y < view_top:
                    target = content_y
                elif item_bottom > view_bottom:
                    target = item_bottom - canvas.winfo_height()
                else:
                    return
                span = max(1.0, float(region[3] - region[1]))
                canvas.yview_moveto(max(0.0, min(1.0, target / span)))
            except tk.TclError:
                return

        def gallery_click(event: tk.Event) -> str:
            mode = gallery_mode_at(event.x, event.y)
            if mode is not None:
                # The mode control re-applies the CURRENT family in the other
                # mode, live, through the same trace as any pick.
                gallery.focus_set()
                theme_var.set(f"{gallery_family()} {mode}")
                return "break"
            index = gallery_index_at(event.x, event.y)
            if 0 <= index < len(gallery_options):
                gallery_state["focus"] = index
                gallery.focus_set()
                theme_var.set(gallery_options[index])
            return "break"

        def gallery_motion(event: tk.Event) -> None:
            index = gallery_index_at(event.x, event.y)
            if index != gallery_state["hover"]:
                gallery_state["hover"] = index
                draw_gallery()

        def gallery_leave(_event: tk.Event | None = None) -> None:
            if gallery_state["hover"] != -1:
                gallery_state["hover"] = -1
                draw_gallery()

        def gallery_move_focus(delta: int) -> str:
            if not gallery_options:
                return "break"
            index = gallery_state["focus"]
            if index < 0:
                try:
                    index = gallery_options.index(theme_var.get())
                except ValueError:
                    index = 0
            else:
                index = (index + delta) % len(gallery_options)
            gallery_state["focus"] = index
            reveal_gallery_row(index)
            draw_gallery()
            return "break"

        def gallery_apply_focus(_event: tk.Event | None = None) -> str:
            index = gallery_state["focus"]
            if 0 <= index < len(gallery_options):
                theme_var.set(gallery_options[index])
            return "break"

        def gallery_focus_in(_event: tk.Event | None = None) -> None:
            if gallery_state["focus"] < 0:
                try:
                    gallery_state["focus"] = gallery_options.index(theme_var.get())
                except ValueError:
                    gallery_state["focus"] = 0
            draw_gallery()

        def gallery_focus_out(_event: tk.Event | None = None) -> None:
            gallery_state["focus"] = -1
            draw_gallery()

        def gallery_configure(_event: tk.Event | None = None) -> None:
            if gallery_state["after"] is not None:
                return

            def redraw() -> None:
                gallery_state["after"] = None
                draw_gallery()

            with contextlib.suppress(tk.TclError):
                gallery_state["after"] = window.after_idle(redraw)

        gallery.bind("<Button-1>", gallery_click)
        gallery.bind("<Motion>", gallery_motion, add="+")
        gallery.bind("<Leave>", gallery_leave, add="+")
        # Arrows walk the grid: Left/Right by one tile, Up/Down by a row.
        gallery.bind("<Left>", lambda _e: gallery_move_focus(-1))
        gallery.bind("<Right>", lambda _e: gallery_move_focus(1))
        gallery.bind("<Up>", lambda _e: gallery_move_focus(-gallery_cols))
        gallery.bind("<Down>", lambda _e: gallery_move_focus(gallery_cols))
        gallery.bind("<Return>", gallery_apply_focus)
        gallery.bind("<space>", gallery_apply_focus)
        gallery.bind("<FocusIn>", gallery_focus_in, add="+")
        gallery.bind("<FocusOut>", gallery_focus_out, add="+")
        gallery.bind("<Configure>", gallery_configure, add="+")
        theme_var.trace_add("write", draw_gallery)

        def build_gallery() -> None:
            if gallery_state["built"]:
                return
            gallery_state["built"] = True
            draw_gallery()

