        # X-120, his order: pre-packaged industry vocabulary. Curated packs
        # ship as assets (military, medical, legal, aviation -- 1,400 terms,
        # domain-reviewed); one click drops a whole profession's spelling
        # into the dictionary, deduplicated against what is already there.
        def add_industry_pack(slug: str, title: str) -> None:
            try:
                import json as _json
                from pathlib import Path as _Path

                pack = _json.loads((_Path(__file__).resolve().parent / "assets" / "vocab_packs" / f"{slug}.json").read_text(encoding="utf-8"))
                existing = {line.strip().lower() for line in words_text.get("1.0", "end-1c").splitlines() if line.strip()}
                fresh = [term for term in pack.get("terms", []) if term.strip() and term.strip().lower() not in existing]
                if not fresh:
                    self.set_state("captured", f"{title}: every term is already in your dictionary.", "")
                    return
                words_text.insert("end", ("" if not existing else chr(10)) + chr(10).join(fresh))
                mark_dirty()
                self.set_state("captured", f"Added {len(fresh)} {title} terms to your dictionary.", "Save happens automatically.")
            except Exception as exc:
                self.set_state("error", f"Could not add the {title} pack: {exc}")

