        def arrange_footer_actions(event: tk.Event | None = None) -> None:
            available = int(event.width) if event is not None else footer_actions.winfo_width()
            if available <= 1:
                # Not laid out yet. Retry on a TIMER, never after_idle: an idle
                # callback that re-arms itself runs again inside the same
                # update() pass, and on Aqua an unmapped frame reports width 1
                # indefinitely, so the idle queue never drained and update()
                # never returned -- Settings "opened" and every test after it
                # hung at 100% CPU. <Configure> re-enters here with the real
                # width the moment the footer is mapped.
                try:
                    if footer_actions.winfo_exists():
                        window.after(50, arrange_footer_actions)
                except tk.TclError:
                    pass
                return
            required = (
                footer_workflow_actions.winfo_reqwidth()
                + footer_window_actions.winfo_reqwidth()
                + ui_scale.px(24, self.config)
            )
            mode = "two-row" if available < required else "one-row"
            if footer_layout["mode"] == mode:
                return
            footer_layout["mode"] = mode
            footer_workflow_actions.grid_forget()
            footer_window_actions.grid_forget()
            if mode == "two-row":
                footer_workflow_actions.grid(
                    row=0,
                    column=0,
                    columnspan=2,
                    sticky="w",
                )
                footer_window_actions.grid(
                    row=1,
                    column=0,
                    columnspan=2,
                    sticky="e",
                    pady=ui_scale.spacing((8, 0), self.config),
                )
            else:
                footer_workflow_actions.grid(row=0, column=0, sticky="w")
                footer_window_actions.grid(row=0, column=1, sticky="e")
            footer_actions._talkdat_layout_mode = mode  # type: ignore[attr-defined]

        footer_actions.bind("<Configure>", arrange_footer_actions, add="+")
        footer_actions._talkdat_workflow_actions = footer_workflow_actions  # type: ignore[attr-defined]
        footer_actions._talkdat_window_actions = footer_window_actions  # type: ignore[attr-defined]
        window.after_idle(arrange_footer_actions)
